const PAGES={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONのサポート、プライバシーポリシー、利用規約\"><title>MEFRION｜サポート</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\" aria-current=\"page\">サポート</a><a href=\"/privacy.html\">プライバシー</a><a href=\"/terms.html\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">HELP &amp; INFO</div><h1>困ったときは、ここから。</h1><p>MEFRIONの使い方やデータの扱いについてご案内します。</p></section><div class=\"notice\">MEFRIONの使い方と、写真やアカウント情報の取り扱いをご案内します。</div><div class=\"cards\"><a class=\"card\" href=\"/privacy.html\"><div class=\"icon\">🔒</div><h2>プライバシー</h2><p>写真やアカウント情報の扱いを確認できます。</p></a><a class=\"card\" href=\"/terms.html\"><div class=\"icon\">📝</div><h2>利用規約</h2><p>投稿や家族アルバムのルールを確認できます。</p></a><a class=\"card\" href=\"mailto:mefrion@mefrion.com?subject=MEFRION%E3%81%AE%E3%81%8A%E5%95%8F%E3%81%84%E5%90%88%E3%82%8F%E3%81%9B\"><div class=\"icon\">💌</div><h2>お問い合わせ</h2><p>不具合・通報・データに関する相談をメールで受け付けます。</p></a></div><section class=\"paper\"><h2>よくある質問</h2><div class=\"faq\"><h3>アカウントを削除したい</h3><p>アプリの「マイページ」→「アカウントを削除する」から手続きできます。ログインできない場合は下記のメールへご連絡ください。</p></div><div class=\"faq\"><h3>投稿やアカウントを通報したい</h3><p>アプリ内の通報メニューをご利用ください。利用できない場合は、対象の画面と状況をメールでお知らせください。</p></div><div class=\"faq\"><h3>家族アルバムの写真は公開されますか？</h3><p>アルバムの写真は初期状態で非公開です。公開投稿などの操作は、別途ご自身で選ぶ必要があります。</p></div><a class=\"button\" href=\"mailto:mefrion@mefrion.com?subject=MEFRION%E3%81%AE%E3%81%8A%E5%95%8F%E3%81%84%E5%90%88%E3%82%8F%E3%81%9B\">メールで問い合わせる</a><p class=\"mini\" style=\"margin-top:12px\">宛先：mefrion@mefrion.com。パスワードや確認コードは送らないでください。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/privacy.html\">プライバシー</a> · <a href=\"/terms.html\">利用規約</a></span></div></footer></body></html>\n"},"/terms.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONの利用規約\"><title>利用規約｜MEFRION</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\">サポート</a><a href=\"/privacy.html\">プライバシー</a><a href=\"/terms.html\" aria-current=\"page\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">TERMS</div><h1>利用規約</h1><p>ペットとの毎日を、安心して楽しむための約束です。</p></section><div class=\"notice\">2026年11月2日更新。現在のサービスの利用条件です。</div><section class=\"paper\"><h2>1. サービスと利用資格</h2><p>MEFRIONはペットの写真・動画を記録し、家族と共有し、公開投稿で交流できるサービスです。無料で利用でき、犬や猫を飼っていなくても登録できます。有料機能を始める場合は、条件を別途案内します。</p></section><section class=\"paper\"><h2>2. アカウントと安全</h2><p>正しい情報で登録し、ログイン情報を安全に管理してください。他人へのなりすましや他人のアカウントの利用は禁止します。不正な利用が疑われる場合は、保護のために機能を制限することがあります。</p></section><section class=\"paper\"><h2>3. 写真・動画と公開範囲</h2><p>投稿する内容の権利は元の権利者に残ります。投稿者は、MEFRIONで保存、縮小、表示、選んだ公開範囲への配信を行うために必要な権限を持つことを確認してください。ほかの人や作品が写る場合は必要な許可を得てください。家族アルバムは初期非公開で、公開投稿や外部共有は別の操作で選びます。</p></section><section class=\"paper\"><h2>4. 禁止事項と対応</h2><p>権利侵害、他人の個人情報の無断公開、嫌がらせ、虐待の助長、差別、脅迫、性的な不適切内容、スパム、不正アクセスを禁止します。公開投稿の写真・動画と投稿文は公開前に運営が確認します。問題のある投稿やアカウントはアプリから通報できます。運営は内容を確認し、非表示や利用制限など必要な対応を行います。異議がある場合はお問い合わせください。</p></section><section class=\"paper\"><h2>5. そっくり機能</h2><p>写真の見た目から候補を探す機能です。血縁、同じ個体、健康状態を判定するものではありません。検索結果の近さは目安であり、正しさを保証するものではありません。</p></section><section class=\"paper\"><h2>6. 削除・変更・連絡</h2><p>アカウント削除はアプリのマイページから申請できます。削除が及ぶ範囲や情報の扱いは<a href=\"/privacy.html\">プライバシーポリシー</a>をご覧ください。サービスの重要な変更は事前に案内します。お問い合わせは <a href=\"mailto:mefrion@mefrion.com\">mefrion@mefrion.com</a> で受け付けます。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/\">サポート</a> · <a href=\"/privacy.html\">プライバシー</a></span></div></footer></body></html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{color-scheme:light;--ink:#352d34;--muted:#736a70;--pink:#d44e68;--soft:#fff2f3;--line:#eee5e5;--paper:#fffdfb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#faf7f4;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Hiragino Kaku Gothic ProN\",\"Noto Sans JP\",sans-serif;line-height:1.8}a{color:#a92c49;text-underline-offset:3px}button{font:inherit}.shell{max-width:920px;margin:auto;padding:0 22px}header{background:rgba(255,253,251,.96);border-bottom:1px solid var(--line)}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:74px}.brand{font-size:20px;font-weight:800;letter-spacing:.04em;text-decoration:none;color:var(--pink)}.brand span{font-size:20px;margin-right:7px}.nav{display:flex;gap:16px;flex-wrap:wrap}.nav a{text-decoration:none;color:var(--ink);font-size:13px;font-weight:700}.nav a[aria-current=page]{color:var(--pink)}main{padding-top:42px;padding-bottom:72px}.hero{background:linear-gradient(135deg,#fff,#fff0f1);border:1px solid #f6dce1;border-radius:28px;padding:32px 34px;margin-bottom:22px}.eyebrow{font-size:12px;color:var(--pink);font-weight:800;letter-spacing:.14em}.hero h1{font-size:clamp(27px,5vw,42px);line-height:1.35;margin:9px 0}.hero p{margin:0;color:var(--muted)}.notice{padding:15px 18px;border-radius:18px;background:#fff9e8;color:#5b4a2e;border:1px solid #f1dfab;font-size:14px;margin:18px 0 24px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card,.paper{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:22px}.card{text-decoration:none;color:var(--ink);transition:transform .15s,box-shadow .15s}.card:hover{transform:translateY(-3px);box-shadow:0 12px 28px #be899322}.icon{font-size:27px}.card h2{font-size:18px;margin:8px 0 4px}.card p{font-size:13px;color:var(--muted);margin:0}.paper{margin:14px 0}.paper h2{font-size:19px;line-height:1.45;margin:0 0 10px}.paper h3{font-size:15px;margin:20px 0 7px}.paper p,.paper li{font-size:14px;margin:0 0 9px}.paper ul{padding-left:1.2em;margin:0}.mini{font-size:12px;color:var(--muted)}.button{display:inline-block;padding:11px 22px;border-radius:999px;background:var(--pink);color:white;text-decoration:none;font-weight:800;margin-top:12px}.faq{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}footer{border-top:1px solid var(--line);padding:24px 0 32px;color:var(--muted);font-size:12px}footer .shell{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}footer a{color:var(--muted)}@media(max-width:620px){.top{align-items:flex-start;flex-direction:column;gap:0;padding:15px 0}.nav{gap:13px}.hero{padding:26px 22px}.cards{grid-template-columns:1fr}main{padding-top:22px}.paper{padding:20px}}\n"},"/privacy.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONのプライバシーポリシー\"><title>プライバシー｜MEFRION</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\">サポート</a><a href=\"/privacy.html\" aria-current=\"page\">プライバシー</a><a href=\"/terms.html\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">PRIVACY</div><h1>プライバシーポリシー</h1><p>あなたとペットの記録を、何に使い、どこで共有するかを説明します。</p></section><div class=\"notice\">2026年11月2日更新。現在提供している機能とデータの取り扱いを説明しています。</div><section class=\"paper\"><h2>1. 運営と連絡先</h2><p>運営表示名はMEFRIONです。プライバシーに関するご質問、開示・訂正・削除のご相談は <a href=\"mailto:mefrion@mefrion.com\">mefrion@mefrion.com</a> へお願いします。本人確認のため、必要な範囲で確認を行うことがあります。パスワードや確認コードの送付は求めません。</p></section><section class=\"paper\"><h2>2. 取り扱う情報と使い道</h2><p>利用状況と品質の改善のため、アプリが生成するランダムな端末識別子、起動・機能の利用・処理の成否・所要時間・アプリバージョンを収集します。ログイン中はアカウントと関連付けます。写真・投稿文・パスワード・認証コードはこの利用分析へ送りません。識別子はサーバーでハッシュ化し、詳細記録は最大90日を目安に保持します。広告追跡には使用しません。</p><p>共有リンクの到着数を調べるため、リンク先へ移動する際にブラウザごとのランダムな識別子をCookieへ最大30日保存し、到着した共有先の種類を記録します。Cookieの識別子はサーバーではハッシュ化します。この到着情報をアプリのインストールやアカウントと結び付けず、SNSへの投稿内容は収集しません。</p><ul><li>メールアドレス、ユーザーID、認証情報：登録、ログイン、確認メール、復旧、不正利用防止に使用します。パスワードそのものはアプリ運営者が閲覧できません。</li><li>プロフィール、ペットの名前・種類・犬種／猫種、写真・動画、撮影日、投稿文、コメント：アルバム、公開投稿、検索、表示に使用します。</li><li>フォロー、いいね、保存、通報、ブロック、通知設定：交流機能と安全管理に使用します。</li><li>アプリ・通信の技術情報：障害調査、不正利用対策、サービス改善に必要な範囲で扱います。</li></ul></section><section class=\"paper\"><h2>3. 写真の公開と家族共有</h2><p>家族アルバムは初期状態で非公開です。招待された家族のみが閲覧でき、公開投稿、そっくり候補への参加、外部共有にはそれぞれ別の操作が必要です。公開投稿の写真・動画と投稿文は公開前に運営が確認し、承認後にほかの利用者から閲覧されます。コメントも投稿前に不適切な内容を確認します。外部に保存・再共有されたコピーはMEFRIONから回収できません。</p><p>そっくり検索では、選んだ写真から端末内で作った特徴データと種類を検索サーバーへ送り、候補を比較します。検索の入力写真そのものは、その操作によってサーバーへアップロードしません。写真をアルバムや投稿へ保存する操作は別です。検索履歴には、どの写真から探したか分かる小さな入力画像と検索結果を、この端末内に24時間保存します。履歴はアプリから削除でき、入力画像を検索サーバーの履歴へ保存しません。</p></section><section class=\"paper\"><h2>4. 外部サービスと国外での取扱い</h2><p>認証、データベース、写真保存にはSupabaseを利用し、確認メールの配信にはBrevoを利用しています。サポート・規約・共有ページと運営画面の配信にはVercelを利用し、これらのWebページへの接続に伴うIPアドレスなどの技術情報が処理されます。これらの事業者がサービス提供のために必要な情報を処理します。本番のデータベースと写真・動画の保存先はSupabaseの東京リージョンです。メール配信などに伴い、委託先のサービス基盤で国外の処理が行われる場合があります。広告目的の追跡や、ユーザーの写真を汎用AIの学習へ自動転用することは予定していません。</p></section><section class=\"paper\"><h2>5. 保存・削除・安全管理</h2><p>情報は利用目的に必要な期間保管します。アプリ内で写真・投稿を削除したり、用途の同意を撤回したりできます。アカウント削除は「マイページ」から申請できます。受付時に公開表示とアクセスを停止し、残るファイルと認証情報は通常24時間以内に削除します。完了後、この端末でアプリを開いた時にお知らせします。24時間を超えた場合はお問い合わせください。法令上必要な情報や削除・復元の安全確認に必要な最小限の記録は、必要な期間だけ保持する場合があります。</p><p>通信の保護、アクセス権限の分離、アプリのKeychain利用などにより情報を守ります。ファイル・認証情報の削除処理と期限切れデータの整理はサーバーで定期実行します。暗号化したバックアップを別の保存先に保管し、復元時にも削除済みデータを再公開しないための記録を使います。外部サービス側で必要な技術記録やバックアップの保持については、各サービスの運用に従います。</p><p>不正利用の調査と障害対応のため、アクセスの日時、応答結果、対象機能、参考となる国情報、週ごとに変わる接続元の匿名化識別子などを記録します。この監視記録に元のIPアドレス、メールアドレス、パスワード、認証コード、リクエスト本文は保存しません。詳細は最大30日、時間別の集計と対応記録は最大90日を目安に保持し、運営権限と二段階認証で閲覧を制限します。外部サービス自体の技術ログは各サービスの運用に従います。</p></section><section class=\"paper\"><h2>6. 変更と問い合わせ</h2><p>サービスや情報の扱いを変更する際は、このページを更新します。重要な変更はアプリ内などで案内し、必要な場合は同意を取り直します。ご不明点は <a href=\"mailto:mefrion@mefrion.com\">mefrion@mefrion.com</a> へご連絡ください。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/\">サポート</a> · <a href=\"/terms.html\">利用規約</a></span></div></footer></body></html>\n"},"/console/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>MEFRION クラウド運営管理</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/console/seed.js\" defer></script><link rel=\"stylesheet\" href=\"/console/security.css\"><script src=\"/console/security.js\" defer></script><script src=\"/console/content.js\" defer></script><link rel=\"stylesheet\" href=\"/console/overview.css\"><script src=\"/console/overview.js\" defer></script><body><header><span>MEFRION / クラウド運営管理</span><a href=\"/console/\">一括管理へ</a></header><main><h1 id=\"main-heading\">運営管理</h1><p class=\"notice\">MEFRIONの運営管理。運営権限と認証アプリのMFAが必要です。利用者の家族アルバム原本と通報者の情報は取得しません。運営素材は担当権限で管理します。権限を付与された担当者だけが利用できます。</p><form id=\"login\"><label>運営専用のメールアドレス<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営専用のメールアドレス<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"overview-nav\" type=\"button\">ホーム</button><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><button id=\"content-nav\" type=\"button\">投稿の確認</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">最新の通報を取得</button><button id=\"logout\">ログアウト</button></div><section id=\"security-section\" hidden aria-label=\"セキュリティ監視\">\n <div class=\"sec-layout\"><aside class=\"sec-sidebar\"><a class=\"sec-wordmark\" href=\"/console/security\"><span class=\"sec-shield\">M</span> MEFRION<span class=\"sec-wordmark-small\">SECURITY</span></a><p class=\"sec-side-caption\">運営ワークスペース</p><nav aria-label=\"監視メニュー\"><button data-sec-view=\"overview\" class=\"active\">◈ 概要</button><button data-sec-view=\"events\">≋ 検知ログ</button><button data-sec-view=\"incidents\">⚑ インシデント <span id=\"sec-nav-incidents\">—</span></button><button data-sec-view=\"coverage\">◎ 監視範囲</button></nav><div class=\"sec-side-bottom\"><span class=\"sec-dot\"></span> 運営アカウント限定<p>二段階認証で保護されています</p></div></aside>\n <div class=\"sec-main\"><header class=\"sec-top\"><div><p class=\"sec-eyebrow\">SECURITY OPERATIONS</p><h1>セキュリティ</h1><p class=\"sec-sub\">起きていることを、記録から確かめる。</p></div><div class=\"sec-controls\"><label class=\"sec-sr\" for=\"sec-hours\">集計期間</label><select id=\"sec-hours\"><option value=\"24\">直近24時間</option><option value=\"168\">直近7日間</option><option value=\"720\">直近30日間</option></select><button id=\"sec-refresh\" type=\"button\">↻ 更新</button></div></header>\n <div class=\"sec-statusline\"><span id=\"sec-connection\" class=\"sec-status-pill\">接続を確認中</span><span id=\"sec-updated\">—</span><label><input id=\"sec-auto\" type=\"checkbox\" checked>概要を30秒ごとに更新</label></div>\n <div id=\"sec-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"sec-view\" data-sec-panel=\"overview\"><div class=\"sec-metrics\"><article><span>記録したシグナル</span><strong id=\"sec-signals\">—</strong><small>通常のエラー・監査記録も含む</small></article><article><span>攻撃の疑い</span><strong id=\"sec-suspected\">—</strong><small>探索・不正入力のパターン検知</small></article><article><span>拒否・制限の応答</span><strong id=\"sec-denied\">—</strong><small>401 / 403 / 404 / 405 / 429など</small></article><article><span>未対応のインシデント</span><strong id=\"sec-open\">—</strong><small>全期間・対応待ちの件数</small></article></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>シグナルの推移</h2><p>記録件数と、攻撃が疑われるパターン</p></div><div class=\"sec-legend\"><span>● 記録件数</span><span>● 攻撃の疑い</span></div></div><div id=\"sec-chart\" class=\"sec-chart\" role=\"img\" aria-label=\"集計結果の取得待ち\"></div><p class=\"sec-footnote\">時間単位の集計です。過去の未収集データは表示しません。</p></section>\n <div class=\"sec-grid-two\"><section class=\"sec-card\"><h2>検知の内訳</h2><div id=\"sec-types\" class=\"sec-breakdown\"></div></section><section class=\"sec-card\"><h2>対象になった場所</h2><div id=\"sec-targets\" class=\"sec-breakdown\"></div></section></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>繰り返し観測した接続元</h2><p>匿名化した識別子。個人や攻撃者の特定ではありません。</p></div></div><div id=\"sec-sources\"></div></section></div>\n <section class=\"sec-view sec-card\" data-sec-panel=\"events\" hidden><div class=\"sec-card-head\"><div><h2>検知ログ</h2><p>詳細を選んで、応答結果と記録IDを確認できます。</p></div><button id=\"sec-export\" type=\"button\">CSVを書き出す</button></div><div class=\"sec-filters\"><label>種類<select id=\"sec-kind\"><option value=\"\">すべての種類</option><option value=\"secret_probe\">秘密ファイル探索の疑い</option><option value=\"path_traversal\">パス探索の疑い</option><option value=\"injection_probe\">不正入力の疑い</option><option value=\"auth_denied\">認証拒否</option><option value=\"access_denied\">アクセス拒否</option><option value=\"rate_limited\">回数制限</option><option value=\"not_found\">404応答</option><option value=\"method_denied\">未対応のメソッド</option><option value=\"account_retirement\">退会の受付</option><option value=\"server_error\">サーバーエラー</option><option value=\"operator_changed\">運営権限の変更</option></select></label><label>重要度<select id=\"sec-severity\"><option value=\"\">すべて</option><option value=\"critical\">緊急</option><option value=\"high\">高</option><option value=\"medium\">中</option><option value=\"low\">低</option><option value=\"info\">情報</option></select></label><label>記録元<select id=\"sec-source\"><option value=\"\">すべて</option><option value=\"vercel\">Vercelサイト</option><option value=\"edge:private-image\">非公開画像API</option><option value=\"edge:public-image\">公開画像API</option><option value=\"edge:public-video\">公開動画API</option><option value=\"app_audit\">アプリの監査記録</option></select></label></div><div class=\"sec-table-wrap\"><table><thead><tr><th>記録時刻</th><th>種類</th><th>重要度</th><th>対象</th><th>結果</th><th>詳細</th></tr></thead><tbody id=\"sec-events\"></tbody></table></div><p id=\"sec-event-count\" class=\"sec-footnote\">—</p><button id=\"sec-more\" type=\"button\" hidden>さらに読み込む</button></section>\n <section class=\"sec-view sec-card\" data-sec-panel=\"incidents\" hidden><div class=\"sec-card-head\"><div><h2>インシデント</h2><p>同じ接続元で5分間に10件以上のシグナル、またはサーバーエラーをまとめます。</p></div></div><div id=\"sec-incidents\"></div></section>\n <section class=\"sec-view\" data-sec-panel=\"coverage\" hidden><div class=\"sec-card\"><h2>監視範囲と収集状態</h2><p>この画面に表示できる記録と、別途連携が必要な記録を区別しています。</p><div id=\"sec-coverage\"></div><div class=\"sec-coverage-static\"><article><h3>Vercel Firewall / DDoS対策</h3><span class=\"sec-badge neutral\">外部ログ未連携</span><p>Vercelがアプリ到達前に遮断した通信は、ここの件数に含まれません。</p><a href=\"https://vercel.com/toshiki-endos-projects/mefrion/firewall\" target=\"_blank\" rel=\"noopener noreferrer\">Vercelの公式画面で確認 ↗</a></article><article><h3>Supabase Auth / DB REST / Storageへの直接通信</h3><span class=\"sec-badge neutral\">拒否ログ未連携</span><p>Edge Functionを通らない直接アクセスの拒否は、この画面だけでは網羅できません。</p><a href=\"https://supabase.com/dashboard/project/pbnimpqrthvznbwewtcf/logs\" target=\"_blank\" rel=\"noopener noreferrer\">Supabaseの公式ログを開く ↗</a></article></div></div><div class=\"sec-card\"><h2>記録の取り扱い</h2><ul id=\"sec-limitations\"></ul><p>詳細ログは最大30日・10万件を目安に毎分整理し、時間別集計は最大90日、対応記録は最終更新から最大90日保存します。IPアドレス・メールアドレス・パスワード・認証コード・リクエスト本文は保存しません。ログの保存上限や送信エラーによる欠落がある場合は収集状態へ表示します。</p><p id=\"sec-retention\" class=\"sec-footnote\"></p></div></section>\n <footer class=\"sec-footer\">検知は調査の手がかりです。攻撃の確定や侵入成功を示すものではありません。<span id=\"sec-quality\"></span></footer>\n </div></div>\n <dialog id=\"sec-detail\" aria-labelledby=\"sec-detail-title\"><div class=\"sec-detail-head\"><h2 id=\"sec-detail-title\">記録の詳細</h2><button id=\"sec-detail-close\" type=\"button\" aria-label=\"詳細を閉じる\">×</button></div><dl id=\"sec-detail-body\"></dl><p>対象URLは個人情報を除去した形式です。元のIPアドレスや送信内容は記録していません。</p></dialog>\n</section>\n<!-- security-panel-end --><section id=\"content-section\" hidden aria-label=\"公開前の投稿確認\">\n <style>\n  #content-section{max-width:900px;margin:24px auto;padding:0 16px;color:#352426}\n  #content-section h2{font-size:1.5rem;margin:8px 0}\n  #content-section .content-intro{color:#6b5557;line-height:1.65}\n  #content-section .content-card{background:#fff;border:1px solid #f0d9dc;border-radius:20px;padding:20px;margin:18px 0;box-shadow:0 7px 24px #58272d12}\n  #content-section .content-card h3{margin:0 0 5px}\n  #content-section .content-card p{white-space:pre-wrap;overflow-wrap:anywhere}\n  #content-section .content-media{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:14px 0}\n  #content-section .content-media-item{background:#fff7f8;border:1px solid #f2dfe1;border-radius:14px;overflow:hidden;padding:8px}\n  #content-section .content-media img,#content-section .content-media video{display:block;width:100%;max-height:340px;object-fit:contain;background:#1c1718;border-radius:9px}\n  #content-section textarea{display:block;width:100%;box-sizing:border-box;min-height:70px;margin:14px 0;padding:12px;border:1px solid #dac8ca;border-radius:12px;font:inherit}\n  #content-section .content-actions{display:flex;flex-wrap:wrap;gap:10px}\n  #content-section button{border-radius:999px;padding:10px 16px;cursor:pointer}\n  #content-section .content-approve{background:#b92845;color:#fff;border:0}\n  #content-section .content-reject{background:#fff;color:#9a2438;border:1px solid #d4a0a8}\n  #content-section .content-muted{color:#806c70;font-size:.9rem}\n </style>\n <h2>公開前の投稿確認 🐾</h2>\n <p class=\"content-intro\">利用者の写真・動画は、確認が終わるまでおすすめに表示されません。すべてのメディアを見てから公開してください。迷ったら非公開にしてください。</p>\n <button id=\"content-refresh\" type=\"button\">一覧を更新</button>\n <p id=\"content-message\" role=\"status\" aria-live=\"polite\"></p>\n <div id=\"content-list\"></div>\n</section>\n<!-- content-panel-end --><section id=\"overview-section\" hidden aria-label=\"運営ホーム\">\n <header class=\"ops-hero\"><div><span class=\"ops-eyebrow\">MEFRION OPERATIONS</span><h1>今日の運営 🐾</h1><p>対応が必要なことを、ここから確認できます。</p></div><button id=\"ops-refresh\" type=\"button\">↻ 更新</button></header>\n <div id=\"ops-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"ops-metrics\" id=\"ops-metrics\"></div>\n <section class=\"ops-card\" aria-label=\"利用分析\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">PRODUCT ANALYTICS</span><h2>MEFRIONの成長と使い心地</h2><p id=\"product-status\">計測状況を確認しています</p></div><select id=\"product-days\" aria-label=\"分析期間\"><option value=\"7\">7日間</option><option value=\"30\" selected>30日間</option><option value=\"90\">90日間</option></select></div>\n <div id=\"product-summary\" class=\"ops-metrics\"></div>\n <h3>日ごとの利用と初回起動</h3><div id=\"product-daily\"></div>\n <h3>直近48時間の利用端末数（日本時間）</h3><div id=\"product-hourly\" class=\"product-chart\"></div><div id=\"product-hour-table\"></div>\n <h3>継続率</h3><div id=\"product-retention\"></div>\n <h3>初回利用・機能別の利用状況</h3><div id=\"product-funnel\"></div><div id=\"product-events\"></div>\n <h3>読み込み・処理の品質</h3><div id=\"product-rates\"></div><div id=\"product-quality\"></div>\n <h3>一般ユーザーと運営投稿</h3><div id=\"product-content\"></div>\n <h3>アプリのバージョン別</h3><div id=\"product-versions\"></div>\n <h3>App Store公式データ</h3><p id=\"product-apple-status\">Apple連携を確認しています</p><p class=\"ops-footnote\">毎日取得。ダウンロードは通常2日、インストールは通常5日まで更新されます。インストールはAppleへのデータ共有に同意した利用者の値で、少人数の場合は非表示です。未取得は0にしません。Appleのレポート日付を使用します。</p><div id=\"product-apple\"></div>\n <details><summary>公式数値を手動で記録（自動取得とは別）</summary><p>Apple公式画面の日別数値を転記します。空欄は未取得です。アプリ初回起動とダウンロードは異なる指標です。</p><form id=\"product-store-form\" class=\"product-store\"><label>対象日<input type=\"date\" name=\"day\" required></label><label>初回ダウンロード<input type=\"number\" name=\"first\" min=\"0\"></label><label>再ダウンロード<input type=\"number\" name=\"again\" min=\"0\"></label><label>インストール<input type=\"number\" name=\"installs\" min=\"0\"></label><button type=\"submit\">保存</button></form></details><div id=\"product-store\"></div>\n <p class=\"ops-footnote\">利用指標は新しいアプリから届いた計測のみ。端末数にはゲストを含み、複数端末・再インストールで同じ人が複数に数えられる場合があります。登録者DAUはサーバーで確認したアカウント単位です。自動アクセスや不正なクライアントによる偽装を完全には排除できないため、売上・請求・セキュリティ判断の根拠には使いません。共有ボタンはSNSを開く操作であり、投稿完了やダウンロードを示しません。画像・動画の時間は準備完了までで、画面内表示や再生開始の時間とは異なります。Xの共有リンクからApp Storeへの移動は計測します。SNS内の投稿完了・インストールへの結び付き・Apple公式DL数は上の自動連携欄で別に確認します。</p>\n </section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">TO DO</span><h2>先に見てほしいこと</h2></div></div><div id=\"ops-alerts\" class=\"ops-alerts\"></div></section>\n <div class=\"ops-grid\">\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">TODAY</span><h2>アプリの動き</h2><div id=\"ops-activity\"></div></section>\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">ACTIVITY</span><h2>最近の対応</h2><div id=\"ops-actions\"></div></section>\n </div>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SEARCH</span><h2>投稿を探す</h2><p>Pet名・投稿文・投稿IDで検索できます。</p></div></div><form id=\"ops-search-form\" class=\"ops-search\"><input id=\"ops-search\" type=\"search\" maxlength=\"80\" minlength=\"2\" placeholder=\"Pet名、投稿文、投稿ID\" required><button type=\"submit\">検索</button></form><div id=\"ops-search-results\"></div></section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SUPPORT</span><h2>問い合わせ</h2><p>メールで受けた相談の担当・期限・対応状況を記録します。</p></div><button id=\"ops-case-new\" type=\"button\">＋ 相談を記録</button></div><div id=\"ops-cases\"></div></section>\n <dialog id=\"ops-case-dialog\"><form id=\"ops-case-form\" method=\"dialog\"><h2>問い合わせを記録</h2><label>件名<input name=\"subject\" maxlength=\"160\" required></label><label>返信先メール<input name=\"email\" type=\"email\" maxlength=\"254\"></label><label>相談内容<textarea name=\"detail\" maxlength=\"4000\" rows=\"5\"></textarea></label><div class=\"ops-dialog-grid\"><label>優先度<select name=\"priority\"><option value=\"normal\">通常</option><option value=\"urgent\">至急</option></select></label><label>対応期限<input name=\"due\" type=\"datetime-local\"></label></div><div class=\"ops-dialog-actions\"><button type=\"button\" id=\"ops-case-cancel\">閉じる</button><button type=\"submit\">記録する</button></div></form></dialog>\n <dialog id=\"ops-history-dialog\"><div class=\"ops-card-head\"><h2>投稿の対応履歴</h2><button id=\"ops-history-close\" type=\"button\">閉じる</button></div><div id=\"ops-history\"></div></dialog>\n <footer class=\"ops-footnote\"><span id=\"ops-email-status\">メール通知の状態を確認中</span> · 数値は取得時点の本番データです。問い合わせメールの自動取り込みは現在連携していません。</footer>\n</section>\n<!-- overview-panel-end --><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section></main></body></html>\n"},"/console/cloud.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst $=id=>document.getElementById(id);\nlet config,token,factor,expires=0,busy=false,generation=0,pendingReview=null,pendingEmail=null,mfaComplete=false;\nlet panel=document.body?.dataset?.consolePanel||'overview';\nconst status=message=>{$('status').textContent=message;const feedback=$('mfa-feedback');if(feedback)feedback.textContent=$('mfa').hidden?'':message;};\n// Map documented error codes; never display raw authentication responses.\nconst authErrors={\n mfa_verification_failed:'コードが一致しません。今回追加した「MEFRION operator」の新しい6桁を入力してください。',\n mfa_challenge_expired:'コードの確認期限が切れました。認証アプリの新しい6桁でもう一度お試しください。',\n mfa_ip_address_mismatch:'途中で通信経路が変わりました。同じWi-Fiかモバイル回線で、もう一度確認してください。',\n mfa_factor_not_found:'認証アプリの登録が見つかりません。メールでログインし直してください。',\n mfa_factor_name_conflict:'確認待ちの登録があります。メールでログインし直すと続きから確認できます。',\n mfa_verification_rejected:'確認が制限されています。少し時間をおいてお試しください。',\n otp_expired:'メールの確認コードが違うか期限切れです。新しいメールのコードでお試しください。'\n};\nasync function request(path,body,auth=token,clearOnForbidden=true,method=body===undefined?'GET':'POST'){\n const headers={apikey:config.anon_key,'Content-Type':'application/json'};if(auth)headers.Authorization='Bearer '+auth;\n const response=await fetch(config.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',credentials:'omit',signal:typeof AbortSignal==='undefined'?undefined:AbortSignal.timeout(20000)});\n if(!response.ok){\n  let errorCode='';try{const result=await response.json();const value=result.error_code||result.code;if(typeof value==='string'&&/^[a-z_]{1,80}$/.test(value))errorCode=value;}catch{}\n  const mfaError=errorCode.startsWith('mfa_');\n  if(((response.status===401&&!mfaError)||(response.status===403&&clearOnForbidden&&!mfaError))&&auth&&auth===token)clear();\n  const error=Error(authErrors[errorCode]||(response.status===429?'確認が混み合っています。少し時間をおいてお試しください。':response.status===401?'ログインが切れました。メールでログインし直してください。':response.status===403?'運営権限と認証を確認してください。':'操作できません。入力内容と接続を確認してください。'));\n  error.status=response.status;error.code=errorCode;throw error;\n }\n return response.status===204?null:response.json();\n}\nconst rpc=(name,body={})=>request('/rest/v1/rpc/mefrion_'+name,body);\ndocument.getElementById('server-health-refresh')?.addEventListener('click',()=>perform(async()=>{\n const result=await rpc('operator_cloud_health');\n const output=document.getElementById('server-health-output');\n if(output)output.textContent=JSON.stringify(result,null,2);\n status('サーバーの稼働状況を取得しました。');\n}));\nfunction clear(){if(typeof clearAds==='function')clearAds();if(typeof clearSecurity==='function')clearSecurity();if(typeof clearOverview==='function')clearOverview();if(typeof clearContent==='function')clearContent();$('restart-enroll').hidden=true;mfaComplete=false;pendingEmail=null;$('email-code').value='';$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=false;$('main-heading').textContent=panel==='ads'?'Ads':'運営管理';if(typeof clearSeed===\"function\")clearSeed();generation++;token=null;factor=null;expires=0;$('queue').replaceChildren();$('queue').hidden=false;$('confirmation').hidden=true;pendingReview=null;$('password').value='';$('code').value='';$('session').hidden=true;$('refresh').hidden=false;$('mfa').hidden=true;$('enroll').hidden=true;$('enroll-instructions').hidden=true;$('enroll-secret').textContent='';$('start-enroll').hidden=false;$('login').hidden=false;}\nasync function perform(operation){if(busy)return;busy=true;for(const button of document.querySelectorAll('button'))button.disabled=true;try{await operation();}catch(error){status(error.name==='TimeoutError'||error.name==='AbortError'?'通信に時間がかかっています。もう一度お試しください。':error instanceof TypeError?'通信できませんでした。接続を確認して、もう一度お試しください。':error.message);}finally{busy=false;for(const button of document.querySelectorAll('button'))button.disabled=false;}}\nfunction node(tag,text){const result=document.createElement(tag);if(text!==undefined)result.textContent=text;return result;}\nasync function refresh(){\n if(panel==='ads')return refreshAds();\n if(panel==='overview'&&typeof refreshOverview==='function')return refreshOverview();if(panel==='security'&&typeof refreshSecurity==='function')return refreshSecurity();if(panel==='content'&&typeof refreshContent==='function')return refreshContent();\n $('main-heading').textContent='通報を確認する';\n $('seed-section').hidden=true;$('queue').hidden=false;$('queue').replaceChildren();if(!token || Date.now()/1000>=expires){clear();throw Error('ログインが切れました。再度ログインしてください。');}\n const stamp=generation;let rows;try{rows=await request('/rest/v1/rpc/mefrion_operator_queue',{},token,false);}catch(error){if(error.status===403){status('二段階認証が完了しました。運営権限の有効化をお待ちください。');return;}throw error;}if(stamp!==generation)return;\n for(const report of rows){\n  const card=node('article');card.className='card';card.append(node('h2',report.comment_id?'コメントの通報':'Pet・投稿の通報'),node('p',report.reason),node('p',report.note),node('p',report.snapshot.body||report.snapshot.name||''));\n  const history=node('p',`対応履歴 ${report.reviews.length}件・異議 ${report.appeals.length}件`);card.append(history);\n  const assigned=report.assignment||{version:0,mine:false,assigned:false};card.append(node('p',assigned.assigned?(assigned.mine?'担当：あなた':'担当：別の担当者'):'担当：未割当'));const claim=node('button',assigned.mine?'担当を解除する':'この通報を担当する');claim.hidden=assigned.assigned&&!assigned.mine;claim.addEventListener('click',()=>perform(async()=>{await rpc('operator_claim',{p_report:report.id,p_version:assigned.version,p_claim:!assigned.mine});await refresh();}));card.append(claim);\n  for(const appeal of report.appeals)card.append(node('p','異議内容：'+appeal.note));\n  const select=node('select');select.setAttribute('aria-label','対応内容');\n  for(const [value,label] of [['dismiss','確認終了'],[report.comment_id?'hide_comment':'hide_post',report.comment_id?'コメントを非表示':'投稿を非表示'],['suspend_account','相手の全Pet・公開活動を停止'],['restore_account','公開活動の停止を解除']]){const option=node('option',label);option.value=value;select.append(option);}\n  const note=node('textarea');note.maxLength=1000;note.placeholder='内部の判断理由（必須）';note.setAttribute('aria-label','判断理由');\n  const button=node('button','対応を記録');let requestKey=crypto.randomUUID();const changed=()=>{requestKey=crypto.randomUUID();};note.addEventListener('input',changed);select.addEventListener('change',changed);\n  button.addEventListener('click',()=>perform(async()=>{\n   if(!note.value.trim())throw Error('判断理由を入力してください。');\n   pendingReview={p_report:report.id,p_decision:select.value,p_note:note.value,p_request_key:requestKey};\n   $('confirm-target').textContent=(report.comment_id?'コメントの通報':'Pet・投稿の通報')+'：'+select.selectedOptions[0].textContent;\n   $('confirm-reason').textContent='内部の判断理由：'+note.value;$('confirmation').hidden=false;$('queue').hidden=true;\n  }));select.hidden=note.hidden=button.hidden=assigned.assigned&&!assigned.mine;card.append(select,note,button);$('queue').append(card);\n }\n status(`運営権限とMFAを確認しました。通報 ${rows.length}件。`);\n}\n$('login').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n const credentials={email:$('email').value,password:$('password').value};clear();const stamp=generation;const configPath=document.querySelector('meta[name=\"mefrion-config\"]')?.content||'/v1/development/cloud-public-config';config=await (await fetch(configPath,{cache:'no-store'})).json();\n const result=await request('/auth/v1/token?grant_type=password',credentials,null);$('password').value='';\n await acceptSession(result,stamp);\n});});\n$('start-enroll').addEventListener('click',()=>perform(async()=>{\n const stamp=generation;const result=await request('/auth/v1/factors',{factor_type:'totp',friendly_name:'MEFRION operator'});if(stamp!==generation)return;\n factor=result.id;$('restart-enroll').hidden=false;$('enroll-secret').textContent=result.totp.secret;$('enroll-instructions').hidden=false;$('start-enroll').hidden=true;$('mfa').hidden=false;status('設定キーを認証アプリへ登録し、コードを入力してください。');\n}));\n$('mfa').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n const code=$('code').value.normalize('NFKC').replace(/[\\s-]/g,'');\n if(!/^[0-9]{6}$/.test(code))throw Error('認証アプリの6桁を入力してください。メールの確認コードとは別です。');\n if(!token||!factor)throw Error('メールでログインし直してください。');\n status('コードを確認しています…');\n const stamp=generation;const challenge=await request('/auth/v1/factors/'+factor+'/challenge',{});\n const result=await request('/auth/v1/factors/'+factor+'/verify',{challenge_id:challenge.id,code});$('code').value='';if(stamp!==generation)return;\n mfaComplete=true;token=result.access_token;expires=Date.now()/1000+result.expires_in;$('enroll').hidden=true;$('enroll-secret').textContent='';$('mfa').hidden=true;$('restart-enroll').hidden=true;$('session').hidden=false;\n if(panel==='ads')return refresh();\n let seedOnly=false;try{const permissions=await request('/rest/v1/rpc/mefrion_seed_permissions',{},token,false);seedOnly=(permissions.edit||permissions.approve)&&!permissions.publish;}catch(error){}\n $('refresh').hidden=seedOnly;\n if(seedOnly){await refreshSeed();status('運営権限とMFAを確認しました。担当範囲の素材・下書きを管理できます。');}else await refresh();\n});});\n$('confirm-review').addEventListener('click',()=>perform(async()=>{\n if(!pendingReview)return;const payload=pendingReview;const stamp=generation;await rpc('operator_review',payload);if(stamp!==generation)return;\n pendingReview=null;$('confirmation').hidden=true;$('queue').hidden=false;await refresh();status('対応を記録しました。');\n}));\n$('cancel-review').addEventListener('click',()=>{pendingReview=null;$('confirmation').hidden=true;$('queue').hidden=false;status('対応を取り消しました。');});\n$('cancel-login').addEventListener('click',()=>{clear();status('ログインを取り消しました。');});\n$('refresh').addEventListener('click',()=>perform(refresh));$('logout').addEventListener('click',()=>perform(async()=>{const previous=token;clear();if(previous)await request('/auth/v1/logout',{},previous);status('ログアウトしました。');}));\nwindow.addEventListener('pagehide',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden){$('enroll-secret').textContent='';$('queue').replaceChildren();if(typeof clearSeed==='function')clearSeed();pendingReview=null;$('confirmation').hidden=true;$('confirm-target').textContent='';$('confirm-reason').textContent='';}else if(mfaComplete && token && !busy)perform(async()=>{if(panel==='ads')return refresh();const permissions=await request('/rest/v1/rpc/mefrion_seed_permissions',{},token,false);if((permissions.edit||permissions.approve)&&!permissions.publish){$('refresh').hidden=true;await refreshSeed();}else await refresh();});});\n\nasync function acceptSession(result,stamp){\n if(stamp!==generation)return;mfaComplete=false;token=result.access_token;expires=Date.now()/1000+result.expires_in;\n const eligible=await request('/rest/v1/rpc/mefrion_operator_login_eligible',{},token,false);\n if(eligible!==true){clear();throw Error('このアカウントでは運営画面を利用できません。運営専用のメールアドレスでログインしてください。');}\n const user=await request('/auth/v1/user');const verified=(user.factors||[]).filter(item=>item.factor_type==='totp' && item.status==='verified');\n if(!verified.length){\n  $('login').hidden=true;$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=true;\n  const pending=(user.factors||[]).find(item=>item.factor_type==='totp'&&item.status==='unverified');\n  if(pending){factor=pending.id;$('mfa').hidden=false;$('restart-enroll').hidden=false;status('確認待ちの登録があります。今回追加した運営画面用の6桁を入力してください。未追加なら「認証アプリを登録し直す」へ。');}\n  else{$('enroll').hidden=false;status('この運営画面用の認証アプリ登録が必要です。以前のSupabase用とは別です。');}\n  return;\n }\n factor=verified[0].id;$('login').hidden=true;$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=true;$('mfa').hidden=false;status('認証アプリのコードを入力してください。');\n}\n\nasync function loadConfig(){const path=document.querySelector('meta[name=\"mefrion-config\"]')?.content||'/console/config.json';const response=await fetch(path,{cache:'no-store',credentials:'omit'});if(!response.ok)throw Error('接続を確認してください。');config=await response.json();}\n$('email-login-toggle').addEventListener('click',()=>{clear();$('login').hidden=true;$('email-login-toggle').hidden=true;$('email-login').hidden=false;status('メールに届くコードで続けます。');});\n$('email-login').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n if(!$('otp-consent').checked)throw Error('利用条件を確認してください。');\n const email=$('otp-email').value.trim();const stamp=generation;await loadConfig();\n await request('/auth/v1/otp',{email,create_user:true},null);if(stamp!==generation)return;\n pendingEmail=email;$('email-login').hidden=true;$('email-verify').hidden=false;status('メールに届いた確認コードを入力してください。');\n});});\n$('email-verify').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n if(!pendingEmail)throw Error('確認コードの送信からやり直してください。');const stamp=generation;\n const result=await request('/auth/v1/verify',{email:pendingEmail,token:$('email-code').value.trim(),type:'email'},null);\n $('email-code').value='';pendingEmail=null;await acceptSession(result,stamp);\n});});\n\n$('check-connection').addEventListener('click',()=>perform(async()=>{\n await loadConfig();\n const result=await fetch(config.url+'/auth/v1/settings',{headers:{apikey:config.anon_key},cache:'no-store',credentials:'omit'});\n if(!result.ok)throw Error('認証サーバーに接続できませんでした。時間をおいてお試しください。');\n // Nonexistent reserved address, create_user false: exercises POST/CORS without\n // sending mail or creating an account. Do not display response bodies.\n const probe=await fetch(config.url+'/auth/v1/otp',{method:'POST',headers:{apikey:config.anon_key,'Content-Type':'application/json'},body:JSON.stringify({email:'mefrion-connectivity-check@example.invalid',create_user:false}),cache:'no-store',credentials:'omit'});\n if(![200,400,422,429].includes(probe.status))throw Error('認証サーバーに接続できませんでした。時間をおいてお試しください。');\n status('認証サーバーとの通信を確認できました。メールは送信していません。');\n}));\n\n$('restart-enroll').addEventListener('click',()=>perform(async()=>{\n const stamp=generation;const user=await request('/auth/v1/user');\n const pending=(user.factors||[]).find(item=>item.id===factor&&item.factor_type==='totp'&&item.status==='unverified');\n if(!pending)throw Error('登録状態が変わりました。メールでログインし直してください。');\n await request('/auth/v1/factors/'+pending.id,undefined,token,true,'DELETE');\n if(stamp!==generation)return;factor=null;$('code').value='';$('mfa').hidden=true;$('restart-enroll').hidden=true;\n $('enroll').hidden=false;$('enroll-instructions').hidden=true;$('enroll-secret').textContent='';$('start-enroll').hidden=false;\n status('確認前の登録を取り消しました。新しい設定キーで認証アプリへ追加してください。確認済みの登録は変更していません。');\n}));\n\n$('copy-enroll-key').addEventListener('click',()=>perform(async()=>{\n const key=$('enroll-secret').textContent;if(!key)throw Error('設定キーが消去されています。「認証アプリを登録し直す」から新しく追加してください。');\n await navigator.clipboard.writeText(key);status('設定キーをコピーしました。認証アプリで新しい項目に登録し、そこで表示される6桁を入力してください。');\n}));\n"},"/console/seed.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nlet seedSnapshot=null,seedItems=[],seedKey=crypto.randomUUID(),seedPreviewURLs=[],seedGeneration=0,seedPermissions={},seedPreviewBytes=0;\nfunction releaseSeedPreviews(){for(const url of seedPreviewURLs)URL.revokeObjectURL(url);seedPreviewURLs=[];seedPreviewBytes=0;}\nfunction seedStamp(){return generation+\":\"+seedGeneration;}\nfunction clearSeed(){seedGeneration++;seedPermissions={};$('seed-audit').replaceChildren();$('seed-permissions').textContent='';releaseSeedPreviews();seedBatchItems=[];$('seed-post-csv').value='';$('seed-batch-list').replaceChildren();$('seed-calendar').replaceChildren();$('seed-search').value='';$('seed-metrics').textContent='';$('seed-publisher').replaceChildren();seedSnapshot=null;seedItems=[];seedKey=crypto.randomUUID();$('seed-list').replaceChildren();$('seed-preview').replaceChildren();$('seed-csv').value='';$('seed-section').hidden=true;}\nasync function refreshSeed(){\n $('main-heading').textContent='運営Petの一括管理';const stamp=seedStamp();const data=await rpc('seed_list');if((stamp!==seedStamp() || document.hidden))return;seedPermissions=await rpc('seed_permissions');if(stamp!==seedStamp() || document.hidden)return;seedSnapshot=data;$('queue').hidden=true;$('seed-permissions').textContent='担当権限：'+Object.keys(seedPermissions).filter(k=>seedPermissions[k]).join(' / ')+'（サーバーでも毎回確認）';for(const id of ['seed-preview-button','seed-create','seed-batch-preview','seed-batch-save'])$(id).hidden=!seedPermissions.edit;$('seed-ratio-save').hidden=!seedPermissions.publish;$('seed-section').hidden=false;$('seed-publisher').replaceChildren();for(const id of data.publishers){const o=node('option','運営用の投稿主体 '+id.slice(0,8));o.value=id;$('seed-publisher').append(o);}renderSeed();renderSeedCalendar();const stats=await rpc('seed_metrics');if((stamp!==seedStamp() || document.hidden))return;$('seed-metrics').textContent=`実登録 ${stats.real_registered_users} / UGC ${stats.ugc_posts} / 運営 ${stats.managed_posts} / 開発用公開 ${stats.synthetic_posts} / 運営上限比率 ${stats.max_seed_ratio}`;}\nfunction csvRows(text){\n if(text.length>100000)throw Error('CSVは100KBまでです。');\n const rows=[];let row=[],cell='',quoted=false;\n for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='\"'){if(quoted && text[i+1]==='\"'){cell+='\"';i++;}else if(quoted || cell==='')quoted=!quoted;else throw Error('CSVの引用符を確認してください。');}else if(!quoted && ch===','){row.push(cell);cell='';}else if(!quoted && (ch==='\\n' || ch==='\\r')){if(ch==='\\r' && text[i+1]==='\\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}\n if(quoted)throw Error('CSVの引用符が閉じていません。');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);\n return rows;\n}\nfunction parseSeedCSV(text){\n const rows=csvRows(text);\n const headers=rows.shift()?.map(v=>v.trim());const required=['key','name','species','breed','introduction','source'];if(!headers || headers.join(',')!==required.join(','))throw Error('ヘッダーは key,name,species,breed,introduction,source の順にしてください。');\n if(!rows.length || rows.length>20)throw Error('一度の登録は1〜20件です。');\n const items=rows.map(r=>{if(r.length!==6)throw Error('CSVの列数を確認してください。');const item=Object.fromEntries(required.map((key,i)=>[key,r[i].trim()]));if(!item.key || !item.name || !['dog','cat'].includes(item.species) || !item.source || item.name.length>40 || item.breed.length>100 || item.introduction.length>500 || item.source.length>500)throw Error('必須項目・文字数・dog/catを確認してください。');return item;});\n if(new Set(items.map(v=>v.key)).size!==items.length)throw Error('管理キーが重複しています。');return items;\n}\nfunction renderSeed(){\n releaseSeedPreviews();$('seed-list').replaceChildren();const selectedPets=new Set();const batch=node('div');const batchConfirm=node('input');batchConfirm.type='checkbox';const batchLabel=node('label');batchLabel.append(batchConfirm,node('span','選択したPetの全公開停止を確認する'));const batchStop=node('button','選択Petを一括停止');batchStop.addEventListener('click',()=>perform(async()=>{if(!batchConfirm.checked || !selectedPets.size)throw Error('対象Petを選択して停止を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[...selectedPets],p_withdraw_rights:false});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));batchLabel.hidden=batchStop.hidden=!seedPermissions.stop;batch.append(batchLabel,batchStop);$('seed-list').append(batch);const q=$('seed-search').value.trim();\n for(const pet of seedSnapshot.pets.filter(p=>!q || (p.name+' '+p.key+' '+p.species).includes(q))){\n  const article=node('article');article.className='card';article.append(node('h2',pet.name),node('p',pet.species+' / '+pet.key),node('p',pet.active===false?'保管中・配信停止':'運営在庫として使用中'),node('p','内部Pet ID：'+pet.id),node('p','出典：'+pet.source),node('p',pet.rights_verified?'権利確認済み・期限 '+pet.rights_until:'権利未確認：下書きのみ'),node('p','更新版 '+pet.version+' / 最終担当 '+pet.updated_by));\n  const selected=node('input');selected.type='checkbox';const selectedLabel=node('label');selectedLabel.append(selected,node('span',pet.name+'を一括停止の対象にする'));selected.addEventListener('change',()=>selected.checked?selectedPets.add(pet.id):selectedPets.delete(pet.id));selectedLabel.hidden=!seedPermissions.stop;article.append(selectedLabel);\n  const copy=node('button','プロフィールを複製する前に確認');copy.hidden=!seedPermissions.edit;copy.addEventListener('click',()=>{const quote=v=>'\"'+String(v||'').replaceAll('\"','\"\"')+'\"';$('seed-csv').value='key,name,species,breed,introduction,source\\n'+[pet.key+'-copy-'+crypto.randomUUID().slice(0,8),pet.name,pet.species,pet.breed,pet.introduction,pet.source].map(quote).join(',');$('seed-preview').replaceChildren();seedItems=[];status('複製先の管理キー・名前・出典を確認し、新しくプレビューしてください。写真や権利承認は複製しません。');});article.append(copy);const edit=node('details');edit.append(node('summary','プロフィール編集・保管設定'));const edited={};for(const [field,label,value] of [['name','なまえ',pet.name],['breed','種類',pet.breed||''],['introduction','紹介文',pet.introduction||''],['source','内部出典',pet.source]]){const row=node('label',label);const input=node('input');input.value=value;edited[field]=input;row.append(input);edit.append(row);}const active=node('input');active.type='checkbox';active.checked=pet.active!==false;const activeLabel=node('label');activeLabel.append(active,node('span','運営在庫として利用する'));edit.append(activeLabel);const editConsent=node('input');editConsent.type='checkbox';const editLabel=node('label');editLabel.append(editConsent,node('span','変更後は公開停止・権利再審査になることを確認する'));edit.append(editLabel);const saveEdit=node('button','変更を保存して再審査へ');saveEdit.addEventListener('click',()=>perform(async()=>{if(!editConsent.checked)throw Error('公開停止と再審査を確認してください。');const stamp=seedStamp();await rpc('seed_edit',{p_pet:pet.id,p_version:pet.version,p_name:edited.name.value,p_breed:edited.breed.value,p_introduction:edited.introduction.value,p_source:edited.source.value,p_active:active.checked});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));edit.append(saveEdit);edit.hidden=!seedPermissions.edit;article.append(edit);\n  const file=node('input');file.type='file';file.accept='image/jpeg';file.multiple=true;file.setAttribute('aria-label',pet.name+'のJPEG素材');\n  const previews=node('div');previews.className='seed-previews';file.addEventListener('change',()=>{previews.replaceChildren();for(const f of [...file.files].slice(0,4)){if(f.type!=='image/jpeg' || f.size>20*1024*1024)continue;const url=URL.createObjectURL(f);seedPreviewURLs.push(url);const image=node('img');image.src=url;image.alt='配信前の素材プレビュー '+f.name;image.width=160;image.height=160;previews.append(image);} });article.append(previews);\n  const upload=node('button','選択JPEGを登録');upload.addEventListener('click',()=>perform(async()=>{\n   const files=[...file.files];if(!files.length || files.length>4 || files.some(f=>f.type!=='image/jpeg' || f.size>20*1024*1024) || files.reduce((n,f)=>n+f.size,0)>100*1024*1024)throw Error('JPEGを1〜4枚、1枚20MB・合計100MBまで選んでください。');\n   const stamp=seedStamp();\n   for(const f of files){const bytes=await f.arrayBuffer(),digest=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));const hex=Array.from(digest).map(x=>x.toString(16).padStart(2,'0')).join('');const id=hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20,32);if((stamp!==seedStamp() || document.hidden))return;\n    const p=await rpc('seed_begin_photo',{p_pet:pet.id,p_key:id,p_title:'JPEG '+hex.slice(0,8)});\n    if(p.state!=='ready'){const response=await fetch(config.url+'/storage/v1/object/family-originals/'+p.path,{method:'POST',headers:{apikey:config.anon_key,Authorization:'Bearer '+token,'Content-Type':'image/jpeg'},body:bytes,cache:'no-store',credentials:'omit'});if(!response.ok){const e=await response.json();if(![400,409].includes(response.status) || e.error!=='Duplicate')throw Error('素材の送信に失敗しました。同じファイルで再試行してください。');}if((stamp!==seedStamp() || document.hidden))return;await rpc('seed_finish_photo',{p_photo:p.id});}\n   }if((stamp===seedStamp() && !document.hidden)){file.value='';await refreshSeed();status('素材を非公開で登録しました。承認前には配信しません。');}\n  }));file.hidden=upload.hidden=!seedPermissions.edit;article.append(file,upload);\n  const chosen=[];const pics=node('div');for(const photo of pet.photos.filter(p=>p.state==='ready')){const label=node('label');const box=node('input');box.type='checkbox';box.addEventListener('change',()=>{const i=chosen.indexOf(photo.id);if(box.checked && i<0)chosen.push(photo.id);else if(i>=0)chosen.splice(i,1);});label.append(box,node('span',photo.title),node('code',photo.id));pics.append(label);\n   const preview=node('button','この素材をプレビュー');preview.addEventListener('click',()=>perform(()=>previewSeedPhoto(photo,pics)));pics.append(preview);\n   const record=node('details');record.append(node('summary','この画像の権利証跡'));const inputs={};for(const [key,label,value] of [['holder','権利者',photo.rights?.holder||''],['scope','使用範囲',photo.rights?.scope||''],['evidence','証跡の保管場所',photo.rights?.evidence||'']]){const row=node('label',label);const input=node('input');input.value=value;inputs[key]=input;row.append(input);record.append(row);}const until=node('input');until.type='datetime-local';until.setAttribute('aria-label','画像の権利期限');const allowed=node('input');allowed.type='checkbox';const rightsLabel=node('label');rightsLabel.append(allowed,node('span','この画像の権利証跡・掲載許可を確認する'));record.append(until,rightsLabel);const save=node('button','画像権利を確認して保存');save.addEventListener('click',()=>perform(async()=>{if(!allowed.checked || !until.value)throw Error('画像ごとの確認と期限を入力してください。');const stamp=seedStamp();await rpc('seed_photo_rights',{p_photo:photo.id,p_holder:inputs.holder.value,p_scope:inputs.scope.value,p_evidence:inputs.evidence.value,p_until:new Date(until.value).toISOString(),p_allowed:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));save.hidden=!seedPermissions.approve;record.append(save);if(photo.rights)record.append(node('p','確認担当 '+photo.rights.checked_by+' / '+photo.rights.checked_at+' / '+(photo.rights.allowed?'掲載許可あり':'撤回済み')));pics.append(record);const removeConfirm=node('input');removeConfirm.type='checkbox';const removeLabel=node('label');removeLabel.append(removeConfirm,node('span','この素材の公開停止・削除連動を確認する'));const remove=node('button','この素材を削除');remove.hidden=removeLabel.hidden=!seedPermissions.edit;remove.addEventListener('click',()=>perform(async()=>{if(!removeConfirm.checked)throw Error('削除連動を確認してください。');const stamp=seedStamp();await rpc('seed_delete_photo',{p_photo:photo.id,p_explicit:true});if(stamp===seedStamp()&&!document.hidden)await refreshSeed();}));pics.append(removeLabel,remove);if(photo.rights){const revoke=node('button','この素材の掲載権利を撤回');revoke.hidden=!seedPermissions.approve;revoke.addEventListener('click',()=>perform(async()=>{if(!removeConfirm.checked)throw Error('この素材の全公開停止を確認してください。');const stamp=seedStamp();await rpc('seed_photo_rights',{p_photo:photo.id,p_holder:photo.rights.holder,p_scope:photo.rights.scope,p_evidence:photo.rights.evidence,p_until:new Date(Date.now()+86400000).toISOString(),p_allowed:false});if(stamp===seedStamp()&&!document.hidden)await refreshSeed();}));pics.append(revoke);if(seedPermissions.approve)removeLabel.hidden=false;}}article.append(pics);\n  const body=node('textarea');body.maxLength=500;body.placeholder='Pet名義の投稿本文（任意・500字まで）';body.setAttribute('aria-label',pet.name+'の投稿本文');let draftKey=crypto.randomUUID();body.addEventListener('input',()=>draftKey=crypto.randomUUID());pics.addEventListener('change',()=>draftKey=crypto.randomUUID());\n  const draft=node('button','このPet名義で下書きを保存');draft.addEventListener('click',()=>perform(async()=>{if(chosen.length<1 || chosen.length>4)throw Error('写真を1〜4枚選んでください。');const stamp=seedStamp();await rpc('seed_draft',{p_pet:pet.id,p_photos:chosen,p_body:body.value,p_key:draftKey});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('下書きを保存しました。');}}));body.hidden=draft.hidden=!seedPermissions.edit;article.append(body,draft);\n  for(const job of pet.jobs){const section=node('section');section.append(node('h3',job.state+' / 版 '+job.version),node('p',job.body));const rights=node('textarea');rights.placeholder='確認した権利・利用範囲・出典（10〜1000字）';rights.maxLength=1000;rights.setAttribute('aria-label','権利確認記録');const expiry=node('input');expiry.type='datetime-local';expiry.setAttribute('aria-label','権利期限');const consent=node('input');consent.type='checkbox';const confirmation=node('label');confirmation.append(consent,node('span','素材・本文・掲載権利を確認しました'));section.append(rights,expiry,confirmation);\n   const approve=node('button','権利確認して承認');approve.addEventListener('click',()=>perform(async()=>{if(!consent.checked || rights.value.trim().length<10 || !expiry.value)throw Error('権利記録・期限・確認を入力してください。');const stamp=seedStamp();await rpc('seed_approve',{p_job:job.id,p_version:job.version,p_rights_note:rights.value,p_rights_until:new Date(expiry.value).toISOString()});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));approve.hidden=job.state!=='draft'||!seedPermissions.approve;section.append(approve);\n   const when=node('input');when.type='datetime-local';when.setAttribute('aria-label','配信予定日時');const schedule=node('button','確認した内容で予約する');schedule.addEventListener('click',()=>perform(async()=>{if(!consent.checked || !when.value)throw Error('配信日時と確認を入力してください。');const stamp=seedStamp();await rpc('seed_schedule',{p_job:job.id,p_version:job.version,p_when:new Date(when.value).toISOString(),p_explicit:true});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('予約しました。検証環境ではworkerの手動実行で処理します。');}}));when.hidden=schedule.hidden=job.state!=='approved'||!seedPermissions.schedule;section.append(when,schedule);\n   const immediate=node('button','確認した内容を今すぐ配信');immediate.hidden=job.state!=='approved'||!seedPermissions.schedule;immediate.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('公開する素材・本文を確認してください。');const stamp=seedStamp();await rpc('seed_now',{p_job:job.id,p_version:job.version,p_explicit:true});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('即時配信を受け付けました。検証worker処理後に表示されます。');}}));section.append(immediate);\n   const cancel=node('button','この予約・公開を取り消す');cancel.hidden=!['approved','scheduled','dispatching','published'].includes(job.state)||!seedPermissions.schedule;cancel.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('対象の予約・公開取消を確認してください。');const stamp=seedStamp();await rpc('seed_cancel',{p_job:job.id,p_version:job.version,p_explicit:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));section.append(cancel);\n   const revise=node('button','本文を変更して再審査へ');revise.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('変更と再審査を確認してください。');const stamp=seedStamp();await rpc('seed_revise',{p_job:job.id,p_version:job.version,p_photos:job.photos,p_body:body.value});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));revise.hidden=!seedPermissions.edit;section.append(revise);article.append(section);\n  }\n  const confirmStop=node('input');confirmStop.type='checkbox';const stopLabel=node('label');stopLabel.append(confirmStop,node('span','このPetの公開停止を確認する'));const stop=node('button','このPetの全公開を停止');stop.addEventListener('click',()=>perform(async()=>{if(!confirmStop.checked)throw Error('対象Petの停止を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[pet.id],p_withdraw_rights:false});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));const withdraw=node('button','掲載権利を撤回して全配信を停止');withdraw.addEventListener('click',()=>perform(async()=>{if(!confirmStop.checked)throw Error('対象Petと権利撤回を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[pet.id],p_withdraw_rights:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));stopLabel.hidden=stop.hidden=withdraw.hidden=!seedPermissions.stop;const history=node('button','このPetの画像権利履歴を表示');const historyBox=node('div');history.addEventListener('click',()=>perform(async()=>{const stamp=seedStamp();const rows=await rpc('seed_rights_history',{p_pet:pet.id});if(stamp!==seedStamp()||document.hidden)return;historyBox.replaceChildren();for(const row of rows)historyBox.append(node('p',row.recorded_at+' / '+row.operation+' / '+row.photo_id+' / '+row.rights.holder+' / '+row.rights.scope+' / '+row.rights.evidence+' / '+(row.rights.allowed?'許可':'撤回')));}));article.append(history,historyBox,stopLabel,stop,withdraw);$('seed-list').append(article);\n }\n}\n$('seed-refresh').addEventListener('click',()=>perform(refreshSeed));$('seed-search').addEventListener('input',()=>{if(seedSnapshot)renderSeed();});\n$('seed-preview-button').addEventListener('click',()=>perform(async()=>{seedItems=parseSeedCSV($('seed-csv').value);seedKey=crypto.randomUUID();$('seed-preview').replaceChildren();for(const item of seedItems)$('seed-preview').append(node('p',`${item.name} / ${item.species} / ${item.key} / 権利未確認：下書きのみ`));status('登録前のプレビューです。個別のPetログインは作成しません。');}));\n$('seed-create').addEventListener('click',()=>perform(async()=>{if(!seedItems.length || parseSeedCSV($('seed-csv').value).map(i=>JSON.stringify(i)).join()!==seedItems.map(i=>JSON.stringify(i)).join())throw Error('最新CSVのプレビューを確認してください。');const stamp=seedStamp();await rpc('seed_create',{p_publisher:$('seed-publisher').value,p_items:seedItems,p_key:seedKey});if((stamp===seedStamp() && !document.hidden)){seedItems=[];await refreshSeed();status('複数Petを同じ運営ログインで登録しました。');}}));\n\nlet seedBatchItems=[],seedBatchKey=crypto.randomUUID();\nfunction parseSeedPostCSV(text){const rows=csvRows(text);const headers=rows.shift();if(headers?.join(',')!=='pet_id,photo_ids,body,planned_at' || !rows.length || rows.length>20)throw Error('pet_id,photo_ids,body,planned_at の4列で1〜20件を入力してください。');return rows.map(row=>{if(row.length!==4)throw Error('投稿CSVの列数を確認してください。');const [pet_id,ids,body,time]=row;const photos=ids.split('|').map(v=>v.trim());const pet=seedSnapshot.pets.find(p=>p.id===pet_id.trim());if(!pet || !photos.length || photos.length>4 || new Set(photos).size!==photos.length || !photos.every(id=>pet.photos.some(p=>p.id===id && p.state==='ready')) || body.length>500)throw Error('Petと写真のひも付け・枚数・本文を確認してください。');const date=time?new Date(time):null;if(date && (!Number.isFinite(date.getTime()) || date<=new Date()))throw Error('予定日時には未来の日時を入力してください。');return {pet_id:pet.id,photos,body,planned_at:date?.toISOString()||null};});}\nfunction renderSeedCalendar(){$('seed-calendar').replaceChildren();const entries=seedSnapshot.pets.flatMap(p=>p.jobs.filter(j=>j.planned_at||j.scheduled_at).map(j=>({pet:p,job:j}))).sort((a,b)=>(a.job.scheduled_at||a.job.planned_at).localeCompare(b.job.scheduled_at||b.job.planned_at));for(const {pet,job} of entries)$('seed-calendar').append(node('p',(job.scheduled_at||job.planned_at)+' / '+pet.name+' / '+job.state+' / '+job.body));}\n$('seed-batch-preview').addEventListener('click',()=>perform(async()=>{seedBatchItems=parseSeedPostCSV($('seed-post-csv').value);seedBatchKey=crypto.randomUUID();$('seed-batch-list').replaceChildren();for(const item of seedBatchItems){const pet=seedSnapshot.pets.find(p=>p.id===item.pet_id);const row=node('article');row.append(node('p',pet.name+' / 写真 '+item.photos.length+'枚 / '+(item.planned_at||'日時未定')+' / '+item.body));for(const id of item.photos){const photo=pet.photos.find(p=>p.id===id);const preview=node('button',pet.name+'の一括投稿素材を確認 '+photo.title);preview.addEventListener('click',()=>perform(()=>previewSeedPhoto(photo,row)));row.append(preview);}$('seed-batch-list').append(row);}status('一括下書きの確認です。承認前には公開しません。');}));\n$('seed-batch-save').addEventListener('click',()=>perform(async()=>{const current=parseSeedPostCSV($('seed-post-csv').value);if(!seedBatchItems.length || JSON.stringify(current)!==JSON.stringify(seedBatchItems))throw Error('最新の一括プレビューを確認してください。');const stamp=seedStamp();await rpc('seed_draft_batch',{p_items:current,p_key:seedBatchKey});if((stamp===seedStamp() && !document.hidden)){seedBatchItems=[];$('seed-batch-list').replaceChildren();await refreshSeed();status('投稿を一括で下書き保存しました。個別に素材を確認・承認してください。');}}));\n\n$('seed-ratio-save').addEventListener('click',()=>perform(async()=>{const ratio=Number($('seed-ratio').value);if(!Number.isFinite(ratio)||ratio<0||ratio>1)throw Error('0〜1の上限比率を入力してください。');await rpc('seed_policy',{p_ratio:ratio});await refreshSeed();status('実UGC優先の運営上限比率を保存しました。');}));\n$('seed-audit-refresh').addEventListener('click',()=>perform(async()=>{const stamp=seedStamp();const rows=await rpc('seed_audit');if(stamp!==seedStamp()||document.hidden)return;$('seed-audit').replaceChildren();for(const row of rows)$('seed-audit').append(node('p',row.created_at+' / '+row.action+' / 担当 '+row.actor_id+' / Pet '+(row.pet_id||'設定')));}));\n\nasync function previewSeedPhoto(photo,container){\n const stamp=seedStamp();const response=await fetch(config.url+'/functions/v1/private-image?photo='+photo.id,{headers:{apikey:config.anon_key,Authorization:'Bearer '+token},cache:'no-store',credentials:'omit'});\n if(!response.ok||!response.headers.get('Content-Type')?.startsWith('image/'))throw Error('素材の権限・状態を再確認してください。');\n const reader=response.body.getReader();let chunks=[],total=0;\n try {while(true){const part=await reader.read();if(part.done)break;total+=part.value.byteLength;if(total>20*1024*1024||seedPreviewBytes+total>100*1024*1024)throw Error('プレビューの容量上限です。表示を更新してください。');chunks.push(part.value);}} finally {await reader.cancel();}\n if(stamp!==seedStamp()||document.hidden)return;\n const blob=new Blob(chunks,{type:response.headers.get('Content-Type')});seedPreviewBytes+=total;const url=URL.createObjectURL(blob);seedPreviewURLs.push(url);const image=node('img');image.src=url;image.alt='登録素材 '+photo.title;image.width=160;image.height=160;container.append(image);\n}\n"},"/console/admin.css":{"type":"text/css; charset=utf-8","body":"section{margin:40px 0;scroll-margin-top:20px}textarea{display:block;width:100%;max-width:100%;padding:12px;border:1px solid #b5a296;border-radius:10px;font:inherit}fieldset{border:1px solid #eadbd0;border-radius:12px;width:100%}.materials{display:flex;flex-wrap:wrap;gap:14px}.materials img{width:72px;height:72px;object-fit:cover}.materials label{max-width:160px}form>label{flex:1 1 240px}button{margin:4px}.card input,.card select{width:100%}.card .row{display:flex;gap:8px;align-items:center}.card .row input[type=checkbox]{width:20px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;text-align:left;border-bottom:1px solid #e4d3c4}.scroll-table{overflow:auto}.post{margin:14px 0;padding:20px;background:white;border-radius:20px}.post img{width:90px;height:90px;object-fit:cover;border-radius:12px}.post p{white-space:pre-wrap}.error{color:#a32921}.rights{font-size:12px;padding:8px;background:#fff8f0}.rights label{margin-top:6px}\n"},"/console/base.css":{"type":"text/css; charset=utf-8","body":":root{--background:#FFFCF8;--accent:#F65359;--text:#292625;--radius:20px;--spacing:16px}*{box-sizing:border-box}body{margin:0;background:var(--background);color:var(--text);font:16px/1.7 system-ui,sans-serif}header{display:flex;justify-content:space-between;padding:24px 6vw;border-bottom:1px solid #e5d6c8}header span{letter-spacing:.18em;font-weight:700}a{color:var(--accent)}main{max-width:1020px;margin:auto;padding:36px 24px}.notice{padding:12px 6vw;background:#45312b;color:white;font-size:13px;margin:0}h1{font-size:clamp(32px,5vw,58px);line-height:1.35;margin:16px 0 24px}h2{font-size:26px}.eyebrow{color:var(--accent)}nav{display:flex;gap:12px;margin:30px 0;flex-wrap:wrap}button{background:var(--accent);color:white;border:0;border-radius:12px;padding:12px 18px;min-height:44px;font:inherit;cursor:pointer}button:disabled{opacity:.5}form{padding:20px;margin:20px 0;background:white;border-radius:var(--radius);display:flex;gap:var(--spacing);flex-wrap:wrap;align-items:end}label{display:block;font-size:14px}input:not([type=checkbox]),select{display:block;min-height:44px;padding:10px;border:1px solid #b5a296;border-radius:8px;max-width:100%;font:inherit}input[type=checkbox]{width:20px;height:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.card{background:white;border-radius:var(--radius);padding:16px;overflow:hidden}.card img{width:100%;aspect-ratio:1;object-fit:contain;border-radius:12px}.card h3{margin:6px 0}.muted,footer{font-size:13px;color:#6b5a51}.comparison{max-width:340px;aspect-ratio:9/16;background:white;border-radius:20px;padding:20px;text-align:center;margin:24px auto;display:flex;flex-direction:column;justify-content:space-around}.comparison img{width:100%;max-height:220px;object-fit:contain}#status{min-height:30px;border-left:3px solid var(--accent);padding:8px 14px}footer{margin-top:50px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #45312b;outline-offset:3px}[hidden]{display:none!important}\n"},"/console/config.json":{"type":"application/json","body":"{\"url\": \"https://pbnimpqrthvznbwewtcf.supabase.co\", \"anon_key\": \"sb_publishable_yIFViOSjS7Qb6M2lNihRgA_Zk8n9M2m\"}"},"/console/security.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\nconst securityKinds={secret_probe:'秘密ファイル探索の疑い',path_traversal:'パス探索の疑い',injection_probe:'不正入力の疑い',auth_denied:'認証拒否',access_denied:'アクセス拒否',rate_limited:'回数制限',not_found:'404応答',method_denied:'未対応のメソッド',server_error:'サーバーエラー',profile_changed:'プロフィール変更',account_retirement:'退会の受付',operator_changed:'運営権限の変更',repeated_signals:'短時間の繰り返し検知'};\nconst securitySeverity={info:'情報',low:'低',medium:'中',high:'高',critical:'緊急'};\nconst securityOutcome={observed:'観測',denied:'拒否応答',limited:'回数制限',failed:'処理失敗',allowed:'許可'};\nconst securitySourceLabels={vercel:'Vercelサイト',app_audit:'アプリの監査記録','edge:security-collector':'ログ収集API','edge:private-image':'非公開画像API','edge:private-video':'非公開動画API','edge:public-image':'公開画像API','edge:public-video':'公開動画API','edge:shared-page':'共有ページAPI','edge:cloud-worker':'クラウド処理','edge:stock-worker':'運営投稿処理','edge:asset-ingest':'素材取り込み','edge:database-backup':'データベースバックアップ','edge:offsite-backup':'オフサイトバックアップ'};\nlet securityData=null,securityRows=[],securityCursor=null,securitySerial=0,securityTimer=null,securityView='overview';\nconst securityDrafts=new Map();\nconst sec=id=>document.getElementById(id);\nconst secNumber=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('ja-JP').format(Number(n)):'—';\nfunction secTime(value,short=false){const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',...(short?{}:{second:'2-digit'})}).format(date):'—';}\nfunction secNode(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}\nfunction secBadge(value,kind='severity'){return secNode('span',kind==='severity'?(securitySeverity[value]||'情報'):value,'sec-badge '+(['info','low','medium','high','critical'].includes(value)?value:'neutral'));}\nfunction secEmpty(parent,text='この期間の記録はありません。'){parent.replaceChildren(secNode('p',text,'sec-empty'));}\nfunction secFilters(){return {p_hours:Number(sec('sec-hours').value),p_kind:sec('sec-kind').value||null,p_severity:sec('sec-severity').value||null,p_source:sec('sec-source').value||null,p_limit:50};}\nfunction clearSecurity(){securitySerial++;securityDrafts.clear();securityData=null;securityRows=[];securityCursor=null;if(securityTimer)clearTimeout(securityTimer);securityTimer=null;const root=sec('security-section');if(root)root.hidden=true;for(const id of ['sec-events','sec-incidents','sec-sources','sec-coverage','sec-types','sec-targets','sec-chart','sec-detail-body'])sec(id)?.replaceChildren();sec('sec-detail')?.close();document.body.classList.remove('security-console');sec('main-heading').hidden=false;sec('cancel-login').hidden=false;}\nfunction secSchedule(){if(securityTimer)clearTimeout(securityTimer);securityTimer=setTimeout(()=>{if(panel==='security'&&mfaComplete&&token&&!document.hidden&&sec('sec-auto').checked&&['overview','coverage'].includes(securityView)&&!sec('sec-detail').open&&!document.querySelector('#security-section textarea:focus'))perform(()=>refreshSecurity());else secSchedule();},30000);}\nasync function refreshSecurity(more=false){\n const serial=++securitySerial,stamp=generation;\n sec('security-section').hidden=false;document.body.classList.add('security-console');sec('main-heading').hidden=true;sec('cancel-login').hidden=true;\n sec('seed-section').hidden=true;sec('queue').hidden=true;sec('seed-refresh').hidden=true;sec('refresh').hidden=true;\n sec('server-health-refresh')?.closest('details')?.setAttribute('hidden','');\n sec('sec-connection').textContent='更新中';sec('sec-connection').className='sec-status-pill';\n const filters=secFilters();if(more&&securityCursor)Object.assign(filters,{p_before:securityCursor.occurred_at,p_before_id:securityCursor.id});\n try{\n  const data=await request('/rest/v1/rpc/mefrion_security_dashboard',filters,token,false);\n  if(serial!==securitySerial||stamp!==generation||!mfaComplete||panel!=='security')return;\n  securityData=data;const incoming=(data.events||[]).slice(0,50);const next=(data.events||[]).length>50;\n  securityRows=more?[...securityRows,...incoming.filter(row=>!securityRows.some(x=>x.id===row.id))]:incoming;\n  securityCursor=next?incoming.at(-1):null;\n  sec('sec-more').hidden=!securityCursor;sec('sec-message').textContent='';status('');\n  renderSecurity(data);const recent=(data.coverage||[]).some(row=>Date.now()-new Date(row.last_seen).getTime()<900000);sec('sec-connection').textContent=recent?'最近の受信を確認':(data.coverage||[]).length?'最近の受信なし（通信がない場合も含む）':'記録元からの受信待ち';sec('sec-connection').className='sec-status-pill'+(recent?' live':'');\n  secSchedule();\n }catch(error){\n  if(serial!==securitySerial||stamp!==generation)return;\n  sec('sec-connection').textContent='確認が必要';\n  if(error.status===403){sec('sec-message').textContent='二段階認証は完了しています。セキュリティ画面を開く運営権限の有効化をお待ちください。';status(sec('sec-message').textContent);}\n  else{sec('sec-message').textContent=error.name==='TimeoutError'?'更新に時間がかかっています。もう一度更新してください。':error instanceof TypeError?'通信できませんでした。接続を確認して更新してください。':error.message;}\n  if(!securityData){for(const id of ['sec-signals','sec-suspected','sec-denied','sec-open'])sec(id).textContent='—';sec('sec-chart').textContent='取得できる記録がまだありません。';}\n  secSchedule();\n }\n}\nfunction renderSecurity(data){\n const summary=data.summary||{};\n for(const [id,key]of [['sec-signals','signals'],['sec-suspected','suspected'],['sec-denied','denied']])sec(id).textContent=secNumber(summary[key]);\n sec('sec-open').textContent=secNumber(data.open_incidents);sec('sec-nav-incidents').textContent=secNumber(data.open_incidents);\n sec('sec-updated').textContent='最終更新 '+secTime(data.generated_at)+' JST';\n sec('sec-retention').textContent='収集開始 '+secTime(data.started_at)+' JST / 詳細30日・集計90日 / 集計からテストデータを除外（受信状態を除く）';\n renderSecurityChart(data.timeline||[],data.hours);\n renderSecurityBars(sec('sec-types'),data.types||[],row=>securityKinds[row.kind]||'その他');\n renderSecurityBars(sec('sec-targets'),data.targets||[],row=>row.target);\n const sources=sec('sec-sources');sources.replaceChildren();\n for(const row of data.sources||[]){const e=secNode('div',undefined,'sec-source-row');e.append(secNode('code',row.source_key),secNode('strong',secNumber(row.n)+'件'),secNode('time','最終 '+secTime(row.last_seen)));sources.append(e);}if(!sources.children.length)secEmpty(sources,'同じ接続元をまとめられる記録はまだありません。');\n renderSecurityEvents();renderSecurityIncidents(data.incidents||[]);renderSecurityCoverage(data);\n const limitations=sec('sec-limitations');limitations.replaceChildren();for(const text of data.limitations||[])limitations.append(secNode('li',text));\n const lost=(data.coverage||[]).reduce((n,r)=>n+Number(r.lost||0),0),omitted=(data.coverage||[]).reduce((n,r)=>n+Number(r.details_omitted||0),0);\n sec('sec-quality').textContent=lost||omitted?'報告された送信失敗 '+secNumber(lost)+'件 / 保存上限による詳細省略 '+secNumber(omitted)+'件。件数は収集できた記録の範囲です。':'記録の収集はベストエフォートです。到達前の遮断や、受信できなかった通信は件数に含みません。';\n}\nfunction renderSecurityBars(parent,rows,label){parent.replaceChildren();if(!rows.length){secEmpty(parent);return;}const max=Math.max(1,...rows.map(r=>Number(r.count)));for(const row of rows){const item=secNode('div',undefined,'sec-bar-row');item.append(secNode('span',label(row)),secNode('strong',secNumber(row.count)));const track=secNode('div',undefined,'sec-bar-track'),fill=secNode('div',undefined,'sec-bar-fill');fill.style.width=(Math.max(0,Number(row.count))/max*100)+'%';track.append(fill);item.append(track);parent.append(item);}}\nfunction renderSecurityChart(rows,hours){\n const root=sec('sec-chart');root.replaceChildren();\n if(!rows.length){root.textContent='この期間に収集したシグナルはありません。';root.setAttribute('aria-label','記録0件。未収集の通信は含みません。');return;}\n const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 900 230');svg.setAttribute('aria-hidden','true');\n const make=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;svg.append(e);return e;};\n const interval=hours>168?86400000:3600000,end=Math.floor(Date.now()/interval)*interval,start=end-(hours>168?Math.ceil(hours/24)-1:hours-1)*interval;\n const lookup=new Map(rows.map(r=>[Math.floor(new Date(r.at).getTime()/interval)*interval,r]));const points=[];\n for(let t=start;t<=end;t+=interval)points.push({t,n:Number(lookup.get(t)?.signals||0),s:Number(lookup.get(t)?.suspected||0)});\n const maximum=Math.max(1,...points.map(p=>p.n)),x=i=>45+i/(Math.max(1,points.length-1))*840,y=n=>190-n/maximum*160;\n for(let i=0;i<=4;i++){const yy=190-i*40;make('line',{x1:45,x2:885,y1:yy,y2:yy,stroke:'#e7edf5','stroke-dasharray':'3 4'});make('text',{x:32,y:yy+4,'text-anchor':'end',fill:'#8291a7','font-size':10},secNumber(Math.round(maximum*i/4)));}\n make('polygon',{points:`45,190 ${points.map((p,i)=>x(i)+','+y(p.n)).join(' ')} 885,190`,fill:'#edf1ff'});\n make('polyline',{points:points.map((p,i)=>x(i)+','+y(p.n)).join(' '),fill:'none',stroke:'#5776dc','stroke-width':2.5});\n make('polyline',{points:points.map((p,i)=>x(i)+','+y(p.s)).join(' '),fill:'none',stroke:'#15b5a1','stroke-width':2});\n for(const i of [0,Math.floor((points.length-1)/3),Math.floor((points.length-1)*2/3),points.length-1]){const d=new Date(points[i].t);const label=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',...(hours>24?{month:'2-digit',day:'2-digit'}:{hour:'2-digit',minute:'2-digit'})}).format(d);make('text',{x:x(i),y:219,'text-anchor':i===0?'start':i===points.length-1?'end':'middle',fill:'#8291a7','font-size':10},label);}\n root.append(svg);root.setAttribute('aria-label',rows.map(r=>secTime(r.at,true)+' 記録'+secNumber(r.signals)+'件・攻撃の疑い'+secNumber(r.suspected||0)+'件').join('。'));\n}\nfunction renderSecurityEvents(){const body=sec('sec-events');body.replaceChildren();for(const row of securityRows){const tr=secNode('tr');tr.append(secNode('td',secTime(row.occurred_at)),secNode('td',securityKinds[row.kind]||'その他'));const severity=secNode('td');severity.append(secBadge(row.severity));tr.append(severity);const target=secNode('td');target.append(secNode('code',row.target));tr.append(target,secNode('td',(securityOutcome[row.outcome]||'観測')+' · '+row.status));const detail=secNode('td'),button=secNode('button','詳細');button.type='button';button.addEventListener('click',()=>showSecurityDetail(row));detail.append(button);tr.append(detail);body.append(tr);}if(!securityRows.length){const tr=secNode('tr'),td=secNode('td','この条件の記録はありません。','sec-empty');td.colSpan=6;tr.append(td);body.append(tr);}sec('sec-event-count').textContent=secNumber(securityRows.length)+'件を表示 / フィルターはログ一覧に適用されます。';}\nfunction showSecurityDetail(row){const dl=sec('sec-detail-body');dl.replaceChildren();for(const[key,value]of [['記録ID',row.id],['記録時刻',secTime(row.occurred_at)+' JST'],['種類',securityKinds[row.kind]||row.kind],['重要度',securitySeverity[row.severity]||'情報'],['応答',row.status+' / '+(securityOutcome[row.outcome]||'観測')],['対象',row.target],['記録元',securitySourceLabels[row.source]||row.source],['接続元ID',row.source_key==='unavailable'?'取得できず':row.source_key],['地域（参考）',row.country||'不明'],['照合用リクエストID',row.request_id||'なし']])dl.append(secNode('dt',key),secNode('dd',String(value)));sec('sec-detail').showModal();}\nfunction renderSecurityIncidents(rows){const root=sec('sec-incidents');root.replaceChildren();for(const row of rows){const card=secNode('article',undefined,'sec-incident'),head=secNode('div',undefined,'sec-incident-head');head.append(secBadge(row.severity),secNode('h3',securityKinds[row.kind]||'繰り返し検知'));card.append(head,secNode('p',secNumber(row.events)+'件 / '+row.source_key+' / 更新 '+secTime(row.updated_at)),secNode('p','状態：'+({open:'未対応',acknowledged:'確認中',resolved:'対応済み'}[row.state]||row.state)));const note=secNode('textarea');note.value=securityDrafts.get(row.id)??row.note??'';note.maxLength=400;note.addEventListener('input',()=>securityDrafts.set(row.id,note.value));note.placeholder='対応メモ（秘密情報や個人情報は書かない）';note.setAttribute('aria-label','インシデントの対応メモ');card.append(note);const actions=secNode('div',undefined,'sec-incident-controls');for(const [state,label]of [['acknowledged','確認中にする'],['resolved','対応済みにする'],['open','未対応に戻す']]){const button=secNode('button',state===row.state?'メモを保存':label);button.type='button';button.addEventListener('click',()=>perform(async()=>{try{await request('/rest/v1/rpc/mefrion_security_incident_update',{p_id:row.id,p_state:state,p_version:row.version,p_note:note.value},token,false);securityDrafts.delete(row.id);await refreshSecurity();sec('sec-message').textContent='対応状態を保存しました。';}catch(error){sec('sec-message').textContent=error.status===409?'別の更新があります。更新ボタンで再取得してください。':error.message;}}));actions.append(button);}card.append(actions);root.append(card);}if(!rows.length)secEmpty(root,'確認対象のインシデントはありません。');}\nfunction renderSecurityCoverage(data){const root=sec('sec-coverage');root.replaceChildren();const actual=new Map((data.coverage||[]).map(row=>[row.source,row]));for(const [name,label]of Object.entries(securitySourceLabels)){const row=actual.get(name),item=secNode('div',undefined,'sec-coverage-row'),text=secNode('div');text.append(secNode('strong',label));const last=row?'最終受信 '+secTime(row.last_seen)+' JST / シグナル '+secNumber(row.accepted)+'件（テスト含む）':'配備後の受信待ち。アクセスがない場合も受信待ちになります。';text.append(secNode('small',last));if(row?.lost)text.append(secNode('small','送信できなかった記録 '+secNumber(row.lost)+'件'));item.append(text,secBadge(!row?'受信待ち':Date.now()-new Date(row.last_seen).getTime()<900000?'最近の受信あり':'最近の受信なし','label'));root.append(item);}}\nfunction securityCSV(rows){const cell=value=>{let s=String(value??'');if(/^[=+\\-@\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"';};const fields=['id','occurred_at','source','kind','severity','outcome','status','target','source_key','country','request_id'];return '\\uFEFF'+[fields.map(cell).join(','),...rows.map(row=>fields.map(k=>cell(row[k])).join(','))].join('\\r\\n');}\nasync function exportSecurity(){if(!mfaComplete||!token)throw Error('運営アカウントでログインしてください。');const stamp=generation,filters={...secFilters(),p_limit:100};const rows=[];for(let i=0;i<10;i++){const data=await request('/rest/v1/rpc/mefrion_security_dashboard',filters,token,false);if(stamp!==generation)return;const batch=(data.events||[]).slice(0,100);rows.push(...batch);if((data.events||[]).length<=100||!batch.length)break;filters.p_before=batch.at(-1).occurred_at;filters.p_before_id=batch.at(-1).id;}const blob=new Blob([securityCSV(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=secNode('a');link.href=url;link.download='MEFRION-security-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);sec('sec-message').textContent=secNumber(rows.length)+'件を書き出しました（最大1,000件）。';}\nfunction secShowView(view){securityView=view;for(const el of document.querySelectorAll('[data-sec-panel]'))el.hidden=el.dataset.secPanel!==view;for(const button of document.querySelectorAll('[data-sec-view]'))button.classList.toggle('active',button.dataset.secView===view);}\nif(document.getElementById('security-section')){\n for(const [value,label] of Object.entries(securitySourceLabels)){if(!Array.from(sec('sec-source').options).some(option=>option.value===value)){const option=secNode('option',label);option.value=value;sec('sec-source').append(option);}}\n sec('sec-refresh').addEventListener('click',()=>perform(()=>refreshSecurity()));sec('sec-more').addEventListener('click',()=>perform(()=>refreshSecurity(true)));sec('sec-export').addEventListener('click',()=>perform(exportSecurity));sec('sec-detail-close').addEventListener('click',()=>sec('sec-detail').close());\n for(const id of ['sec-hours','sec-kind','sec-severity','sec-source'])sec(id).addEventListener('change',()=>perform(()=>refreshSecurity()));\n for(const button of document.querySelectorAll('[data-sec-view]'))button.addEventListener('click',()=>secShowView(button.dataset.secView));\n sec('security-nav').addEventListener('click',()=>perform(async()=>{panel='security';await refreshSecurity();}));\n sec('reports-nav').addEventListener('click',()=>perform(async()=>{panel='reports';clearSecurity();sec('server-health-refresh')?.closest('details')?.removeAttribute('hidden');sec('seed-refresh').hidden=false;sec('refresh').hidden=false;await refresh();}));\n}\n"},"/console/security.css":{"type":"text/css; charset=utf-8","body":"#security-section{--ink:#172b43;--muted:#61728b;--line:#e4eaf1;--blue:#3259d6;--mint:#11b4a0;font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:var(--ink);font-size:14px;text-align:left;line-height:1.6}body.security-console{background:#f3f6fb}body.security-console>header{display:none}body.security-console>main{max-width:1480px;padding:16px;margin:auto}#security-section *{box-sizing:border-box}#security-section button,#security-section select,#security-section input,#security-section textarea{font:inherit}#security-section button{cursor:pointer;border:1px solid #d8e0ed;background:white;color:var(--ink);border-radius:9px;padding:9px 15px;min-height:42px;margin:0}#security-section button:hover{background:#edf3ff;border-color:#b8c9ed}#security-section button:focus-visible,#security-section select:focus-visible{outline:3px solid #98b0ff;outline-offset:2px}#security-section button:disabled{cursor:wait;opacity:.55}#security-section h1,#security-section h2,#security-section h3,#security-section p{margin:0}#security-section h1{font-size:30px;letter-spacing:-.04em;color:var(--ink)}#security-section h2{font-size:16px;font-weight:700;color:var(--ink);margin-bottom:5px}#security-section h3{font-size:14px;color:var(--ink)}#security-section a{color:#3259d6;text-decoration:none}.sec-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:0;border:1px solid var(--line);border-radius:18px;overflow:clip;min-height:800px;background:#f4f7fb}.sec-sidebar{background:#12233b;color:#c6d4e9;padding:30px 18px;position:relative;display:flex;flex-direction:column}.sec-wordmark{display:flex;align-items:center;flex-wrap:wrap;gap:9px;color:#fff!important;font-size:17px;font-weight:750;letter-spacing:.025em}.sec-shield{display:grid;place-items:center;background:#13b8a6;color:#082e31;width:33px;height:36px;border-radius:9px 9px 15px 15px}.sec-wordmark-small{display:block;margin-left:43px;font-size:9px;letter-spacing:.23em;color:#8fa7c5}.sec-side-caption{margin-top:39px!important;margin-bottom:15px!important;font-size:10px;letter-spacing:.12em;color:#8ba0bd}.sec-sidebar nav{display:flex;gap:7px;flex-direction:column}.sec-sidebar nav button{border:0!important;background:transparent!important;color:#b5c7df!important;text-align:left;padding:12px 13px!important}.sec-sidebar nav button.active{background:#263c59!important;color:white!important}.sec-sidebar nav button span{float:right;background:#344d6e;border-radius:6px;min-width:23px;text-align:center;font-size:12px}.sec-side-bottom{font-size:11px;margin-top:auto;padding-top:80px}.sec-side-bottom p{font-size:10px;color:#92a9c4;margin-top:7px!important}.sec-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#29cfb5;margin-right:6px}.sec-main{min-width:0;padding:30px}.sec-top{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:0;background:none;border:0;box-shadow:none}.sec-eyebrow{font-size:10px;letter-spacing:.2em;color:#596d8c}.sec-sub{font-size:12px;color:var(--muted);margin-top:4px!important}.sec-controls{display:flex;align-items:center;gap:8px}.sec-controls select,.sec-filters select{border:1px solid #d8e0ed;border-radius:9px;padding:9px;background:white;color:var(--ink);width:auto;min-height:42px}.sec-statusline{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:11px;color:var(--muted);margin:23px 0}.sec-statusline label{margin:0 0 0 auto;display:flex;gap:7px;align-items:center}.sec-statusline input{width:15px;height:15px;margin:0}.sec-status-pill,.sec-badge{display:inline-flex;align-items:center;border-radius:20px;padding:3px 9px;font-size:11px;font-weight:600;background:#e7edf5;color:#4e6079}.sec-status-pill.live{background:#dcf6ef;color:#087363}.sec-badge.high,.sec-badge.critical{background:#fff0ef;color:#ac3844}.sec-badge.medium{background:#fff4dc;color:#8b6411}.sec-badge.low{background:#edf0ff;color:#4a5ab5}.sec-badge.info,.sec-badge.neutral{background:#edf1f6;color:#5d6a7b}.sec-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:0 0 20px}.sec-metrics article{background:white;border:1px solid var(--line);padding:18px;border-radius:12px}.sec-metrics article>span{font-size:11px;color:var(--muted)}.sec-metrics strong{display:block;font-variant-numeric:tabular-nums;font-size:31px;letter-spacing:-.04em;font-weight:750;color:var(--ink);margin:8px 0 3px}.sec-metrics article:nth-child(2) strong{color:#bc5661}.sec-metrics article:nth-child(3) strong{color:var(--blue)}.sec-metrics small{font-size:9px;color:var(--muted);display:block}.sec-card{border:1px solid var(--line);background:white;border-radius:12px;padding:22px;margin:0 0 18px}.sec-card p{font-size:12px;color:var(--muted)}.sec-card-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.sec-legend{display:flex;gap:12px;font-size:10px;white-space:nowrap}.sec-legend span:first-child{color:#4869dd}.sec-legend span+span{color:#18af9d}.sec-chart{height:230px;width:100%;display:flex;align-items:center;justify-content:center;color:var(--muted)}.sec-chart svg{width:100%;height:100%}.sec-grid-two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.sec-breakdown{margin-top:18px}.sec-bar-row{display:grid;grid-template-columns:minmax(0,1fr) 48px;gap:6px 12px;align-items:center;margin-top:13px;font-size:11px}.sec-bar-row strong{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink);font-size:12px}.sec-bar-track{height:5px;background:#eef2f8;border-radius:5px;grid-column:1/-1;overflow:hidden}.sec-bar-fill{height:100%;background:#6684e3;border-radius:5px}.sec-breakdown .sec-bar-row:nth-child(2n) .sec-bar-fill{background:#51bbaa}.sec-source-row{display:grid;grid-template-columns:1fr auto auto;gap:20px;padding:13px 0;border-bottom:1px solid #edf1f6;font-size:11px}.sec-source-row code{font-size:11px}.sec-source-row:last-child{border:0}.sec-filters{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px}.sec-filters label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-size:11px;min-width:120px;margin:0}.sec-table-wrap{overflow-x:auto}#security-section table{border-collapse:collapse;width:100%;min-width:680px;font-size:11px}#security-section th{font-weight:600;color:var(--muted);text-align:left;background:#f6f8fc;padding:11px;white-space:nowrap}#security-section td{padding:13px 11px;border-bottom:1px solid var(--line);vertical-align:middle}#security-section td button{padding:4px 10px;min-height:34px}#security-section td code{font-size:10px;overflow-wrap:anywhere}.sec-footnote{font-size:10px!important;color:var(--muted);margin-top:12px!important}.sec-empty{padding:35px 10px;text-align:center;color:var(--muted);font-size:12px}.sec-incident{padding:20px 0;border-bottom:1px solid var(--line)}.sec-incident:first-child{padding-top:0}.sec-incident-head{display:flex;align-items:center;gap:10px}.sec-incident p{margin-top:8px!important}.sec-incident-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px}.sec-incident textarea{min-height:60px;width:100%;border:1px solid #d8e0ed;border-radius:8px;padding:10px;color:var(--ink);background:white;margin-top:12px}.sec-coverage-row{display:flex;justify-content:space-between;gap:15px;padding:16px 0;border-bottom:1px solid var(--line)}.sec-coverage-row small{display:block;font-size:10px;color:var(--muted);margin-top:4px}.sec-coverage-static{margin-top:25px;display:grid;grid-template-columns:1fr 1fr;gap:16px}.sec-coverage-static article{border:1px solid var(--line);border-radius:10px;padding:17px}.sec-coverage-static .sec-badge{margin:8px 0}.sec-coverage-static a{font-size:11px;display:inline-block;margin-top:12px}.sec-footer{font-size:10px;color:var(--muted);padding:0;margin-top:22px;background:none;border:0;display:block}.sec-footer span{display:block;margin-top:6px}#sec-message:not(:empty){padding:12px 16px;margin-bottom:18px;border-radius:10px;background:#fff4da;color:#6f530c;font-size:12px}#sec-detail{max-width:600px;width:calc(100% - 32px);border:1px solid var(--line);border-radius:16px;padding:24px;color:var(--ink);background:#fff}#sec-detail::backdrop{background:#0b1c35aa}.sec-detail-head{display:flex;align-items:center;justify-content:space-between}#sec-detail-body{display:grid;grid-template-columns:110px 1fr;gap:12px;font-size:12px;margin-top:24px}#sec-detail-body dt{color:var(--muted)}#sec-detail-body dd{margin:0;overflow-wrap:anywhere;font-family:ui-monospace,monospace}#sec-detail p{font-size:11px;color:var(--muted)}.sec-sr{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}#security-section [hidden]{display:none!important}@media(max-width:1100px){.sec-layout{grid-template-columns:180px minmax(0,1fr)}.sec-main{padding:22px}.sec-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.sec-legend{display:none}}@media(max-width:720px){body.security-console>main{padding:8px}.sec-layout{display:block;border-radius:12px}.sec-sidebar{padding:16px}.sec-wordmark-small,.sec-side-caption,.sec-side-bottom{display:none!important}.sec-sidebar nav{flex-direction:row;overflow-x:auto;margin-top:16px}.sec-sidebar nav button{white-space:nowrap;min-width:100px}.sec-main{padding:18px 12px}.sec-top{align-items:flex-start;flex-direction:column}.sec-top h1{font-size:25px}.sec-controls{width:100%}.sec-controls select{flex:1}.sec-statusline label{margin-left:0}.sec-metrics{gap:10px}.sec-metrics article{padding:14px}.sec-metrics strong{font-size:27px}.sec-metrics small{min-height:27px}.sec-grid-two,.sec-coverage-static{grid-template-columns:1fr}.sec-card{padding:16px}.sec-card-head{align-items:flex-start;flex-wrap:wrap}.sec-chart{height:180px}.sec-source-row{grid-template-columns:1fr auto;gap:6px}.sec-source-row time{grid-column:1/-1}.sec-filters label{min-width:calc(50% - 8px)}.sec-filters select{width:100%}}\nbody.security-console main>.notice,body.security-console main>details,body.security-console #email-login-toggle{display:none}body.security-console #status:empty{display:none}body.security-console #session{display:flex;justify-content:flex-end;gap:8px;align-items:center;margin:0 0 14px}body.security-console #session[hidden]{display:none}body.security-console #session>button{border:1px solid #d8e0ed;background:white;color:#344963;font:600 12px ui-sans-serif,-apple-system,sans-serif;padding:8px 14px;border-radius:9px;margin:0;min-height:38px}body.security-console #session>button:hover{background:#e8effa}body.security-console #session>#logout{color:#a24454}\n@media(max-width:720px){.sec-sidebar nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0 0;padding:0;overflow:visible}.sec-sidebar nav button{min-width:0;white-space:normal;text-align:left;padding:9px 12px}.sec-sidebar{min-height:0}}\n"},"/console/security":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>セキュリティ監視｜MEFRION</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/console/seed.js\" defer></script><link rel=\"stylesheet\" href=\"/console/security.css\"><script src=\"/console/security.js\" defer></script><script src=\"/console/content.js\" defer></script><link rel=\"stylesheet\" href=\"/console/overview.css\"><script src=\"/console/overview.js\" defer></script><body data-console-panel=\"security\"><header><span>MEFRION / クラウド運営管理</span><a href=\"/console/\">一括管理へ</a></header><main><h1 id=\"main-heading\">運営管理</h1><p class=\"notice\">MEFRIONの運営管理。運営権限と認証アプリのMFAが必要です。利用者の家族アルバム原本と通報者の情報は取得しません。運営素材は担当権限で管理します。権限を付与された担当者だけが利用できます。</p><form id=\"login\"><label>運営専用のメールアドレス<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営専用のメールアドレス<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"overview-nav\" type=\"button\">ホーム</button><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><button id=\"content-nav\" type=\"button\">投稿の確認</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">最新の通報を取得</button><button id=\"logout\">ログアウト</button></div><section id=\"security-section\" hidden aria-label=\"セキュリティ監視\">\n <div class=\"sec-layout\"><aside class=\"sec-sidebar\"><a class=\"sec-wordmark\" href=\"/console/security\"><span class=\"sec-shield\">M</span> MEFRION<span class=\"sec-wordmark-small\">SECURITY</span></a><p class=\"sec-side-caption\">運営ワークスペース</p><nav aria-label=\"監視メニュー\"><button data-sec-view=\"overview\" class=\"active\">◈ 概要</button><button data-sec-view=\"events\">≋ 検知ログ</button><button data-sec-view=\"incidents\">⚑ インシデント <span id=\"sec-nav-incidents\">—</span></button><button data-sec-view=\"coverage\">◎ 監視範囲</button></nav><div class=\"sec-side-bottom\"><span class=\"sec-dot\"></span> 運営アカウント限定<p>二段階認証で保護されています</p></div></aside>\n <div class=\"sec-main\"><header class=\"sec-top\"><div><p class=\"sec-eyebrow\">SECURITY OPERATIONS</p><h1>セキュリティ</h1><p class=\"sec-sub\">起きていることを、記録から確かめる。</p></div><div class=\"sec-controls\"><label class=\"sec-sr\" for=\"sec-hours\">集計期間</label><select id=\"sec-hours\"><option value=\"24\">直近24時間</option><option value=\"168\">直近7日間</option><option value=\"720\">直近30日間</option></select><button id=\"sec-refresh\" type=\"button\">↻ 更新</button></div></header>\n <div class=\"sec-statusline\"><span id=\"sec-connection\" class=\"sec-status-pill\">接続を確認中</span><span id=\"sec-updated\">—</span><label><input id=\"sec-auto\" type=\"checkbox\" checked>概要を30秒ごとに更新</label></div>\n <div id=\"sec-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"sec-view\" data-sec-panel=\"overview\"><div class=\"sec-metrics\"><article><span>記録したシグナル</span><strong id=\"sec-signals\">—</strong><small>通常のエラー・監査記録も含む</small></article><article><span>攻撃の疑い</span><strong id=\"sec-suspected\">—</strong><small>探索・不正入力のパターン検知</small></article><article><span>拒否・制限の応答</span><strong id=\"sec-denied\">—</strong><small>401 / 403 / 404 / 405 / 429など</small></article><article><span>未対応のインシデント</span><strong id=\"sec-open\">—</strong><small>全期間・対応待ちの件数</small></article></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>シグナルの推移</h2><p>記録件数と、攻撃が疑われるパターン</p></div><div class=\"sec-legend\"><span>● 記録件数</span><span>● 攻撃の疑い</span></div></div><div id=\"sec-chart\" class=\"sec-chart\" role=\"img\" aria-label=\"集計結果の取得待ち\"></div><p class=\"sec-footnote\">時間単位の集計です。過去の未収集データは表示しません。</p></section>\n <div class=\"sec-grid-two\"><section class=\"sec-card\"><h2>検知の内訳</h2><div id=\"sec-types\" class=\"sec-breakdown\"></div></section><section class=\"sec-card\"><h2>対象になった場所</h2><div id=\"sec-targets\" class=\"sec-breakdown\"></div></section></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>繰り返し観測した接続元</h2><p>匿名化した識別子。個人や攻撃者の特定ではありません。</p></div></div><div id=\"sec-sources\"></div></section></div>\n <section class=\"sec-view sec-card\" data-sec-panel=\"events\" hidden><div class=\"sec-card-head\"><div><h2>検知ログ</h2><p>詳細を選んで、応答結果と記録IDを確認できます。</p></div><button id=\"sec-export\" type=\"button\">CSVを書き出す</button></div><div class=\"sec-filters\"><label>種類<select id=\"sec-kind\"><option value=\"\">すべての種類</option><option value=\"secret_probe\">秘密ファイル探索の疑い</option><option value=\"path_traversal\">パス探索の疑い</option><option value=\"injection_probe\">不正入力の疑い</option><option value=\"auth_denied\">認証拒否</option><option value=\"access_denied\">アクセス拒否</option><option value=\"rate_limited\">回数制限</option><option value=\"not_found\">404応答</option><option value=\"method_denied\">未対応のメソッド</option><option value=\"account_retirement\">退会の受付</option><option value=\"server_error\">サーバーエラー</option><option value=\"operator_changed\">運営権限の変更</option></select></label><label>重要度<select id=\"sec-severity\"><option value=\"\">すべて</option><option value=\"critical\">緊急</option><option value=\"high\">高</option><option value=\"medium\">中</option><option value=\"low\">低</option><option value=\"info\">情報</option></select></label><label>記録元<select id=\"sec-source\"><option value=\"\">すべて</option><option value=\"vercel\">Vercelサイト</option><option value=\"edge:private-image\">非公開画像API</option><option value=\"edge:public-image\">公開画像API</option><option value=\"edge:public-video\">公開動画API</option><option value=\"app_audit\">アプリの監査記録</option></select></label></div><div class=\"sec-table-wrap\"><table><thead><tr><th>記録時刻</th><th>種類</th><th>重要度</th><th>対象</th><th>結果</th><th>詳細</th></tr></thead><tbody id=\"sec-events\"></tbody></table></div><p id=\"sec-event-count\" class=\"sec-footnote\">—</p><button id=\"sec-more\" type=\"button\" hidden>さらに読み込む</button></section>\n <section class=\"sec-view sec-card\" data-sec-panel=\"incidents\" hidden><div class=\"sec-card-head\"><div><h2>インシデント</h2><p>同じ接続元で5分間に10件以上のシグナル、またはサーバーエラーをまとめます。</p></div></div><div id=\"sec-incidents\"></div></section>\n <section class=\"sec-view\" data-sec-panel=\"coverage\" hidden><div class=\"sec-card\"><h2>監視範囲と収集状態</h2><p>この画面に表示できる記録と、別途連携が必要な記録を区別しています。</p><div id=\"sec-coverage\"></div><div class=\"sec-coverage-static\"><article><h3>Vercel Firewall / DDoS対策</h3><span class=\"sec-badge neutral\">外部ログ未連携</span><p>Vercelがアプリ到達前に遮断した通信は、ここの件数に含まれません。</p><a href=\"https://vercel.com/toshiki-endos-projects/mefrion/firewall\" target=\"_blank\" rel=\"noopener noreferrer\">Vercelの公式画面で確認 ↗</a></article><article><h3>Supabase Auth / DB REST / Storageへの直接通信</h3><span class=\"sec-badge neutral\">拒否ログ未連携</span><p>Edge Functionを通らない直接アクセスの拒否は、この画面だけでは網羅できません。</p><a href=\"https://supabase.com/dashboard/project/pbnimpqrthvznbwewtcf/logs\" target=\"_blank\" rel=\"noopener noreferrer\">Supabaseの公式ログを開く ↗</a></article></div></div><div class=\"sec-card\"><h2>記録の取り扱い</h2><ul id=\"sec-limitations\"></ul><p>詳細ログは最大30日・10万件を目安に毎分整理し、時間別集計は最大90日、対応記録は最終更新から最大90日保存します。IPアドレス・メールアドレス・パスワード・認証コード・リクエスト本文は保存しません。ログの保存上限や送信エラーによる欠落がある場合は収集状態へ表示します。</p><p id=\"sec-retention\" class=\"sec-footnote\"></p></div></section>\n <footer class=\"sec-footer\">検知は調査の手がかりです。攻撃の確定や侵入成功を示すものではありません。<span id=\"sec-quality\"></span></footer>\n </div></div>\n <dialog id=\"sec-detail\" aria-labelledby=\"sec-detail-title\"><div class=\"sec-detail-head\"><h2 id=\"sec-detail-title\">記録の詳細</h2><button id=\"sec-detail-close\" type=\"button\" aria-label=\"詳細を閉じる\">×</button></div><dl id=\"sec-detail-body\"></dl><p>対象URLは個人情報を除去した形式です。元のIPアドレスや送信内容は記録していません。</p></dialog>\n</section>\n<!-- security-panel-end --><section id=\"content-section\" hidden aria-label=\"公開前の投稿確認\">\n <style>\n  #content-section{max-width:900px;margin:24px auto;padding:0 16px;color:#352426}\n  #content-section h2{font-size:1.5rem;margin:8px 0}\n  #content-section .content-intro{color:#6b5557;line-height:1.65}\n  #content-section .content-card{background:#fff;border:1px solid #f0d9dc;border-radius:20px;padding:20px;margin:18px 0;box-shadow:0 7px 24px #58272d12}\n  #content-section .content-card h3{margin:0 0 5px}\n  #content-section .content-card p{white-space:pre-wrap;overflow-wrap:anywhere}\n  #content-section .content-media{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:14px 0}\n  #content-section .content-media-item{background:#fff7f8;border:1px solid #f2dfe1;border-radius:14px;overflow:hidden;padding:8px}\n  #content-section .content-media img,#content-section .content-media video{display:block;width:100%;max-height:340px;object-fit:contain;background:#1c1718;border-radius:9px}\n  #content-section textarea{display:block;width:100%;box-sizing:border-box;min-height:70px;margin:14px 0;padding:12px;border:1px solid #dac8ca;border-radius:12px;font:inherit}\n  #content-section .content-actions{display:flex;flex-wrap:wrap;gap:10px}\n  #content-section button{border-radius:999px;padding:10px 16px;cursor:pointer}\n  #content-section .content-approve{background:#b92845;color:#fff;border:0}\n  #content-section .content-reject{background:#fff;color:#9a2438;border:1px solid #d4a0a8}\n  #content-section .content-muted{color:#806c70;font-size:.9rem}\n </style>\n <h2>公開前の投稿確認 🐾</h2>\n <p class=\"content-intro\">利用者の写真・動画は、確認が終わるまでおすすめに表示されません。すべてのメディアを見てから公開してください。迷ったら非公開にしてください。</p>\n <button id=\"content-refresh\" type=\"button\">一覧を更新</button>\n <p id=\"content-message\" role=\"status\" aria-live=\"polite\"></p>\n <div id=\"content-list\"></div>\n</section>\n<!-- content-panel-end --><section id=\"overview-section\" hidden aria-label=\"運営ホーム\">\n <header class=\"ops-hero\"><div><span class=\"ops-eyebrow\">MEFRION OPERATIONS</span><h1>今日の運営 🐾</h1><p>対応が必要なことを、ここから確認できます。</p></div><button id=\"ops-refresh\" type=\"button\">↻ 更新</button></header>\n <div id=\"ops-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"ops-metrics\" id=\"ops-metrics\"></div>\n <section class=\"ops-card\" aria-label=\"利用分析\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">PRODUCT ANALYTICS</span><h2>MEFRIONの成長と使い心地</h2><p id=\"product-status\">計測状況を確認しています</p></div><select id=\"product-days\" aria-label=\"分析期間\"><option value=\"7\">7日間</option><option value=\"30\" selected>30日間</option><option value=\"90\">90日間</option></select></div>\n <div id=\"product-summary\" class=\"ops-metrics\"></div>\n <h3>日ごとの利用と初回起動</h3><div id=\"product-daily\"></div>\n <h3>直近48時間の利用端末数（日本時間）</h3><div id=\"product-hourly\" class=\"product-chart\"></div><div id=\"product-hour-table\"></div>\n <h3>継続率</h3><div id=\"product-retention\"></div>\n <h3>初回利用・機能別の利用状況</h3><div id=\"product-funnel\"></div><div id=\"product-events\"></div>\n <h3>読み込み・処理の品質</h3><div id=\"product-rates\"></div><div id=\"product-quality\"></div>\n <h3>一般ユーザーと運営投稿</h3><div id=\"product-content\"></div>\n <h3>アプリのバージョン別</h3><div id=\"product-versions\"></div>\n <h3>App Store公式データ</h3><p id=\"product-apple-status\">Apple連携を確認しています</p><p class=\"ops-footnote\">毎日取得。ダウンロードは通常2日、インストールは通常5日まで更新されます。インストールはAppleへのデータ共有に同意した利用者の値で、少人数の場合は非表示です。未取得は0にしません。Appleのレポート日付を使用します。</p><div id=\"product-apple\"></div>\n <details><summary>公式数値を手動で記録（自動取得とは別）</summary><p>Apple公式画面の日別数値を転記します。空欄は未取得です。アプリ初回起動とダウンロードは異なる指標です。</p><form id=\"product-store-form\" class=\"product-store\"><label>対象日<input type=\"date\" name=\"day\" required></label><label>初回ダウンロード<input type=\"number\" name=\"first\" min=\"0\"></label><label>再ダウンロード<input type=\"number\" name=\"again\" min=\"0\"></label><label>インストール<input type=\"number\" name=\"installs\" min=\"0\"></label><button type=\"submit\">保存</button></form></details><div id=\"product-store\"></div>\n <p class=\"ops-footnote\">利用指標は新しいアプリから届いた計測のみ。端末数にはゲストを含み、複数端末・再インストールで同じ人が複数に数えられる場合があります。登録者DAUはサーバーで確認したアカウント単位です。自動アクセスや不正なクライアントによる偽装を完全には排除できないため、売上・請求・セキュリティ判断の根拠には使いません。共有ボタンはSNSを開く操作であり、投稿完了やダウンロードを示しません。画像・動画の時間は準備完了までで、画面内表示や再生開始の時間とは異なります。Xの共有リンクからApp Storeへの移動は計測します。SNS内の投稿完了・インストールへの結び付き・Apple公式DL数は上の自動連携欄で別に確認します。</p>\n </section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">TO DO</span><h2>先に見てほしいこと</h2></div></div><div id=\"ops-alerts\" class=\"ops-alerts\"></div></section>\n <div class=\"ops-grid\">\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">TODAY</span><h2>アプリの動き</h2><div id=\"ops-activity\"></div></section>\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">ACTIVITY</span><h2>最近の対応</h2><div id=\"ops-actions\"></div></section>\n </div>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SEARCH</span><h2>投稿を探す</h2><p>Pet名・投稿文・投稿IDで検索できます。</p></div></div><form id=\"ops-search-form\" class=\"ops-search\"><input id=\"ops-search\" type=\"search\" maxlength=\"80\" minlength=\"2\" placeholder=\"Pet名、投稿文、投稿ID\" required><button type=\"submit\">検索</button></form><div id=\"ops-search-results\"></div></section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SUPPORT</span><h2>問い合わせ</h2><p>メールで受けた相談の担当・期限・対応状況を記録します。</p></div><button id=\"ops-case-new\" type=\"button\">＋ 相談を記録</button></div><div id=\"ops-cases\"></div></section>\n <dialog id=\"ops-case-dialog\"><form id=\"ops-case-form\" method=\"dialog\"><h2>問い合わせを記録</h2><label>件名<input name=\"subject\" maxlength=\"160\" required></label><label>返信先メール<input name=\"email\" type=\"email\" maxlength=\"254\"></label><label>相談内容<textarea name=\"detail\" maxlength=\"4000\" rows=\"5\"></textarea></label><div class=\"ops-dialog-grid\"><label>優先度<select name=\"priority\"><option value=\"normal\">通常</option><option value=\"urgent\">至急</option></select></label><label>対応期限<input name=\"due\" type=\"datetime-local\"></label></div><div class=\"ops-dialog-actions\"><button type=\"button\" id=\"ops-case-cancel\">閉じる</button><button type=\"submit\">記録する</button></div></form></dialog>\n <dialog id=\"ops-history-dialog\"><div class=\"ops-card-head\"><h2>投稿の対応履歴</h2><button id=\"ops-history-close\" type=\"button\">閉じる</button></div><div id=\"ops-history\"></div></dialog>\n <footer class=\"ops-footnote\"><span id=\"ops-email-status\">メール通知の状態を確認中</span> · 数値は取得時点の本番データです。問い合わせメールの自動取り込みは現在連携していません。</footer>\n</section>\n<!-- overview-panel-end --><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section></main></body></html>\n"},"/console/content.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\nconst content=id=>document.getElementById(id);\nlet contentUrls=[];\nfunction clearContent(){\n for(const url of contentUrls)URL.revokeObjectURL(url);\n contentUrls=[];\n content('content-list')?.replaceChildren();\n if(content('content-section'))content('content-section').hidden=true;\n}\nasync function contentMedia(id){\n const response=await fetch(config.url+'/functions/v1/review-media?media='+encodeURIComponent(id),{\n  headers:{apikey:config.anon_key,Authorization:'Bearer '+token},cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(60000)\n });\n if(!response.ok)throw Error('メディアを読み込めませんでした。運営権限と公開前の状態を確認してください。');\n const url=URL.createObjectURL(await response.blob());contentUrls.push(url);return url;\n}\nasync function refreshContent(){\n if(!mfaComplete||!token)throw Error('運営アカウントで二段階認証を完了してください。');\n clearContent();\n content('content-section').hidden=false;\n content('queue').hidden=true;content('seed-section').hidden=true;\n content('refresh').hidden=true;content('seed-refresh').hidden=true;\n content('main-heading').textContent='公開前の投稿';\n const stamp=generation,rows=await rpc('content_review_queue');\n if(stamp!==generation||panel!=='content')return;\n const list=content('content-list');\n if(!rows.length){list.textContent='確認待ちの投稿はありません。';content('content-message').textContent='確認待ち 0 件';return;}\n content('content-message').textContent='確認待ち '+rows.length+' 件';\n for(const row of rows){\n  const card=document.createElement('article');card.className='content-card';\n  const title=node('h3',row.pet_name||'うちの子'),date=node('small',new Date(row.created_at).toLocaleString('ja-JP'));\n  const body=node('p',row.body||'本文なし'),mediaGrid=node('div');mediaGrid.className='content-media';\n  const viewed=new Set();\n  for(const media of row.media||[]){\n   const item=node('div');item.className='content-media-item';\n   const button=node('button',media.kind==='video'?'動画を確認':'写真を確認');button.type='button';\n   button.addEventListener('click',()=>perform(async()=>{\n    const url=await contentMedia(media.id),display=document.createElement(media.kind==='video'?'video':'img');\n    display.src=url;\n    if(media.kind==='video'){display.controls=true;display.playsInline=true;display.preload='metadata';}\n    else display.alt='公開前の写真';\n    item.replaceChildren(display);viewed.add(media.id);\n   }));item.append(button);mediaGrid.append(item);\n  }\n  const hint=node('p','写真・動画 '+(row.media||[]).length+' 件を確認してください。');hint.className='content-muted';\n  const note=document.createElement('textarea');note.maxLength=500;note.placeholder='判断理由（運営記録・必須）';note.setAttribute('aria-label','判断理由');\n  const actions=node('div');actions.className='content-actions';\n  for(const [approve,label,style] of [[true,'確認して公開','content-approve'],[false,'公開しない','content-reject']]){\n   const button=node('button',label);button.type='button';button.className=style;\n   button.addEventListener('click',()=>perform(async()=>{\n    if(!note.value.trim())throw Error('判断理由を入力してください。');\n    if(approve&&viewed.size!==(row.media||[]).length)throw Error('すべての写真・動画を確認してください。');\n    const result=await rpc('content_review_decide',{p_post:row.id,p_approve:approve,p_note:note.value});\n    await refreshContent();status(result.state==='approved'?'投稿を公開しました。':'投稿を非公開にしました。');\n   }));actions.append(button);\n  }\n  card.append(title,date,body,mediaGrid,hint,note,actions);list.append(card);\n }\n}\ncontent('content-nav')?.addEventListener('click',()=>perform(async()=>{\n panel='content';if(typeof clearSecurity==='function')clearSecurity();await refreshContent();\n}));\ncontent('content-refresh')?.addEventListener('click',()=>perform(refreshContent));\nfor(const id of ['reports-nav','security-nav'])content(id)?.addEventListener('click',clearContent,{capture:true});\n"},"/console/content":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>公開前の投稿｜MEFRION</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/console/seed.js\" defer></script><link rel=\"stylesheet\" href=\"/console/security.css\"><script src=\"/console/security.js\" defer></script><script src=\"/console/content.js\" defer></script><link rel=\"stylesheet\" href=\"/console/overview.css\"><script src=\"/console/overview.js\" defer></script><body data-console-panel=\"content\"><header><span>MEFRION / クラウド運営管理</span><a href=\"/console/\">一括管理へ</a></header><main><h1 id=\"main-heading\">運営管理</h1><p class=\"notice\">MEFRIONの運営管理。運営権限と認証アプリのMFAが必要です。利用者の家族アルバム原本と通報者の情報は取得しません。運営素材は担当権限で管理します。権限を付与された担当者だけが利用できます。</p><form id=\"login\"><label>運営専用のメールアドレス<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営専用のメールアドレス<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"overview-nav\" type=\"button\">ホーム</button><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><button id=\"content-nav\" type=\"button\">投稿の確認</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">最新の通報を取得</button><button id=\"logout\">ログアウト</button></div><section id=\"security-section\" hidden aria-label=\"セキュリティ監視\">\n <div class=\"sec-layout\"><aside class=\"sec-sidebar\"><a class=\"sec-wordmark\" href=\"/console/security\"><span class=\"sec-shield\">M</span> MEFRION<span class=\"sec-wordmark-small\">SECURITY</span></a><p class=\"sec-side-caption\">運営ワークスペース</p><nav aria-label=\"監視メニュー\"><button data-sec-view=\"overview\" class=\"active\">◈ 概要</button><button data-sec-view=\"events\">≋ 検知ログ</button><button data-sec-view=\"incidents\">⚑ インシデント <span id=\"sec-nav-incidents\">—</span></button><button data-sec-view=\"coverage\">◎ 監視範囲</button></nav><div class=\"sec-side-bottom\"><span class=\"sec-dot\"></span> 運営アカウント限定<p>二段階認証で保護されています</p></div></aside>\n <div class=\"sec-main\"><header class=\"sec-top\"><div><p class=\"sec-eyebrow\">SECURITY OPERATIONS</p><h1>セキュリティ</h1><p class=\"sec-sub\">起きていることを、記録から確かめる。</p></div><div class=\"sec-controls\"><label class=\"sec-sr\" for=\"sec-hours\">集計期間</label><select id=\"sec-hours\"><option value=\"24\">直近24時間</option><option value=\"168\">直近7日間</option><option value=\"720\">直近30日間</option></select><button id=\"sec-refresh\" type=\"button\">↻ 更新</button></div></header>\n <div class=\"sec-statusline\"><span id=\"sec-connection\" class=\"sec-status-pill\">接続を確認中</span><span id=\"sec-updated\">—</span><label><input id=\"sec-auto\" type=\"checkbox\" checked>概要を30秒ごとに更新</label></div>\n <div id=\"sec-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"sec-view\" data-sec-panel=\"overview\"><div class=\"sec-metrics\"><article><span>記録したシグナル</span><strong id=\"sec-signals\">—</strong><small>通常のエラー・監査記録も含む</small></article><article><span>攻撃の疑い</span><strong id=\"sec-suspected\">—</strong><small>探索・不正入力のパターン検知</small></article><article><span>拒否・制限の応答</span><strong id=\"sec-denied\">—</strong><small>401 / 403 / 404 / 405 / 429など</small></article><article><span>未対応のインシデント</span><strong id=\"sec-open\">—</strong><small>全期間・対応待ちの件数</small></article></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>シグナルの推移</h2><p>記録件数と、攻撃が疑われるパターン</p></div><div class=\"sec-legend\"><span>● 記録件数</span><span>● 攻撃の疑い</span></div></div><div id=\"sec-chart\" class=\"sec-chart\" role=\"img\" aria-label=\"集計結果の取得待ち\"></div><p class=\"sec-footnote\">時間単位の集計です。過去の未収集データは表示しません。</p></section>\n <div class=\"sec-grid-two\"><section class=\"sec-card\"><h2>検知の内訳</h2><div id=\"sec-types\" class=\"sec-breakdown\"></div></section><section class=\"sec-card\"><h2>対象になった場所</h2><div id=\"sec-targets\" class=\"sec-breakdown\"></div></section></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>繰り返し観測した接続元</h2><p>匿名化した識別子。個人や攻撃者の特定ではありません。</p></div></div><div id=\"sec-sources\"></div></section></div>\n <section class=\"sec-view sec-card\" data-sec-panel=\"events\" hidden><div class=\"sec-card-head\"><div><h2>検知ログ</h2><p>詳細を選んで、応答結果と記録IDを確認できます。</p></div><button id=\"sec-export\" type=\"button\">CSVを書き出す</button></div><div class=\"sec-filters\"><label>種類<select id=\"sec-kind\"><option value=\"\">すべての種類</option><option value=\"secret_probe\">秘密ファイル探索の疑い</option><option value=\"path_traversal\">パス探索の疑い</option><option value=\"injection_probe\">不正入力の疑い</option><option value=\"auth_denied\">認証拒否</option><option value=\"access_denied\">アクセス拒否</option><option value=\"rate_limited\">回数制限</option><option value=\"not_found\">404応答</option><option value=\"method_denied\">未対応のメソッド</option><option value=\"account_retirement\">退会の受付</option><option value=\"server_error\">サーバーエラー</option><option value=\"operator_changed\">運営権限の変更</option></select></label><label>重要度<select id=\"sec-severity\"><option value=\"\">すべて</option><option value=\"critical\">緊急</option><option value=\"high\">高</option><option value=\"medium\">中</option><option value=\"low\">低</option><option value=\"info\">情報</option></select></label><label>記録元<select id=\"sec-source\"><option value=\"\">すべて</option><option value=\"vercel\">Vercelサイト</option><option value=\"edge:private-image\">非公開画像API</option><option value=\"edge:public-image\">公開画像API</option><option value=\"edge:public-video\">公開動画API</option><option value=\"app_audit\">アプリの監査記録</option></select></label></div><div class=\"sec-table-wrap\"><table><thead><tr><th>記録時刻</th><th>種類</th><th>重要度</th><th>対象</th><th>結果</th><th>詳細</th></tr></thead><tbody id=\"sec-events\"></tbody></table></div><p id=\"sec-event-count\" class=\"sec-footnote\">—</p><button id=\"sec-more\" type=\"button\" hidden>さらに読み込む</button></section>\n <section class=\"sec-view sec-card\" data-sec-panel=\"incidents\" hidden><div class=\"sec-card-head\"><div><h2>インシデント</h2><p>同じ接続元で5分間に10件以上のシグナル、またはサーバーエラーをまとめます。</p></div></div><div id=\"sec-incidents\"></div></section>\n <section class=\"sec-view\" data-sec-panel=\"coverage\" hidden><div class=\"sec-card\"><h2>監視範囲と収集状態</h2><p>この画面に表示できる記録と、別途連携が必要な記録を区別しています。</p><div id=\"sec-coverage\"></div><div class=\"sec-coverage-static\"><article><h3>Vercel Firewall / DDoS対策</h3><span class=\"sec-badge neutral\">外部ログ未連携</span><p>Vercelがアプリ到達前に遮断した通信は、ここの件数に含まれません。</p><a href=\"https://vercel.com/toshiki-endos-projects/mefrion/firewall\" target=\"_blank\" rel=\"noopener noreferrer\">Vercelの公式画面で確認 ↗</a></article><article><h3>Supabase Auth / DB REST / Storageへの直接通信</h3><span class=\"sec-badge neutral\">拒否ログ未連携</span><p>Edge Functionを通らない直接アクセスの拒否は、この画面だけでは網羅できません。</p><a href=\"https://supabase.com/dashboard/project/pbnimpqrthvznbwewtcf/logs\" target=\"_blank\" rel=\"noopener noreferrer\">Supabaseの公式ログを開く ↗</a></article></div></div><div class=\"sec-card\"><h2>記録の取り扱い</h2><ul id=\"sec-limitations\"></ul><p>詳細ログは最大30日・10万件を目安に毎分整理し、時間別集計は最大90日、対応記録は最終更新から最大90日保存します。IPアドレス・メールアドレス・パスワード・認証コード・リクエスト本文は保存しません。ログの保存上限や送信エラーによる欠落がある場合は収集状態へ表示します。</p><p id=\"sec-retention\" class=\"sec-footnote\"></p></div></section>\n <footer class=\"sec-footer\">検知は調査の手がかりです。攻撃の確定や侵入成功を示すものではありません。<span id=\"sec-quality\"></span></footer>\n </div></div>\n <dialog id=\"sec-detail\" aria-labelledby=\"sec-detail-title\"><div class=\"sec-detail-head\"><h2 id=\"sec-detail-title\">記録の詳細</h2><button id=\"sec-detail-close\" type=\"button\" aria-label=\"詳細を閉じる\">×</button></div><dl id=\"sec-detail-body\"></dl><p>対象URLは個人情報を除去した形式です。元のIPアドレスや送信内容は記録していません。</p></dialog>\n</section>\n<!-- security-panel-end --><section id=\"content-section\" hidden aria-label=\"公開前の投稿確認\">\n <style>\n  #content-section{max-width:900px;margin:24px auto;padding:0 16px;color:#352426}\n  #content-section h2{font-size:1.5rem;margin:8px 0}\n  #content-section .content-intro{color:#6b5557;line-height:1.65}\n  #content-section .content-card{background:#fff;border:1px solid #f0d9dc;border-radius:20px;padding:20px;margin:18px 0;box-shadow:0 7px 24px #58272d12}\n  #content-section .content-card h3{margin:0 0 5px}\n  #content-section .content-card p{white-space:pre-wrap;overflow-wrap:anywhere}\n  #content-section .content-media{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:14px 0}\n  #content-section .content-media-item{background:#fff7f8;border:1px solid #f2dfe1;border-radius:14px;overflow:hidden;padding:8px}\n  #content-section .content-media img,#content-section .content-media video{display:block;width:100%;max-height:340px;object-fit:contain;background:#1c1718;border-radius:9px}\n  #content-section textarea{display:block;width:100%;box-sizing:border-box;min-height:70px;margin:14px 0;padding:12px;border:1px solid #dac8ca;border-radius:12px;font:inherit}\n  #content-section .content-actions{display:flex;flex-wrap:wrap;gap:10px}\n  #content-section button{border-radius:999px;padding:10px 16px;cursor:pointer}\n  #content-section .content-approve{background:#b92845;color:#fff;border:0}\n  #content-section .content-reject{background:#fff;color:#9a2438;border:1px solid #d4a0a8}\n  #content-section .content-muted{color:#806c70;font-size:.9rem}\n </style>\n <h2>公開前の投稿確認 🐾</h2>\n <p class=\"content-intro\">利用者の写真・動画は、確認が終わるまでおすすめに表示されません。すべてのメディアを見てから公開してください。迷ったら非公開にしてください。</p>\n <button id=\"content-refresh\" type=\"button\">一覧を更新</button>\n <p id=\"content-message\" role=\"status\" aria-live=\"polite\"></p>\n <div id=\"content-list\"></div>\n</section>\n<!-- content-panel-end --><section id=\"overview-section\" hidden aria-label=\"運営ホーム\">\n <header class=\"ops-hero\"><div><span class=\"ops-eyebrow\">MEFRION OPERATIONS</span><h1>今日の運営 🐾</h1><p>対応が必要なことを、ここから確認できます。</p></div><button id=\"ops-refresh\" type=\"button\">↻ 更新</button></header>\n <div id=\"ops-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"ops-metrics\" id=\"ops-metrics\"></div>\n <section class=\"ops-card\" aria-label=\"利用分析\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">PRODUCT ANALYTICS</span><h2>MEFRIONの成長と使い心地</h2><p id=\"product-status\">計測状況を確認しています</p></div><select id=\"product-days\" aria-label=\"分析期間\"><option value=\"7\">7日間</option><option value=\"30\" selected>30日間</option><option value=\"90\">90日間</option></select></div>\n <div id=\"product-summary\" class=\"ops-metrics\"></div>\n <h3>日ごとの利用と初回起動</h3><div id=\"product-daily\"></div>\n <h3>直近48時間の利用端末数（日本時間）</h3><div id=\"product-hourly\" class=\"product-chart\"></div><div id=\"product-hour-table\"></div>\n <h3>継続率</h3><div id=\"product-retention\"></div>\n <h3>初回利用・機能別の利用状況</h3><div id=\"product-funnel\"></div><div id=\"product-events\"></div>\n <h3>読み込み・処理の品質</h3><div id=\"product-rates\"></div><div id=\"product-quality\"></div>\n <h3>一般ユーザーと運営投稿</h3><div id=\"product-content\"></div>\n <h3>アプリのバージョン別</h3><div id=\"product-versions\"></div>\n <h3>App Store公式データ</h3><p id=\"product-apple-status\">Apple連携を確認しています</p><p class=\"ops-footnote\">毎日取得。ダウンロードは通常2日、インストールは通常5日まで更新されます。インストールはAppleへのデータ共有に同意した利用者の値で、少人数の場合は非表示です。未取得は0にしません。Appleのレポート日付を使用します。</p><div id=\"product-apple\"></div>\n <details><summary>公式数値を手動で記録（自動取得とは別）</summary><p>Apple公式画面の日別数値を転記します。空欄は未取得です。アプリ初回起動とダウンロードは異なる指標です。</p><form id=\"product-store-form\" class=\"product-store\"><label>対象日<input type=\"date\" name=\"day\" required></label><label>初回ダウンロード<input type=\"number\" name=\"first\" min=\"0\"></label><label>再ダウンロード<input type=\"number\" name=\"again\" min=\"0\"></label><label>インストール<input type=\"number\" name=\"installs\" min=\"0\"></label><button type=\"submit\">保存</button></form></details><div id=\"product-store\"></div>\n <p class=\"ops-footnote\">利用指標は新しいアプリから届いた計測のみ。端末数にはゲストを含み、複数端末・再インストールで同じ人が複数に数えられる場合があります。登録者DAUはサーバーで確認したアカウント単位です。自動アクセスや不正なクライアントによる偽装を完全には排除できないため、売上・請求・セキュリティ判断の根拠には使いません。共有ボタンはSNSを開く操作であり、投稿完了やダウンロードを示しません。画像・動画の時間は準備完了までで、画面内表示や再生開始の時間とは異なります。Xの共有リンクからApp Storeへの移動は計測します。SNS内の投稿完了・インストールへの結び付き・Apple公式DL数は上の自動連携欄で別に確認します。</p>\n </section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">TO DO</span><h2>先に見てほしいこと</h2></div></div><div id=\"ops-alerts\" class=\"ops-alerts\"></div></section>\n <div class=\"ops-grid\">\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">TODAY</span><h2>アプリの動き</h2><div id=\"ops-activity\"></div></section>\n  <section class=\"ops-card\"><span class=\"ops-eyebrow\">ACTIVITY</span><h2>最近の対応</h2><div id=\"ops-actions\"></div></section>\n </div>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SEARCH</span><h2>投稿を探す</h2><p>Pet名・投稿文・投稿IDで検索できます。</p></div></div><form id=\"ops-search-form\" class=\"ops-search\"><input id=\"ops-search\" type=\"search\" maxlength=\"80\" minlength=\"2\" placeholder=\"Pet名、投稿文、投稿ID\" required><button type=\"submit\">検索</button></form><div id=\"ops-search-results\"></div></section>\n <section class=\"ops-card\"><div class=\"ops-card-head\"><div><span class=\"ops-eyebrow\">SUPPORT</span><h2>問い合わせ</h2><p>メールで受けた相談の担当・期限・対応状況を記録します。</p></div><button id=\"ops-case-new\" type=\"button\">＋ 相談を記録</button></div><div id=\"ops-cases\"></div></section>\n <dialog id=\"ops-case-dialog\"><form id=\"ops-case-form\" method=\"dialog\"><h2>問い合わせを記録</h2><label>件名<input name=\"subject\" maxlength=\"160\" required></label><label>返信先メール<input name=\"email\" type=\"email\" maxlength=\"254\"></label><label>相談内容<textarea name=\"detail\" maxlength=\"4000\" rows=\"5\"></textarea></label><div class=\"ops-dialog-grid\"><label>優先度<select name=\"priority\"><option value=\"normal\">通常</option><option value=\"urgent\">至急</option></select></label><label>対応期限<input name=\"due\" type=\"datetime-local\"></label></div><div class=\"ops-dialog-actions\"><button type=\"button\" id=\"ops-case-cancel\">閉じる</button><button type=\"submit\">記録する</button></div></form></dialog>\n <dialog id=\"ops-history-dialog\"><div class=\"ops-card-head\"><h2>投稿の対応履歴</h2><button id=\"ops-history-close\" type=\"button\">閉じる</button></div><div id=\"ops-history\"></div></dialog>\n <footer class=\"ops-footnote\"><span id=\"ops-email-status\">メール通知の状態を確認中</span> · 数値は取得時点の本番データです。問い合わせメールの自動取り込みは現在連携していません。</footer>\n</section>\n<!-- overview-panel-end --><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section></main></body></html>\n"},"/console/overview.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\nconst ops=id=>document.getElementById(id);\nconst opsNode=(tag,value)=>{const el=document.createElement(tag);if(value!==undefined)el.textContent=String(value);return el;};\nconst opsCount=value=>new Intl.NumberFormat('ja-JP').format(Number(value)||0);\nconst opsDate=value=>value?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)):'—';\nlet opsCases=[],opsStamp=0,opsTimer=null,opsPreviousAttention=null;\nfunction clearOverview(event){opsStamp++;if(opsTimer)clearTimeout(opsTimer);opsTimer=null;document.body.classList.remove('ops-console');document.title='MEFRION クラウド運営管理';ops('overview-section').hidden=true;ops('ops-search-results').replaceChildren();ops('ops-case-dialog')?.close();ops('ops-history-dialog')?.close();if(event?.currentTarget){for(const id of ['overview-nav','reports-nav','content-nav','security-nav','seed-refresh'])ops(id)?.classList.toggle('active',id===event.currentTarget.id);}}\nfunction scheduleOverview(){if(opsTimer)clearTimeout(opsTimer);opsTimer=setTimeout(()=>{if(panel==='overview'&&mfaComplete&&token&&!document.hidden&&!busy&&!ops('ops-case-dialog').open&&!ops('ops-history-dialog').open&&!document.querySelector('#overview-section input:focus,#overview-section textarea:focus,#overview-section select:focus'))perform(refreshOverview);else scheduleOverview();},60000);}\nfunction opsNav(){for(const id of ['overview-nav','reports-nav','content-nav','security-nav','seed-refresh'])ops(id)?.classList.toggle('active',id==='overview-nav');}\nfunction opsMetric(label,value,hint){const card=opsNode('article');card.className='ops-metric';card.append(opsNode('span',label),opsNode('strong',opsCount(value)),opsNode('small',hint));return card;}\nfunction opsLine(label,value){const row=opsNode('div');row.className='ops-statline';row.append(opsNode('span',label),opsNode('strong',value));return row;}\nfunction opsAlert(title,detail,nav,urgent=false){const card=opsNode('div');card.className='ops-alert'+(urgent?' urgent':'');card.append(opsNode('strong',title),opsNode('p',detail));if(nav){const button=opsNode('button','確認する →');button.type='button';button.addEventListener('click',()=>ops(nav)?.click());card.append(button);}return card;}\nasync function refreshOverview(){\n if(!mfaComplete||!token)throw Error('運営アカウントで二段階認証を完了してください。');\n if(typeof clearSecurity==='function')clearSecurity();if(typeof clearContent==='function')clearContent();\n panel='overview';document.body.classList.add('ops-console');ops('overview-section').hidden=false;ops('queue').hidden=true;ops('seed-section').hidden=true;\n ops('main-heading').hidden=true;ops('refresh').hidden=true;ops('seed-refresh').hidden=false;\n ops('server-health-refresh')?.closest('details')?.removeAttribute('hidden');opsNav();\n const stamp=++opsStamp;ops('ops-message').textContent='更新中…';\n try{\n  const [data,cases,delivery]=await Promise.all([rpc('operator_workspace'),rpc('operator_case_list'),rpc('operator_alert_status')]);\n  if(stamp!==opsStamp||panel!=='overview')return;\n  opsCases=cases;renderOverview(data);renderCases(cases);\n  ops('ops-email-status').textContent=delivery.last_sent_at?'メール通知：最終送信 '+opsDate(delivery.last_sent_at):'メール通知：初回送信待ち';\n  if(delivery.last_failure_at&&(!delivery.last_sent_at||new Date(delivery.last_failure_at)>new Date(delivery.last_sent_at)))ops('ops-email-status').textContent='メール通知：送信エラーを確認してください';\n  ops('ops-message').textContent='';status('運営ホームを更新しました。');scheduleOverview();await refreshProductAnalytics();\n }catch(error){if(stamp===opsStamp)ops('ops-message').textContent=error.message;throw error;}\n}\nfunction renderOverview(data){\n const attention=Number(data.pending_reports)+Number(data.pending_posts)+Number(data.overdue_cases)+Number(data.failed_jobs);\n document.title=(attention>0?'● '+attention+'件 · ':'')+'MEFRION 運営管理';\n if(opsPreviousAttention!==null&&attention>opsPreviousAttention&&globalThis.Notification?.permission==='granted')new globalThis.Notification('MEFRIONの確認事項が増えました',{body:'運営ダッシュボードを開いて確認してください。'});\n opsPreviousAttention=attention;\n const metrics=ops('ops-metrics');metrics.replaceChildren(\n  opsMetric('未対応の通報',data.pending_reports,'通報を確認'),\n  opsMetric('公開前の投稿',data.pending_posts,'写真・動画の確認'),\n  opsMetric('対応中の相談',data.open_cases,'メールの相談を記録'),\n  opsMetric('直近24時間の登録',data.signups_24h,'新しく登録した人')\n );\n const alerts=ops('ops-alerts');alerts.replaceChildren();\n if(data.pending_reports>0)alerts.append(opsAlert('通報が '+opsCount(data.pending_reports)+' 件あります','内容を確認し、対応を記録してください。','reports-nav',true));\n if(data.pending_posts>0)alerts.append(opsAlert('公開待ち '+opsCount(data.pending_posts)+' 件','最も古い投稿：'+opsDate(data.pending_posts_oldest),'content-nav',true));\n if(data.overdue_cases>0)alerts.append(opsAlert('期限を過ぎた相談 '+opsCount(data.overdue_cases)+' 件','問い合わせ一覧で対応状況を確認してください。',null,true));\n if(data.failed_jobs>0)alerts.append(opsAlert('失敗した処理 '+opsCount(data.failed_jobs)+' 件','サーバー稼働状況を確認してください。',null,true));\n if(data.server_errors_24h>0)alerts.append(opsAlert('サーバーエラー '+opsCount(data.server_errors_24h)+' 件','直近24時間に記録したエラーです。','security-nav'));\n if(!alerts.children.length)alerts.append(opsAlert('いま急ぎの対応はありません','新しい通報や公開待ち投稿が入ると、ここに表示します。'));\n const activity=ops('ops-activity');activity.replaceChildren(\n  opsLine('公開投稿（直近24時間）',opsCount(data.published_24h)),\n  opsLine('公開中の投稿',opsCount(data.published_total)),\n  opsLine('7日以内の登録者',opsCount(data.signups_7d)),\n  opsLine('7日以内の登録者で初投稿済み',opsCount(data.new_users_first_post_7d)),\n  opsLine('30日以内に別の日にも投稿した人',opsCount(data.returning_posters_30d)),\n  opsLine('写真・動画の保存量',formatBytes(data.storage_bytes)),\n  opsLine('データベース容量',formatBytes(data.database_bytes))\n );\n const actions=ops('ops-actions');actions.replaceChildren();\n for(const action of data.recent_actions||[]){const row=opsNode('div');row.className='ops-action';row.append(opsNode('span',action.category+' · '+action.action),opsNode('small',opsDate(action.at)));actions.append(row);}\n if(!actions.children.length)actions.append(opsNode('p','最近の対応記録はありません。'));\n}\nfunction formatBytes(bytes){const n=Number(bytes)||0;return n>=1073741824?(n/1073741824).toFixed(1)+' GB':n>=1048576?(n/1048576).toFixed(1)+' MB':opsCount(n)+' B';}\nfunction renderCases(rows){\n const root=ops('ops-cases');root.replaceChildren();\n if(!rows.length){const p=opsNode('p','記録した問い合わせはまだありません。');p.className='ops-empty';root.append(p);return;}\n for(const row of rows){\n  const item=opsNode('article');item.className='ops-case';\n  const main=opsNode('div');main.className='ops-case-main';\n  main.append(opsNode('strong',row.subject));\n  const details=opsNode('p',(row.contact_email||'返信先なし')+' · '+opsDate(row.created_at));main.append(details);\n  if(row.contact_email){const reply=opsNode('a','メールで返信 ↗');reply.href='mailto:'+encodeURIComponent(row.contact_email)+'?subject='+encodeURIComponent('Re: '+row.subject);reply.rel='noreferrer';main.append(reply);}\n  if(row.detail)main.append(opsNode('p',row.detail));\n  const badge=opsNode('span',row.state==='resolved'?'解決':row.state==='waiting'?'回答待ち':'対応中');badge.className='ops-chip'+(row.priority==='urgent'?' urgent':'');main.append(badge);\n  if(row.due_at)main.append(opsNode('small',' 期限 '+opsDate(row.due_at)));\n  main.append(opsNode('small',' · 担当 '+(row.assigned_email||'未割当')));\n  const controls=opsNode('div');controls.className='ops-case-controls';\n  const state=opsNode('select');state.setAttribute('aria-label',row.subject+' の状態');\n  for(const [value,label] of [['open','対応中'],['waiting','回答待ち'],['resolved','解決']]){const option=opsNode('option',label);option.value=value;state.append(option);}state.value=row.state;\n  const priority=opsNode('select');priority.setAttribute('aria-label',row.subject+' の優先度');\n  for(const [value,label] of [['normal','通常'],['urgent','至急']]){const option=opsNode('option',label);option.value=value;priority.append(option);}priority.value=row.priority;\n  const assignment=opsNode('select');assignment.setAttribute('aria-label',row.subject+' の担当');\n  for(const [value,label] of [['unassigned','担当なし'],['mine','自分が担当']]){const option=opsNode('option',label);option.value=value;assignment.append(option);}assignment.value=row.mine?'mine':'unassigned';\n  const due=opsNode('input');due.type='datetime-local';due.setAttribute('aria-label',row.subject+' の対応期限');if(row.due_at)due.value=new Date(new Date(row.due_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);\n  const note=opsNode('textarea');note.maxLength=2000;note.placeholder='解決時は対応内容を入力';note.value=row.resolution||'';\n  const save=opsNode('button','保存');save.type='button';save.addEventListener('click',()=>perform(async()=>{\n   await rpc('operator_case_update',{p_id:row.id,p_version:row.version,p_state:state.value,p_priority:priority.value,p_due_at:due.value?new Date(due.value).toISOString():null,p_resolution:note.value,p_assign_to_me:assignment.value==='mine'});\n   await refreshOverview();status('問い合わせを更新しました。');\n  }));if(row.assigned_to&&!row.mine){save.disabled=true;save.title='別の担当者が対応中です。';}\n  controls.append(state,priority,assignment,due,note,save);item.append(main,controls);root.append(item);\n }\n}\nfunction renderPostResults(rows){\n const root=ops('ops-search-results');root.replaceChildren();\n if(!rows.length){const p=opsNode('p','該当する公開投稿はありません。');p.className='ops-empty';root.append(p);return;}\n for(const row of rows){const item=opsNode('article');item.className='ops-result';const main=opsNode('div');main.className='ops-result-main';\n  main.append(opsNode('strong',row.pet_name+' · '+({published:'公開中',review:'確認待ち',stopped:'停止',processing:'処理中',pending:'準備中'}[row.state]||row.state)));\n  main.append(opsNode('p',row.body||'本文なし'),opsNode('small',opsDate(row.created_at)+' · '+row.id+' · 通報 '+opsCount(row.reports)+' 件'));\n  const button=opsNode('button','対応履歴');button.type='button';button.addEventListener('click',()=>perform(async()=>{\n   const history=await rpc('operator_post_history',{p_post:row.id});showPostHistory(row,history);\n  }));item.append(main,button);root.append(item);\n }\n}\nfunction showPostHistory(row,data){const root=ops('ops-history');root.replaceChildren();root.append(opsNode('p',row.pet_name+' · '+row.id));\n const review=data.review;if(review)root.append(opsNode('p','公開前確認：'+review.state+' / '+opsDate(review.decided_at)+' / '+review.reviewer+' / '+(review.note||'理由なし')));\n for(const report of data.reports||[])root.append(opsNode('p','通報：'+report.reason+' / '+report.state+' / '+opsDate(report.created_at)));\n for(const decision of data.decisions||[])root.append(opsNode('p','対応：'+decision.decision+' / '+opsDate(decision.created_at)+' / '+decision.reviewer+' / '+decision.note));\n if(!root.children.length)root.append(opsNode('p','対応履歴はありません。'));ops('ops-history-dialog').showModal();}\nops('overview-nav')?.addEventListener('click',()=>perform(refreshOverview));\nops('ops-refresh')?.addEventListener('click',()=>perform(refreshOverview));\nops('ops-search-form')?.addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n const query=ops('ops-search').value.trim();if(query.length<2)throw Error('2文字以上で検索してください。');\n ops('ops-search-results').textContent='検索中…';renderPostResults(await rpc('operator_post_search',{p_query:query,p_limit:30}));\n});});\nops('ops-case-new')?.addEventListener('click',()=>ops('ops-case-dialog').showModal());\nops('ops-case-cancel')?.addEventListener('click',()=>ops('ops-case-dialog').close());\nops('ops-case-form')?.addEventListener('submit',event=>{event.preventDefault();const formElement=event.currentTarget;perform(async()=>{\n const form=new FormData(formElement),due=form.get('due');\n await rpc('operator_case_create',{p_subject:form.get('subject'),p_contact_email:form.get('email'),p_detail:form.get('detail'),p_priority:form.get('priority'),p_due_at:due?new Date(due).toISOString():null});\n ops('ops-case-dialog').close();formElement.reset();await refreshOverview();status('問い合わせを記録しました。');\n});});\nops('ops-history-close')?.addEventListener('click',()=>ops('ops-history-dialog').close());\nfor(const id of ['reports-nav','security-nav','content-nav','seed-refresh'])ops(id)?.addEventListener('click',clearOverview,{capture:true});\n\nfunction productTable(id,headers,rows){const root=ops(id);root.replaceChildren();if(!rows?.length){root.append(opsNode('p','まだ計測データがありません。'));return;}const wrap=opsNode('div');wrap.className='product-scroll';const table=opsNode('table');table.className='product-table';const download=opsNode('button','CSV');download.type='button';download.addEventListener('click',()=>{const cell=v=>'\\\"'+String(v??'').replace(/^[\\s\\u0000-\\u001f]*[=+@-]/,\"'$&\").replaceAll('\\\"','\\\"\\\"')+'\\\"';const csv='\\uFEFF'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=opsNode('a');link.href=url;link.download='MEFRION-'+id+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});root.append(download);const head=opsNode('tr');for(const h of headers)head.append(opsNode('th',h));const thead=opsNode('thead');thead.append(head);table.append(thead);const body=opsNode('tbody');for(const values of rows){const tr=opsNode('tr');for(const value of values)tr.append(opsNode('td',value??'未取得'));body.append(tr);}table.append(body);wrap.append(table);root.append(wrap);}\nasync function refreshProductAnalytics(){\n const stamp=generation;\n try{\n const data=await rpc('operator_product_analytics',{p_days:Number(ops('product-days').value)});\n if(stamp!==generation||panel!=='overview')return;\n ops('product-status').textContent=data.started_at?'計測開始 '+opsDate(data.started_at)+' / 集計は日本時間':'対応アプリからの初回データ待ち。過去の利用履歴は推定しません。';\n ops('product-summary').replaceChildren(opsMetric('DAU（端末）',data.devices.dau,'今日・ゲスト含む'),opsMetric('WAU（端末）',data.devices.wau,'直近7日'),opsMetric('MAU（端末）',data.devices.mau,'直近30日'),opsMetric('現在の登録者',data.registered.total,'メール確認済み・ゲスト等を除く'));\n const daily=data.daily||[];productTable('product-daily',['日付','利用端末','登録者の利用','起動セッション','初回起動','登録確認済み人数'],daily.map(r=>[r.day,r.devices,r.members,r.sessions,r.first_opens,r.new_accounts]));\n const c=data.collection;if(c){const warning=c.events_today>=c.daily_limit||c.stored_events>=c.storage_limit;ops('product-status').append(document.createTextNode(' / 直近24時間 '+opsCount(c.events_today)+'イベント・保存 '+opsCount(c.stored_events)+'件'+(warning?'：計測上限のため一部データが欠ける可能性があります。':' / 生イベント90日保存')));}\n const chart=ops('product-hourly');chart.replaceChildren();const lookup=new Map((data.hourly||[]).map(r=>[r.hour.slice(0,13),r]));const hours=Array.from({length:48},(_,i)=>{const key=new Date(Date.now()+9*3600000-(47-i)*3600000).toISOString().slice(0,13);return lookup.get(key)||{hour:key+':00',devices:0,sessions:0};});const maximum=Math.max(1,...hours.map(r=>r.devices));for(const row of hours){const bar=opsNode('div');bar.style.height=Math.max(2,row.devices/maximum*120)+'px';bar.title=row.hour+' / '+row.devices+'端末 / '+row.sessions+'起動';bar.setAttribute('aria-label',bar.title);chart.append(bar);}if(!hours.length)chart.textContent='時間別の利用データ待ち';\n productTable('product-retention',['初回観測から','対象端末','再利用端末','継続率'],(data.retention||[]).map(r=>[r.day+'日後',r.eligible,r.returned,r.eligible?(100*r.returned/r.eligible).toFixed(1)+'%':'対象期間待ち']));\n productTable('product-funnel',['初回起動した端末','起動後に登録確認','登録後に投稿受付'],[[data.funnel.first_open,data.funnel.registered_after_open,data.funnel.posted_after_registration]]);\n productTable('product-hour-table',['時刻(JST)','アプリ利用端末','起動回数','計測イベント数','共有リンクの到着'],hours.map(r=>[r.hour,r.devices,r.sessions,r.events||0,r.share_visits||0]));\n const labels={first_open:'初回観測した起動',session:'起動セッション',active:'利用中',tab:'タブ表示',signup_start:'登録開始',signup_success:'メール登録確認',post_start:'投稿送信開始',post_success:'投稿受付成功',post_failure:'投稿受付失敗',album_open:'アルバム表示',album_save:'アルバム保存',twins_start:'そっくり検索開始',twins_success:'検索結果取得',twins_failure:'検索失敗',share_visit:'共有リンクからApp Storeへ移動',share_open:'共有先を開く',share_complete:'共有完了',image_ready:'画像準備完了',image_failure:'画像準備失敗',video_ready:'動画準備完了',video_failure:'動画準備失敗',request_success:'通信成功',request_failure:'通信失敗'};\n const events=data.events||[];productTable('product-events',['操作','区分','回数','端末数'],events.map(r=>[labels[r.name]||r.name,r.detail||'—',r.n,r.devices]));\n const rateRows=[];for(const [success,failure,label] of [['twins_success','twins_failure','そっくり検索'],['post_success','post_failure','投稿受付'],['image_ready','image_failure','画像準備'],['video_ready','video_failure','動画準備']]){const ok=events.filter(r=>r.name===success).reduce((a,r)=>a+Number(r.n),0),bad=events.filter(r=>r.name===failure).reduce((a,r)=>a+Number(r.n),0);rateRows.push([label,ok,bad,ok+bad?(100*ok/(ok+bad)).toFixed(1)+'%':'未計測']);}productTable('product-rates',['処理','成功','失敗','成功率'],rateRows);\n productTable('product-quality',['処理','区分','件数','中央値(ms)','95%(ms)'],events.filter(r=>r.p50_ms!==null).map(r=>[labels[r.name]||r.name,r.detail||'—',r.n,Math.round(r.p50_ms),Math.round(r.p95_ms)]));\n productTable('product-content',['一般投稿','一般投稿者','運営投稿'],[[data.content.user_posts,data.content.user_posters,data.content.managed_posts]]);\n productTable('product-versions',['バージョン','端末数','失敗イベント'],(data.versions||[]).map(r=>[r.app_version,r.devices,r.failures]));\n productTable('product-store',['日付','初回DL','再DL','インストール'],(data.store||[]).map(r=>[r.day,r.first_downloads,r.redownloads,r.installations]));\n try{const apple=await rpc('operator_apple_metrics',{p_days:Number(ops('product-days').value)});if(stamp!==generation||panel!=='overview')return;const states={not_configured:'Apple接続設定待ち',request_required:'Appleで継続レポートの生成設定が必要',awaiting_reports:'Appleのレポート生成待ち',ok:'自動連携中',apple_auth:'Appleの権限・キーを確認してください'};ops('product-apple-status').textContent=(states[apple.status]||'同期エラー・再試行待ち')+' / 最終確認 '+opsDate(apple.last_attempt)+' / 最終取得 '+opsDate(apple.last_success);productTable('product-apple',['日付（Apple）','初回DL','再DL','インストール（同意利用者）','DL処理日','インストール処理日'],(apple.days||[]).map(r=>[r.day,r.first_downloads,r.redownloads,r.installations,r.download_processed,r.install_processed]));}catch{ops('product-apple-status').textContent='Apple自動連携の状態を取得できません。';}\n ops('product-content').append(opsLine('アルバム利用端末',opsCount(data.album.devices)),opsLine('別の日にもアルバムを見た端末',opsCount(data.album.returning)));\n ops('product-summary').append(opsMetric('登録者DAU',data.registered.dau,'今日・アカウント単位'),opsMetric('登録者WAU',data.registered.wau,'直近7日'),opsMetric('登録者MAU',data.registered.mau,'直近30日'));\n }catch{ops('product-status').textContent='利用分析を取得できません。接続と本番への配備状況を確認してください。';}\n}\nops('product-days')?.addEventListener('change',()=>perform(refreshProductAnalytics));\nops('product-store-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);perform(async()=>{const number=k=>f.get(k)===''?null:Number(f.get(k));await rpc('operator_store_metric',{p_day:f.get('day'),p_first:number('first'),p_again:number('again'),p_installs:number('installs')});await refreshProductAnalytics();});});\n"},"/console/overview.css":{"type":"text/css; charset=utf-8","body":"#session{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 0 18px}\n#session>button{border:1px solid #ebd8dd;background:#fff;color:#653942;border-radius:999px;padding:9px 15px;font-weight:700;cursor:pointer}\n#session>button.active{background:#b62d4a;color:#fff;border-color:#b62d4a}\n#session>details{width:100%;order:2}\n#overview-section{max-width:1180px;margin:0 auto 60px;color:#34292c;font-family:-apple-system,BlinkMacSystemFont,'Hiragino Kaku Gothic ProN',sans-serif}\n#overview-section *{box-sizing:border-box}\n#overview-section button{cursor:pointer;font:inherit}\n.ops-hero{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:12px 0 24px;padding:30px 32px;border-radius:28px;background:linear-gradient(120deg,#fff4f2,#ffe8eb 55%,#fbeef6);box-shadow:0 12px 35px #a34c6214}\n.ops-hero h1{font-size:clamp(1.8rem,4vw,2.6rem);letter-spacing:-.04em;margin:8px 0 6px}\n.ops-hero p,.ops-card-head p{margin:0;color:#7a6268}\n.ops-eyebrow{font-size:.69rem;font-weight:800;letter-spacing:.18em;color:#bc5971}\n.ops-hero>button,.ops-search button,.ops-card-head>button,.ops-dialog-actions button:last-child{border:0;background:#b82e4c;color:#fff;border-radius:999px;padding:11px 19px;font-weight:700;white-space:nowrap}\n#ops-message:not(:empty){margin:12px 0;padding:12px 15px;border-radius:15px;background:#fff7ee;color:#895220}\n.ops-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}\n.ops-metric{background:#fff;border:1px solid #f2e6e8;border-radius:22px;padding:20px;box-shadow:0 4px 22px #4c1b2910}\n.ops-metric span{display:block;color:#826e72;font-size:.88rem}.ops-metric strong{display:block;color:#2f2527;font-size:2rem;line-height:1.3}.ops-metric small{color:#a28f93}\n.ops-card{background:#fff;border:1px solid #f2e6e8;border-radius:24px;padding:24px;margin:16px 0;box-shadow:0 4px 22px #4c1b2910}\n.ops-card h2{font-size:1.2rem;margin:5px 0 12px}.ops-card-head{display:flex;justify-content:space-between;align-items:start;gap:12px}\n.ops-alerts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.ops-alert{padding:15px 18px;border-radius:16px;background:#fff7f7;border:1px solid #f5e0e4}.ops-alert.urgent{background:#fff0ee;border-color:#efc6c7}.ops-alert strong{display:block}.ops-alert p{margin:5px 0;color:#765c63;font-size:.88rem}.ops-alert button{border:0;background:none;color:#b62d4a;font-weight:700;padding:5px 0}\n.ops-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.ops-grid .ops-card{margin:0}\n.ops-statline,.ops-action,.ops-case,.ops-result{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid #f2e9ea;padding:12px 0}.ops-statline:first-child,.ops-action:first-child,.ops-case:first-child,.ops-result:first-child{border-top:0}\n.ops-statline strong{font-size:1.1rem}.ops-action small,.ops-case small,.ops-result small{color:#948186}.ops-case-main,.ops-result-main{min-width:0}.ops-case-main strong,.ops-result-main strong{display:block}.ops-case-main p,.ops-result-main p{margin:3px 0;color:#785f65;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.ops-chip{display:inline-block;padding:3px 8px;border-radius:999px;background:#f8edf0;color:#9e3d55;font-size:.76rem;font-weight:700}.ops-chip.urgent{background:#fff0da;color:#9b5912}\n.ops-search{display:flex;gap:8px;margin:18px 0}.ops-search input,#ops-case-dialog input,#ops-case-dialog textarea,#ops-case-dialog select,.ops-case select,.ops-case input,.ops-case textarea{border:1px solid #e7d7dc;border-radius:12px;padding:11px 12px;background:#fff;font:inherit}.ops-search input{flex:1;min-width:0}\n.ops-result button,.ops-case button{border:1px solid #e5cbd2;background:#fff;color:#ad3552;border-radius:999px;padding:8px 12px;font-weight:700}\n.ops-case{align-items:flex-start}.ops-case-controls{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px;max-width:55%}.ops-case-controls select{padding:7px}.ops-case-controls textarea{width:100%;min-height:48px}.ops-case-main{flex:1}.ops-case-main a{display:inline-block;margin:5px 0;color:#b62d4a;font-weight:700}.ops-case-controls button:disabled{opacity:.45;cursor:not-allowed}\n#ops-case-dialog,#ops-history-dialog{border:0;border-radius:22px;padding:24px;width:min(92vw,520px);box-shadow:0 25px 80px #28131966}#ops-case-dialog::backdrop,#ops-history-dialog::backdrop{background:#26171c99}\n#ops-case-dialog h2,#ops-history-dialog h2{margin:0 0 18px}#ops-case-dialog label{display:block;margin:12px 0;color:#5c454b;font-weight:700}#ops-case-dialog input,#ops-case-dialog textarea,#ops-case-dialog select{display:block;width:100%;margin-top:6px}.ops-dialog-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ops-dialog-actions{display:flex;justify-content:flex-end;gap:8px}.ops-dialog-actions button:first-child{border:0;background:#f5ecee;color:#6b4d55;border-radius:999px;padding:11px 19px}\n.ops-empty{color:#927e82;padding:16px 0}.ops-footnote{font-size:.78rem;color:#967f84;padding:12px}\n@media(max-width:760px){.ops-hero{padding:22px}.ops-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.ops-grid,.ops-alerts{grid-template-columns:1fr}.ops-case{display:block}.ops-case-controls{max-width:none;justify-content:flex-start;margin-top:10px}.ops-dialog-grid{grid-template-columns:1fr}}\nbody.ops-console main>.notice,body.ops-console #email-login-toggle,body.ops-console #cancel-login,body.ops-console main>details{display:none}\nbody.ops-console #status{border:0;padding:0;min-height:0;color:#8d727b;font-size:.8rem}\nbody.ops-console #status:empty{display:none}\n\n.product-table{width:100%;border-collapse:collapse;font-size:.85rem}.product-table th,.product-table td{text-align:left;padding:9px;border-bottom:1px solid #f2e6e8}.product-scroll{overflow:auto;max-height:320px}.product-chart{display:flex;align-items:end;gap:3px;height:150px;overflow:auto;padding-top:25px}.product-chart div{min-width:9px;flex:1;background:#e88da2;border-radius:4px 4px 0 0}.product-store{display:flex;flex-wrap:wrap;gap:12px;margin:14px 0}.product-store input{display:block;padding:9px;border:1px solid #ead6dd;border-radius:10px;max-width:160px}\n\n.product-table th{position:sticky;top:0;background:#fff7f8;z-index:1;white-space:nowrap}.product-table td{font-variant-numeric:tabular-nums}.ops-card[aria-label=利用分析] h3{margin-top:30px;padding-top:16px;border-top:1px solid #f3e5e9;color:#653942}.ops-card[aria-label=利用分析] select{border:1px solid #ead6dd;border-radius:12px;padding:10px;background:#fff7f8;color:#653942;font:inherit}.product-scroll+button,.ops-card[aria-label=利用分析] button{border:1px solid #ead6dd;border-radius:999px;padding:7px 14px;background:#fff7f8;color:#99475d}.ops-card[aria-label=利用分析] .ops-footnote{line-height:1.8}\n"},"/ads/ui.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\n\nconst adsPlatforms = {\n  x: { name: 'X', manager: 'https://ads.x.com/', scope: 'X内の配信。レポートは最大20キャンペーン、日付はUTC。' },\n  instagram: { name: 'Instagram', manager: 'https://adsmanager.facebook.com/', scope: 'Instagramへの配信実績のみ。配信操作はInstagram専用のキャンペーンに限ります。' },\n  tiktok: { name: 'TikTok', manager: 'https://ads.tiktok.com/', scope: 'TikTok Adsの広告アカウント全体。設定によってTikTok以外の配信面も含みます。' },\n};\nconst adsMessages = {\n  login_required: 'ログインし直してください。',\n  admin_required: 'Adsは管理者アカウントで利用できます。',\n  x_access_denied: '広告アカウントのAPI権限を確認してください。',\n  provider_access_denied: '広告アカウントのAPI権限を確認してください。',\n  x_rate_limit: '取得上限に達しました。少し時間をおいて更新してください。',\n  provider_rate_limit: '取得上限に達しました。少し時間をおいて更新してください。',\n  campaign_changed: '媒体側で設定が変わりました。更新してから操作してください。',\n  activation_blocked: '媒体側のキャンペーン種別・通貨・予算上限を確認してください。',\n  placement_blocked: 'Instagram専用の手動配置を確認できないため、この画面からは操作できません。',\n  write_unconfirmed: '変更結果を確認できません。再操作する前に、媒体側で最新の状態を確認してください。',\n  provider_not_connected: '広告APIが接続されていません。',\n  invalid_dates: '有効な日付を選び、期間を31日以内にしてください。',\n  unsupported_level: 'この媒体はキャンペーン単位で集計します。',\n  apple_report_unavailable: 'Appleの詳細レポートを取得できませんでした。接続を確認するか、期間を短くしてください。',\n};\n\nlet adsPlatform = 'all';\nlet adsRevision = 0;\nlet adsCursor = null;\nlet adsPending = null;\nlet adsReports = {};\nlet adsPrevious = {};\nlet adsAppleRows = [];\nlet adsAppleFeed = null;\nlet adsSort = 'spendMicros';\nlet adsMath;\nconst adsMathReady = import('/ads/insights.js');\nconst adsNames = {\n  spendMicros: '消化額', impressions: '表示', clicks: 'リンク・遷移クリック', ctr: 'CTR', cpc: 'CPC',\n  cpm: 'CPM', installs: '媒体計測インストール', cpi: '媒体CPI', results: '媒体CV', cpa: 'CPA',\n  videoViews: '動画再生', video25: '動画25%', video50: '動画50%', video75: '動画75%', videoComplete: '動画100%',\n};\nconst adsReportColumns = Object.keys(adsNames);\nconst adsMoneyKeys = ['spendMicros', 'cpc', 'cpm', 'cpi', 'cpa'];\nconst adsDash = '—';\nconst adsFormatted = new Intl.NumberFormat('ja-JP', { maximumFractionDigits: 2 });\n\nasync function adsRequest(platform, { query = {}, body } = {}) {\n  const path = '/ads/api/' + platform + '?' + new URLSearchParams(query);\n  const session = token;\n  let result, data;\n  try {\n    result = await fetch(path, {\n      method: body ? 'POST' : 'GET',\n      headers: { Authorization: 'Bearer ' + session, 'Content-Type': 'application/json' },\n      body: body ? JSON.stringify(body) : undefined,\n      cache: 'no-store', credentials: 'omit', signal: AbortSignal.timeout(26000),\n    });\n    data = await result.json();\n  } catch (error) {\n    if (body) throw Error(adsMessages.write_unconfirmed);\n    throw error;\n  }\n  if (session === token && result.status === 401) clear();\n  if (session === token && data.code === 'admin_required') clearAds();\n  if (!result.ok) throw Error(adsMessages[data.code] || '広告データを取得できませんでした。接続を確認して更新してください。');\n  return data;\n}\n\nfunction clearAds() {\n  adsRevision++;\n  $('ads-workspace').hidden = true;\n  $('main-heading').hidden = false;\n  for (const id of ['ads-campaigns', 'ads-report', 'ads-apple-results', 'ads-apple-feed', 'ads-diagnostics']) $(id).replaceChildren();\n  for (const id of ['ads-link-url', 'ads-target', 'ads-apple-file']) $(id).value = '';\n  for (const id of ['ads-link-status', 'ads-apple-status']) $(id).textContent = '';\n  $('ads-link-result').hidden = true;\n  $('ads-link-form').reset();\n  $('ads-apple-feed-status').textContent = '詳細レポートからキャンペーントークン別に取得します。';\n  adsReports = {};\n  adsPrevious = {};\n  adsAppleRows = [];\n  adsAppleFeed = null;\n  adsCursor = null;\n  adsPending = null;\n  if ($('ads-confirm').open) $('ads-confirm').close();\n}\n\nfunction adsMoney(value, currency) {\n  return value != null && currency ? new Intl.NumberFormat('ja-JP', {\n    style: 'currency', currency, currencyDisplay: 'code', maximumFractionDigits: 2,\n  }).format(value / 1e6) : adsDash;\n}\n\nfunction adsValue(key, value, currency) {\n  if (value == null) return adsDash;\n  if (adsMoneyKeys.includes(key)) return adsMoney(value, currency);\n  return adsFormatted.format(value) + (key === 'ctr' ? '%' : '');\n}\n\nfunction adsTable(headers, rows, label) {\n  const region = node('div');\n  region.className = 'ads-table-scroll';\n  region.tabIndex = 0;\n  region.setAttribute('role', 'region');\n  region.setAttribute('aria-label', label);\n  const table = node('table');\n  const head = node('thead');\n  const tr = node('tr');\n  for (const text of headers) {\n    const th = node('th', text);\n    th.scope = 'col';\n    tr.append(th);\n  }\n  head.append(tr);\n  const body = node('tbody');\n  for (const row of rows) {\n    const line = node('tr');\n    for (const value of row) line.append(node('td', value));\n    body.append(line);\n  }\n  table.append(head, body);\n  region.append(table);\n  return region;\n}\n\nfunction adsTotals(report) {\n  return adsMath.aggregate(report.rows, () => 'total')[0] || {};\n}\n\nfunction adsGrouped(report) {\n  return adsMath.aggregate(report.rows, row => row.id);\n}\n\nfunction adsMetrics(item, currency) {\n  return adsReportColumns.map(key => {\n    const value = adsValue(key, item[key], currency);\n    return value + (item[key] != null && item.missing?.[key] ? ' ※' : '');\n  });\n}\n\nfunction adsDelta(report, previous, key, now, before) {\n  if (!previous?.connected || previous.partial || report.partial || previous.currency !== report.currency ||\n      now.missing?.[key] || before.missing?.[key]) return '';\n  const points = key === 'ctr';\n  const delta = adsMath.metricChange(now[key], before[key], points);\n  return delta === null ? '' : (delta > 0 ? '+' : '') + adsFormatted.format(delta) + (points ? ' pt' : '%');\n}\n\nfunction adsReportInfo(platform, report) {\n  const source = adsPlatforms[platform];\n  if (report.error) return source.name + ' · ' + report.error;\n  if (!report.connected) return source.name + ' · 未接続';\n  if (!report.rows.length) return source.name + ' · 対象期間の配信データなし' + (report.partial ? '（一部取得）' : '');\n  return source.name + ' · ' + (report.partial ? '一部取得' : '取得済み') + ' · ' +\n    (report.timezone || '媒体のアカウント時刻') + (report.limitedMetrics ? ' · 基本指標のみ' : '');\n}\n\nfunction adsRenderReport() {\n  const out = $('ads-report');\n  out.replaceChildren();\n  const reports = Object.entries(adsReports);\n  const connected = reports.filter(([, report]) => report.connected);\n  const compare = Object.keys(adsPrevious).length > 0;\n  $('ads-connection').textContent = connected.length + ' / ' + reports.length + ' 媒体 接続';\n  $('ads-export').hidden = !connected.some(([, report]) => report.rows.length);\n  const previousPeriod = Object.values(adsPrevious).find(report => report.connected);\n  $('ads-report-status').textContent = reports.map(([platform, report]) => adsReportInfo(platform, report)).join('　/　') +\n    (compare ? previousPeriod ? '　前期 ' + previousPeriod.start + ' 〜 ' + previousPeriod.end : '　前期データなし' : '');\n  if (adsPlatform === 'all') {\n    $('ads-optimization').hidden = true;\n    if (!connected.length) return;\n    out.append(adsTable(['媒体', ...adsReportColumns.map(key => adsNames[key])],\n      connected.map(([platform, report]) => {\n        const total = adsTotals(report);\n        const previous = adsPrevious[platform];\n        const baseline = previous?.connected ? adsTotals(previous) : {};\n        return [adsPlatforms[platform].name + (report.partial ? '（一部）' : ''), ...adsMetrics(total, report.currency)\n          .map((value, index) => {\n            const delta = adsDelta(report, previous, adsReportColumns[index], total, baseline);\n            return delta ? value + ' (' + delta + ')' : value;\n          })];\n      }), '媒体別の実績'));\n    const note = node('p', '媒体ごとに計測条件が異なります。※は一部の値を取得できた項目です。');\n    note.className = 'ads-muted';\n    out.append(note);\n    return;\n  }\n  const report = adsReports[adsPlatform];\n  if (!report?.connected || !report.rows.length) {\n    $('ads-optimization').hidden = true;\n    return;\n  }\n  const totals = adsTotals(report);\n  const previous = adsPrevious[adsPlatform];\n  const baseline = previous?.connected ? adsTotals(previous) : {};\n  const kpis = node('div');\n  kpis.className = 'ads-kpis';\n  for (const key of ['spendMicros', 'impressions', 'clicks', 'ctr', 'installs', 'cpi']) {\n    const card = node('div');\n    card.append(node('span', adsNames[key]), node('strong', adsValue(key, totals[key], report.currency) +\n      (totals[key] != null && totals.missing?.[key] ? ' ※' : '')));\n    const delta = adsDelta(report, previous, key, totals, baseline);\n    if (delta) card.append(node('small', '前期比 ' + delta));\n    kpis.append(card);\n  }\n  out.append(kpis);\n  const toolbar = node('div');\n  toolbar.className = 'ads-heading';\n  const sort = node('select');\n  sort.setAttribute('aria-label', '並べ替え');\n  for (const [key, label] of Object.entries(adsNames)) {\n    const option = node('option', label + '順');\n    option.value = key;\n    sort.append(option);\n  }\n  sort.value = adsSort;\n  sort.addEventListener('change', () => { adsSort = sort.value; adsRenderReport(); out.querySelector('select')?.focus(); });\n  toolbar.append(node('h3', '広告実績'), sort);\n  const items = adsGrouped(report).sort((a, b) => (b[adsSort] ?? -1) - (a[adsSort] ?? -1));\n  out.append(toolbar, adsTable(['名前 / ID', ...adsReportColumns.map(key => adsNames[key])],\n    items.map(item => [item.name + ' / ' + item.key, ...adsMetrics(item, report.currency)]), '広告別の実績'));\n  const daily = adsMath.aggregate(report.rows, row => row.date).sort((a, b) => a.key.localeCompare(b.key));\n  const trend = node('details');\n  trend.className = 'ads-trend';\n  const max = Math.max(1, ...daily.map(item => item.spendMicros ?? 0));\n  const chart = node('div');\n  chart.className = 'ads-chart';\n  for (const item of daily) {\n    if (item.spendMicros == null || item.missing.spendMicros) continue;\n    const line = node('div');\n    const bar = node('progress');\n    bar.max = max;\n    bar.value = item.spendMicros;\n    bar.setAttribute('aria-label', item.key + 'の消化額');\n    line.append(node('span', item.key), bar, node('span', adsMoney(item.spendMicros, report.currency)));\n    chart.append(line);\n  }\n  trend.append(node('summary', '日別の推移'), chart,\n    adsTable(['日付', ...adsReportColumns.map(key => adsNames[key])],\n      daily.map(item => [item.key, ...adsMetrics(item, report.currency)]), '日別の実績'));\n  const notes = node('p', adsPlatforms[adsPlatform].scope + ' ※は一部の値を取得できた項目です。ダッシュは値がないか、比較できない項目です。');\n  notes.className = 'ads-muted';\n  out.append(trend, notes);\n  $('ads-optimization').hidden = false;\n  adsRenderDiagnostics();\n}\n\nfunction adsRenderDiagnostics() {\n  const report = adsReports[adsPlatform];\n  const out = $('ads-diagnostics');\n  out.replaceChildren();\n  if (!report?.rows?.length) return;\n  if (report.partial) {\n    out.append(node('p', '取得範囲が一部のため、分析を保留しています。期間を短くして再取得してください。'));\n    return;\n  }\n  const target = Number($('ads-target').value) * 1e6;\n  const hints = adsMath.diagnostics(adsGrouped(report), report.currency ? target : 0);\n  if (!hints.length) out.append(node('p', '現在の集計では、条件に該当する見直し候補はありません。'));\n  else for (const hint of hints) {\n    const card = node('article');\n    card.className = 'ads-row';\n    const key = hint.kind.toLowerCase();\n    card.append(node('strong', hint.name + ' · ' + hint.kind),\n      node('p', adsValue(key, hint.value, report.currency) + ' / 比較基準 ' + adsValue(key, hint.baseline, report.currency)),\n      node('p', hint.note));\n    out.append(card);\n  }\n}\n\nfunction adsDownload(filename, rows) {\n  const data = '\\uFEFF' + rows.map(row => row.map(adsMath.csvCell).join(',')).join('\\r\\n');\n  const url = URL.createObjectURL(new Blob([data], { type: 'text/csv;charset=utf-8' }));\n  const anchor = node('a');\n  anchor.href = url;\n  anchor.download = filename;\n  anchor.click();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n}\n\nfunction adsRenderApple() {\n  const out = $('ads-apple-results');\n  out.replaceChildren();\n  if (!adsAppleRows.length) return;\n  const rows = adsAppleRows.filter(entry => adsPlatform === 'all' || entry.platform === adsPlatform);\n  if (!rows.length) return;\n  out.append(adsTable(['媒体', 'キャンペーンID / トークン', '対象期間', '初回DL', 'D1', 'D7', 'D30', 'Apple基準CPI'],\n    rows.map(entry => {\n      const report = adsReports[entry.platform];\n      const matched = report?.connected && !report.partial && report.level === 'campaign' &&\n        report.start === entry.start && report.end === entry.end &&\n        adsGrouped(report).find(item => item.key === entry.id && !item.missing.spendMicros);\n      const expected = Math.round((Date.parse(entry.end) - Date.parse(entry.start)) / 86400000) + 1;\n      const fromApple = adsAppleFeed?.start === entry.start && adsAppleFeed.end === entry.end &&\n        adsAppleFeed.days.length === expected ? adsAppleFeed.rows.find(row => row.campaign === entry.campaign)?.downloads : null;\n      const downloads = fromApple ?? entry.downloads;\n      const cpi = adsMath.ratio(matched?.spendMicros, downloads);\n      return [adsPlatforms[entry.platform].name, entry.id + ' / ' + entry.campaign, entry.start + ' 〜 ' + entry.end,\n        adsValue('installs', downloads), ...entry.rates.map(rate => adsValue('ctr', rate)),\n        adsMoney(cpi, report?.currency)];\n    }), 'Appleのキャンペーン別計測'));\n}\n\nfunction adsConfirm(platform, item, accountId, next) {\n  adsPending = { platform, item: { ...item, status: next } };\n  const starts = next === 'ACTIVE';\n  $('ads-confirm-title').textContent = starts ? '広告の配信を開始' : '広告の配信を停止';\n  $('ads-confirm-summary').textContent = adsPlatforms[platform].name + ' / ' + accountId + ' / ' + item.name +\n    ' · 日額 ' + adsMoney(item.dailyMicros, item.currency) + ' · 総額 ' + adsMoney(item.totalMicros, item.currency);\n  $('ads-confirm-notice').textContent = starts ? '媒体の設定に沿って配信され、広告費が発生します。' : '媒体側でキャンペーンを停止します。';\n  $('ads-confirm-start').textContent = starts ? '予算を確認して開始' : '配信を停止';\n  $('ads-confirm').returnValue = '';\n  $('ads-confirm').showModal();\n}\n\nfunction adsRow(platform, item, accountId) {\n  const row = node('article');\n  row.className = 'ads-row ads-delivery-row';\n  row.dataset.campaignId = item.id;\n  const summary = node('div');\n  const state = { ACTIVE: '有効', PAUSED: '停止中', DRAFT: '下書き' }[item.status] || item.status;\n  summary.append(node('strong', item.name), node('p', state + ' · ' + item.id),\n    node('p', '日額 ' + adsMoney(item.dailyMicros, item.currency) + ' / 総額 ' + adsMoney(item.totalMicros, item.currency)));\n  row.append(summary);\n  const next = item.canActivate ? 'ACTIVE' : item.canPause || (platform === 'x' && item.status === 'ACTIVE' && item.updatedAt) ? 'PAUSED' : null;\n  if (next || item.needsReview) {\n    const button = node('button', item.needsReview ? '配信先を確認' : next === 'ACTIVE' ? '配信開始…' : '配信停止…');\n    button.type = 'button';\n    button.addEventListener('click', () => {\n      if (next) return adsConfirm(platform, item, accountId, next);\n      perform(async () => {\n        const stamp = adsRevision;\n        const { item: review } = await adsRequest(platform, { query: { view: 'review', id: item.id } });\n        if (stamp !== adsRevision) return;\n        row.replaceWith(adsRow(platform, review, accountId));\n        if (!review.scoped) status(adsMessages.placement_blocked);\n        else if (!review.canActivate && !review.canPause) status('Instagram専用です。配信開始には総額予算と配信権限が必要です。');\n      });\n    });\n    row.append(button);\n  }\n  return row;\n}\n\nasync function adsLoadDelivery(platform, stamp, append = false) {\n  const section = $('ads-delivery');\n  section.hidden = platform === 'all';\n  if (section.hidden) return;\n  const provider = adsPlatforms[platform];\n  const out = $('ads-campaigns');\n  $('ads-manager').href = provider.manager;\n  $('ads-delivery-note').textContent = provider.scope;\n  if (!append) out.replaceChildren(node('p', 'キャンペーンを取得しています…'));\n  $('ads-more').hidden = true;\n  try {\n    const result = await adsRequest(platform, { query: append ? { cursor: adsCursor } : {} });\n    if (stamp !== adsRevision) return;\n    if (!append) out.replaceChildren();\n    if (!result.connected) return out.append(node('p', '広告APIを接続するとキャンペーンが表示されます。'));\n    if (result.items.length) out.append(...result.items.map(item => adsRow(platform, item, result.accountId)));\n    else if (!append) out.append(node('p', '操作対象のキャンペーンがありません。'));\n    if (result.partial) out.append(node('p', '一部のキャンペーンを表示しています。残りは媒体の管理画面で確認できます。'));\n    adsCursor = result.next || null;\n    $('ads-more').hidden = !adsCursor;\n  } catch (error) {\n    if (stamp === adsRevision) out.replaceChildren(node('p', error.message));\n  }\n}\n\nasync function refreshAds() {\n  if (!token || !mfaComplete || Date.now() / 1000 >= expires) {\n    clear();\n    throw Error('Adsにログインし直してください。');\n  }\n  const stamp = ++adsRevision;\n  adsMath = await adsMathReady;\n  if (stamp !== adsRevision) return;\n  $('ads-workspace').hidden = false;\n  $('main-heading').hidden = true;\n  const form = $('ads-period');\n  const level = form.elements.level;\n  level.disabled = ['all', 'x'].includes(adsPlatform);\n  if (level.disabled) level.value = 'campaign';\n  const { start, end, compare } = form.elements;\n  const selected = adsPlatform === 'all' ? Object.keys(adsPlatforms) : [adsPlatform];\n  const current = adsPlatform;\n  adsReports = {};\n  adsPrevious = {};\n  $('ads-export').hidden = true;\n  $('ads-optimization').hidden = true;\n  $('ads-report').replaceChildren();\n  $('ads-report-status').textContent = '媒体から集計を取得しています…';\n  const dates = { start: start.value, end: end.value };\n  const before = compare.checked ? adsMath.previousPeriod(dates.start, dates.end) : null;\n  const getReport = async (platform, period) => {\n    try {\n      const result = await adsRequest(platform, { query: { view: 'report', ...period, level: level.value } });\n      return [platform, result];\n    } catch (error) {\n      return [platform, { error: error.message }];\n    }\n  };\n  const reports = Promise.all(selected.map(platform => getReport(platform, dates)));\n  const comparison = before ? Promise.all(selected.map(platform => getReport(platform, before))) : [];\n  const delivery = adsLoadDelivery(current, stamp);\n  const [results, preceding] = await Promise.all([reports, comparison]);\n  if (stamp === adsRevision) {\n    adsReports = Object.fromEntries(results);\n    adsPrevious = Object.fromEntries(preceding);\n    adsRenderReport();\n    adsRenderApple();\n  }\n  await delivery;\n}\n\nconst adsDate = days => new Date(Date.now() + days * 86400000).toISOString().slice(0, 10);\n$('ads-period').elements.start.value = adsDate(-7);\n$('ads-period').elements.end.value = adsDate(-1);\n$('ads-platforms').addEventListener('click', event => {\n  const next = event.target.closest('button')?.dataset.platform;\n  if (!next || next === adsPlatform) return;\n  adsPlatform = next;\n  $('ads-target').value = '';\n  for (const button of $('ads-platforms').querySelectorAll('button')) button.setAttribute('aria-pressed', button.dataset.platform === next);\n  refreshAds().catch(error => status(error.message));\n});\n$('ads-period').addEventListener('submit', event => {\n  event.preventDefault();\n  refreshAds().catch(error => status(error.message));\n});\n$('ads-target').addEventListener('input', adsRenderDiagnostics);\n$('ads-apple-fetch').addEventListener('click', async () => {\n  const button = $('ads-apple-fetch');\n  const stamp = generation;\n  const out = $('ads-apple-feed');\n  const message = $('ads-apple-feed-status');\n  const { start, end } = $('ads-period').elements;\n  const query = { start: start.value, end: end.value };\n  out.replaceChildren();\n  message.textContent = 'Appleの詳細レポートを確認中…';\n  button.disabled = true;\n  try {\n    const data = await adsRequest('apple', { query });\n    if (stamp !== generation) return;\n    if (data.status !== 'ok') {\n      const states = {\n        not_configured: 'Appleの分析APIが未接続です。',\n        request_required: 'Appleの継続レポートがまだ設定されていません。',\n        awaiting_reports: 'Appleの詳細レポートの生成待ちです。',\n      };\n      message.textContent = states[data.status] || 'Appleの集計はまだ利用できません。';\n      return;\n    }\n    adsAppleFeed = data;\n    adsRenderApple();\n    const expected = Math.round((Date.parse(data.end) - Date.parse(data.start)) / 86400000) + 1;\n    message.textContent = data.start + ' 〜 ' + data.end + ' · ' + data.days.length + '/' + expected +\n      '日分にデータあり。' + (data.days.length < expected ? ' 表示は取得できた日付分の集計です。' : '') +\n      (!data.rows.length ? ' 表示条件を満たすキャンペーンがありません。' : '');\n    if (data.rows.length) out.append(adsTable(['キャンペーントークン', '初回ダウンロード'],\n      data.rows.map(row => [row.campaign, adsFormatted.format(row.downloads)]), 'Appleの初回ダウンロード'));\n  } catch (error) {\n    if (stamp === generation) message.textContent = error.message;\n  } finally {\n    button.disabled = false;\n  }\n});\n$('ads-more').addEventListener('click', () => adsLoadDelivery(adsPlatform, adsRevision, true));\n$('ads-confirm').addEventListener('close', () => {\n  const change = adsPending;\n  adsPending = null;\n  if (!change || $('ads-confirm').returnValue !== 'confirm') return;\n  perform(async () => {\n    const stamp = adsRevision;\n    const { platform, item } = change;\n    const updated = await adsRequest(platform, { body: item });\n    if (stamp !== adsRevision) return;\n    const row = [...$('ads-campaigns').children].find(row => row.dataset.campaignId === item.id);\n    row?.replaceWith(adsRow(platform, updated.item, updated.accountId));\n    status(item.status === 'ACTIVE' ? '媒体でキャンペーンを有効にしました。' : '媒体でキャンペーンを停止しました。');\n  });\n});\n$('ads-export').addEventListener('click', () => {\n  if ($('ads-export').hidden) return;\n  const rows = [['platform', 'account_currency', 'timezone', 'coverage_partial', 'level', 'date', 'id', 'name', ...adsMath.keys]];\n  for (const [platform, report] of Object.entries(adsReports)) {\n    if (!report.connected) continue;\n    for (const row of report.rows) rows.push([platform, report.currency, report.timezone, report.partial,\n      report.level, row.date, row.id, row.name, ...adsMath.keys.map(key => key === 'spendMicros' && row[key] != null ? row[key] / 1e6 : row[key])]);\n  }\n  rows[0][8] = 'spend_in_account_currency';\n  adsDownload('mefrion-ads.csv', rows);\n});\n$('ads-apple-template').addEventListener('click', () => {\n  const url = URL.createObjectURL(new Blob([adsMath.appleColumns.join(',') + '\\r\\n'], { type: 'text/csv;charset=utf-8' }));\n  const anchor = node('a');\n  anchor.href = url;\n  anchor.download = 'mefrion-apple-campaign-template.csv';\n  anchor.click();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n});\n$('ads-apple-file').addEventListener('change', async event => {\n  const file = event.target.files[0];\n  if (!file) return;\n  const stamp = generation;\n  try {\n    if (file.size > 500_000) throw Error('500KB以下のCSVを指定してください。');\n    const rows = adsMath.parseAppleFile(await file.text());\n    if (stamp !== generation) return;\n    adsAppleRows = rows;\n    $('ads-apple-status').textContent = rows.length + '件のキャンペーンを読み込みました。';\n    adsRenderApple();\n  } catch (error) {\n    if (stamp === generation) $('ads-apple-status').textContent = error.message;\n  } finally {\n    event.target.value = '';\n  }\n});\n$('ads-link-form').addEventListener('submit', event => {\n  event.preventDefault();\n  const values = new FormData(event.currentTarget);\n  $('ads-link-result').hidden = true;\n  try {\n    const url = new URL(values.get('base'));\n    const campaign = values.get('campaign');\n    if (url.origin !== 'https://apps.apple.com' || url.username || url.password ||\n        !/\\/app\\/(?:[^/]+\\/)?id6825337314\\/?$/.test(url.pathname) ||\n        !/^\\d+$/.test(url.searchParams.get('pt') || '') || !url.searchParams.get('ct') ||\n        !/^[A-Za-z0-9_-]{1,40}$/.test(campaign)) throw Error();\n    const output = new URL(url.origin + url.pathname);\n    output.searchParams.set('pt', url.searchParams.get('pt'));\n    output.searchParams.set('ct', campaign);\n    output.searchParams.set('mt', '8');\n    $('ads-link-url').value = output.href;\n    $('ads-link-result').hidden = false;\n    $('ads-link-status').textContent = '広告ごとに異なる識別名を使ってください。';\n  } catch {\n    $('ads-link-status').textContent = 'MEFRIONのApp Store Connectで発行したキャンペーンリンクを入力してください。';\n  }\n});\n$('ads-copy').addEventListener('click', async () => {\n  try {\n    await navigator.clipboard.writeText($('ads-link-url').value);\n    $('ads-link-status').textContent = 'リンクをコピーしました。';\n  } catch {\n    $('ads-link-url').select();\n    $('ads-link-status').textContent = '選択したリンクをコピーしてください。';\n  }\n});\n"},"/ads/ui.css":{"type":"text/css; charset=utf-8","body":"body[data-console-panel=\"ads\"] { background: #f4f2fa; color: #211a36; }\nbody[data-console-panel=\"ads\"] main { width: min(100% - 2rem, 68rem); }\nbody[data-console-panel=\"ads\"] > header { background: #201638; color: #fff; }\nbody[data-console-panel=\"ads\"] > header a { color: #e2d5ff; }\nbody[data-console-panel=\"ads\"] #session > :not(#logout, #refresh),\nbody[data-console-panel=\"ads\"] #queue,\nbody[data-console-panel=\"ads\"] #seed-section,\nbody[data-console-panel=\"ads\"] #confirmation { display: none; }\nbody[data-console-panel=\"ads\"]:has(#ads-workspace:not([hidden])) main > .notice { display: none; }\n.ads-hero, .ads-card { border-radius: 1.25rem; padding: clamp(1.2rem, 4vw, 2.1rem); margin: 1rem 0; }\n.ads-hero { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; background: #272044; color: white; }\n.ads-hero h1 { color: inherit; margin: .1em 0; font-size: clamp(2.6rem, 8vw, 4.4rem); letter-spacing: -.07em; }\n.ads-hero p { margin: .25rem 0; }\n.ads-label { color: #7351b5; font-weight: 750; font-size: .75rem; letter-spacing: .15em; margin: 0; }\n.ads-hero .ads-label { color: #d9c8fa; }\n.ads-badge { background: #ffffff21; padding: .45rem .75rem; border-radius: 2rem; font-size: .8rem; white-space: nowrap; }\n.ads-card { background: white; border: 1px solid #e5dff0; }\n.ads-heading { display: flex; flex-wrap: wrap; gap: .6rem 1rem; align-items: center; justify-content: space-between; }\n.ads-heading h2 { margin: .35rem 0; }\n.ads-row { padding: 1rem 0; border-top: 1px solid #ece7f1; }\n.ads-row h3, .ads-row p { margin: 0 0 .4rem; }\n.ads-muted { color: #584f6a; font-size: .88rem; }\n#ads-link-result:not([hidden]) { display: flex; align-items: end; gap: .75rem; }\n#ads-link-result label { flex: 1; min-width: 0; }\n#ads-confirm { width: min(32rem, 90vw); border: 1px solid #ddd5e8; border-radius: 1rem; padding: 1.5rem; color: #211a36; }\n#ads-confirm::backdrop { background: #1a142b99; }\n.ads-dialog-actions { display: flex; flex-wrap: wrap; justify-content: end; gap: .75rem; }\nbody[data-console-panel=\"ads\"] main { width: min(100% - 2rem, 82rem); max-width: none; }\nbody[data-console-panel=\"ads\"] #ads-workspace { border: 0; padding: 0; background: transparent; margin: 0; }\n#ads-workspace { --ink: #22213c; --sub: #635d75; --line: #e7e3ef; --accent: #6344aa; }\n#ads-workspace button, #ads-confirm-start { color: white; background: #6141a4; }\n#ads-workspace button:disabled { color: #62586e; background: #ebe7f2; opacity: 1; }\n#ads-workspace a { color: #59378e; }\n.ads-hero {\n  background: radial-gradient(ellipse at 78% 120%, #6840b9 0%, transparent 61%), #231938;\n  padding-block: clamp(1.7rem, 5vw, 3.15rem);\n}\n.ads-hero h1 span { color: #bc9dff; }\n.ads-hero .ads-badge { border: 1px solid #ffffff37; }\n#ads-platforms { display: flex; flex-wrap: wrap; gap: .4rem; margin: 1.15rem 0; }\n#ads-platforms button { background: #fff; color: #533d76; border: 1px solid var(--line); }\n#ads-platforms button[aria-pressed=\"true\"] { background: #3f2c66; color: #fff; border-color: #3f2c66; }\n#ads-period { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) auto; align-items: end; gap: .8rem; }\n#ads-period > label { margin: 0; min-width: 0; }\n#ads-period > label > * { width: 100%; min-width: 0; margin: .25rem 0 0; }\n#ads-workspace select { font: inherit; background: #faf9fc; color: var(--ink); border: 1px solid #d8d0e3; border-radius: .45rem; padding: .55rem; }\n#ads-workspace input { border-color: #d8d0e3; }\n.ads-kpis { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: .65rem; margin: 1rem 0 1.5rem; }\n.ads-kpis > div { background: #f8f5fd; border: 1px solid #ede7f6; border-radius: .8rem; padding: .8rem; }\n.ads-kpis span { display: block; color: var(--sub); font-size: .79rem; line-height: 1.4; }\n.ads-kpis strong { display: block; margin: .25rem 0 0; font-size: clamp(1rem, 2vw, 1.45rem); overflow-wrap: anywhere; }\n.ads-table-scroll { overflow: auto; border: 1px solid var(--line); border-radius: .75rem; max-height: 29rem; }\n.ads-table-scroll table { border-collapse: separate; border-spacing: 0; width: 100%; font-variant-numeric: tabular-nums; font-size: .86rem; }\n.ads-table-scroll :is(th, td) { text-align: end; padding: .64rem .76rem; white-space: nowrap; border-bottom: 1px solid var(--line); }\n.ads-table-scroll :is(th, td):first-child { text-align: start; position: sticky; left: 0; background: white; min-width: 6rem; white-space: normal; max-width: 15rem; overflow-wrap: anywhere; }\n.ads-table-scroll th { background: #f5f0fa; color: var(--ink); position: sticky; top: 0; z-index: 1; }\n.ads-table-scroll th:first-child { background: #f5f0fa; z-index: 2; }\n.ads-table-scroll tr:last-child td { border-bottom: 0; }\n.ads-table-scroll tr:hover td { background: #fbf9fe; }\n.ads-trend { margin-top: 1.1rem; }\n.ads-trend summary { font-weight: 700; padding: .35rem 0; cursor: pointer; }\n.ads-chart { margin: .8rem 0; display: grid; gap: .25rem; }\n.ads-chart > div { display: grid; grid-template-columns: 6.5rem minmax(2rem, 1fr) minmax(5rem, auto); align-items: center; gap: .6rem; font-size: .8rem; }\n.ads-chart progress { width: 100%; accent-color: var(--accent); height: .7rem; }\n.ads-columns { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.2rem; margin-bottom: .7rem; }\n.ads-columns > div { background: #f9f7fc; padding: .85rem 1rem; border-radius: .75rem; }\n.ads-columns h3 { margin-top: 0; }\n.ads-columns input { width: 100%; }\n.ads-delivery-row { display: flex; justify-content: space-between; align-items: center; gap: .8rem; }\n.ads-delivery-row > div { min-width: 0; overflow-wrap: anywhere; }\n.ads-delivery-row p { color: var(--sub); font-size: .88rem; }\n#ads-target-label { margin: 0; }\n#ads-target { max-width: 12rem; }\n#ads-confirm form { margin: 0; }\n@media (max-width: 52rem) {\n  .ads-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }\n}\n@media (max-width: 38rem) {\n  body[data-console-panel=\"ads\"] main { width: calc(100% - 1rem); }\n  .ads-hero { flex-direction: column; }\n  #ads-period { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .ads-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .ads-columns { grid-template-columns: 1fr; }\n  .ads-table-scroll :is(th, td):first-child { max-width: 7rem; }\n}\n#ads-period .ads-compare { grid-column: 1 / -1; display: flex; align-items: center; gap: .5rem; }\n#ads-period .ads-compare input { width: 1.1rem; height: 1.1rem; margin: 0; accent-color: var(--accent); }\n.ads-kpis small { color: #51427b; font-size: .78rem; }\nbody[data-console-panel=\"ads\"] #session button { background: #6141a4; }\n"},"/ads/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>Ads｜MEFRION</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><link rel=\"stylesheet\" href=\"/ads/ui.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/ads/ui.js\" defer></script><body data-console-panel=\"ads\"><header><span>MEFRION / Ads</span><a href=\"/console/\">運営画面へ</a></header><main><h1 id=\"main-heading\">Ads</h1><p class=\"notice\">MEFRIONの広告管理。管理者アカウントと二段階認証でログインしてください。</p><form id=\"login\"><label>運営専用のメールアドレス<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営専用のメールアドレス<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"overview-nav\" type=\"button\">ホーム</button><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><button id=\"content-nav\" type=\"button\">投稿の確認</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">広告を更新</button><button id=\"logout\">ログアウト</button></div><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section><section id=\"ads-workspace\" hidden aria-labelledby=\"ads-title\">\n <div class=\"ads-hero\">\n  <div><p class=\"ads-label\">MEFRION / ADVERTISING</p><h1 id=\"ads-title\">Ads<span>.</span></h1><p>配信状況とアプリの獲得成果を、ひとつの画面で。</p></div>\n  <span id=\"ads-connection\" class=\"ads-badge\" role=\"status\">接続を確認中</span>\n </div>\n <nav id=\"ads-platforms\" aria-label=\"広告媒体\">\n  <button type=\"button\" data-platform=\"all\" aria-pressed=\"true\">全媒体</button>\n  <button type=\"button\" data-platform=\"x\" aria-pressed=\"false\">X</button>\n  <button type=\"button\" data-platform=\"instagram\" aria-pressed=\"false\">Instagram</button>\n  <button type=\"button\" data-platform=\"tiktok\" aria-pressed=\"false\">TikTok</button>\n </nav>\n <section class=\"ads-card\" aria-labelledby=\"ads-report-title\">\n  <div class=\"ads-heading\">\n   <div><p class=\"ads-label\">PERFORMANCE</p><h2 id=\"ads-report-title\">配信レポート</h2></div>\n   <button id=\"ads-export\" type=\"button\" hidden>CSVを出力</button>\n  </div>\n  <form id=\"ads-period\">\n   <label>開始日<input type=\"date\" name=\"start\" required></label>\n   <label>終了日<input type=\"date\" name=\"end\" required></label>\n   <label>集計単位<select name=\"level\"><option value=\"campaign\">キャンペーン</option><option value=\"adgroup\">広告セット・広告グループ</option><option value=\"ad\">広告</option></select></label>\n   <button type=\"submit\">適用</button>\n   <label class=\"ads-compare\"><input type=\"checkbox\" name=\"compare\">同じ長さの直前期間と比較する</label>\n  </form>\n  <p id=\"ads-report-status\" class=\"ads-muted\" role=\"status\"></p>\n  <div id=\"ads-report\"></div>\n </section>\n <section id=\"ads-optimization\" class=\"ads-card\" aria-labelledby=\"ads-optimization-title\" hidden>\n  <div class=\"ads-heading\"><div><p class=\"ads-label\">OPTIMIZATION</p><h2 id=\"ads-optimization-title\">改善のヒント</h2></div>\n   <label id=\"ads-target-label\">目標インストール単価<input id=\"ads-target\" type=\"number\" min=\"0\" max=\"999999999\" step=\"0.01\" placeholder=\"任意\"></label>\n  </div>\n  <p class=\"ads-muted\">同じ媒体・期間の実績を基準に比較します。CTRは1,000表示以上、目標CPIは20インストール以上の広告が対象です。</p>\n  <div id=\"ads-diagnostics\" aria-live=\"polite\"></div>\n </section>\n <section id=\"ads-delivery\" class=\"ads-card\" aria-labelledby=\"ads-campaigns-title\" hidden>\n  <div class=\"ads-heading\">\n   <div><p class=\"ads-label\">DELIVERY CONTROL</p><h2 id=\"ads-campaigns-title\">キャンペーン管理</h2></div>\n   <a id=\"ads-manager\" target=\"_blank\" rel=\"noopener noreferrer\">広告マネージャー ↗</a>\n  </div>\n  <p id=\"ads-delivery-note\" class=\"ads-muted\"></p>\n  <div id=\"ads-campaigns\" aria-live=\"polite\"></div>\n  <button id=\"ads-more\" type=\"button\" hidden>次のキャンペーンを表示</button>\n </section>\n <section class=\"ads-card\" aria-labelledby=\"ads-link-title\">\n  <div class=\"ads-heading\">\n   <div><p class=\"ads-label\">APP STORE ATTRIBUTION</p><h2 id=\"ads-link-title\">初回ダウンロード・継続率</h2></div>\n   <a href=\"https://appstoreconnect.apple.com/apps/6825337314/analytics\" target=\"_blank\" rel=\"noopener noreferrer\">App Store Connect ↗</a>\n  </div>\n  <div class=\"ads-columns\">\n   <div>\n    <h3>広告ごとの計測リンク</h3>\n    <form id=\"ads-link-form\">\n     <label>既存のキャンペーンリンク<input name=\"base\" type=\"url\" required placeholder=\"https://apps.apple.com/…?pt=…&amp;ct=…\"></label>\n     <label>広告の識別名<input name=\"campaign\" required maxlength=\"40\" pattern=\"[A-Za-z0-9_\\-]+\" placeholder=\"ig_sokkuri_reels_01\"></label>\n     <button type=\"submit\">計測リンクを作る</button>\n    </form>\n    <div id=\"ads-link-result\" hidden>\n     <label>広告に設定するURL<input id=\"ads-link-url\" readonly></label>\n     <button id=\"ads-copy\" type=\"button\">コピー</button>\n    </div>\n    <p id=\"ads-link-status\" role=\"status\"></p>\n   </div>\n   <div>\n    <h3>Appleの集計を取り込む</h3>\n    <p class=\"ads-muted\">Appleのキャンペーン別集計をテンプレートに記入します。非表示の数値は空欄で。読み込んだ集計はこのセッションだけに表示します。</p>\n    <button id=\"ads-apple-template\" type=\"button\">CSVテンプレート</button>\n    <label>集計CSV<input id=\"ads-apple-file\" type=\"file\" accept=\".csv,text/csv\"></label>\n    <p id=\"ads-apple-status\" class=\"ads-muted\" role=\"status\"></p>\n   </div>\n  </div>\n  <div class=\"ads-heading\"><h3>Appleの初回ダウンロード</h3>\n   <button type=\"button\" id=\"ads-apple-fetch\">表示期間のデータを取得</button>\n  </div>\n  <p id=\"ads-apple-feed-status\" class=\"ads-muted\" role=\"status\">詳細レポートからキャンペーントークン別に取得します。</p>\n  <div id=\"ads-apple-feed\"></div>\n  <div id=\"ads-apple-results\"></div>\n  <p class=\"ads-muted\">Appleの初回ダウンロード・継続率と、媒体の計測インストールはそれぞれの基準で集計されます。CSVで広告とAppleのトークンをひも付けると、広告費と期間が一致するキャンペーンのApple基準CPIを表示します。</p>\n </section>\n</section>\n<dialog id=\"ads-confirm\" aria-labelledby=\"ads-confirm-title\">\n <form method=\"dialog\">\n  <h2 id=\"ads-confirm-title\"></h2>\n  <p id=\"ads-confirm-summary\"></p>\n  <p id=\"ads-confirm-notice\"></p>\n  <div class=\"ads-dialog-actions\"><button value=\"cancel\">キャンセル</button><button id=\"ads-confirm-start\" value=\"confirm\">確認</button></div>\n </form>\n</dialog>\n</main></body></html>\n"},"/ads/insights.js":{"type":"application/javascript; charset=utf-8","body":"export const keys = ['spendMicros', 'impressions', 'clicks', 'installs', 'results', 'videoViews', 'video25', 'video50', 'video75', 'videoComplete'];\nconst known = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;\nexport const ratio = (numerator, denominator, scale = 1) =>\n  known(numerator) && known(denominator) && denominator > 0 ? numerator / denominator * scale : null;\n\nexport function previousPeriod(start, end) {\n  const day = 86400000;\n  const first = Date.parse(start), last = Date.parse(end);\n  if (!Number.isFinite(first) || !Number.isFinite(last) || last < first) return null;\n  const date = time => new Date(time).toISOString().slice(0, 10);\n  return { start: date(first - (last - first) - day), end: date(first - day) };\n}\n\nexport function metricChange(current, previous, percentagePoints = false) {\n  if (!known(current) || !known(previous)) return null;\n  return percentagePoints ? current - previous : previous > 0 ? (current - previous) / previous * 100 : null;\n}\n\nexport function aggregate(rows, group) {\n  const groups = new Map();\n  for (const row of rows) {\n    const key = group(row);\n    if (!groups.has(key)) groups.set(key, { key, name: row.name, rows: 0, missing: {} });\n    const target = groups.get(key);\n    target.rows++;\n    for (const metric of keys) {\n      const value = row[metric];\n      if (known(value)) target[metric] = (target[metric] ?? 0) + value;\n      else target.missing[metric] = (target.missing[metric] || 0) + 1;\n    }\n  }\n  return [...groups.values()].map(item => {\n    const complete = key => item.missing[key] ? null : item[key];\n    return { ...item,\n      ctr: ratio(complete('clicks'), complete('impressions'), 100),\n      cpc: ratio(complete('spendMicros'), complete('clicks')),\n      cpm: ratio(complete('spendMicros'), complete('impressions'), 1000),\n      cpi: ratio(complete('spendMicros'), complete('installs')),\n      cpa: ratio(complete('spendMicros'), complete('results')),\n    };\n  });\n}\n\n// Descriptive diagnostics using aggregate data from the same platform and period.\nexport function diagnostics(items, targetMicros) {\n  const eligible = items.filter(item => item.impressions >= 1000 && item.ctr !== null);\n  const out = [];\n  for (const item of items) {\n    if (targetMicros > 0 && item.cpi > targetMicros * 1.25 && item.installs >= 20) {\n      out.push({ name: item.name, kind: 'CPI', value: item.cpi, baseline: targetMicros,\n        note: '獲得単価が目標を25%以上超えています。配信先とストア導線を見直す候補です。' });\n    }\n    const peers = eligible.filter(peer => peer !== item);\n    if (!eligible.includes(item) || peers.length < 2) continue;\n    const impressions = peers.reduce((sum, peer) => sum + peer.impressions, 0);\n    const clicks = peers.reduce((sum, peer) => sum + peer.clicks, 0);\n    const baseline = clicks / impressions * 100;\n    if (clicks >= 30 && item.ctr < baseline * 0.7) {\n      out.push({ name: item.name, kind: 'CTR', value: item.ctr, baseline,\n        note: '他の配信よりクリック率が低めです。動画の冒頭や見出しを変えるテスト候補です。' });\n    }\n  }\n  return out.slice(0, 12);\n}\n\nexport function csvCell(value) {\n  if (value == null) return '';\n  const safe = typeof value === 'string' && (/^[\\s\\uFEFF]*[=+\\-@]/u.test(value) || /^[\\t\\r\\n]/.test(value)) ? \"'\" + value : String(value);\n  return '\"' + safe.replaceAll('\"', '\"\"') + '\"';\n}\n\nexport const appleColumns = ['platform','campaign_id','campaign_token','start','end','first_downloads','d1_pct','d7_pct','d30_pct'];\n\nexport function parseAppleFile(raw) {\n  const lines = raw.replace(/^\\uFEFF/, '').trim().split(/\\r?\\n/);\n  if (lines.length > 1001 || lines.shift()?.trim() !== appleColumns.join(',')) throw Error('列名をテンプレートと同じにしてください。');\n  const date = value => /^\\d{4}-\\d{2}-\\d{2}$/.test(value) && Number.isFinite(Date.parse(value)) &&\n    new Date(value).toISOString().slice(0, 10) === value;\n  const value = (input, pattern) => {\n    if (!input) return null;\n    if (!pattern.test(input) || !known(Number(input))) throw Error('ダウンロード数と継続率を数値で入力してください。');\n    return Number(input);\n  };\n  const unique = new Set();\n  return lines.map((line, index) => {\n    const fields = line.split(',').map(field => field.trim());\n    const [platform, id, campaign, start, end, downloads, d1, d7, d30] = fields;\n    if (fields.length !== appleColumns.length || !['x', 'instagram', 'tiktok'].includes(platform) ||\n        !/^[a-z0-9]{1,32}$/i.test(id) || !/^[a-zA-Z0-9_-]{1,40}$/.test(campaign) ||\n        !date(start) || !date(end) || start > end) throw Error((index + 2) + '行目の媒体、ID、トークン、期間を確認してください。');\n    const rates = [d1, d7, d30].map(rate => value(rate, /^\\d{1,3}(\\.\\d{1,4})?$/));\n    if (rates.some(rate => rate > 100)) throw Error('継続率は0〜100で入力してください。');\n    const key = [platform, id, start, end].join(':');\n    const sourceKey = ['apple', campaign, start, end].join(':');\n    if (unique.has(key) || unique.has(sourceKey)) throw Error('同じキャンペーン・期間の行が重複しています。');\n    unique.add(key);\n    unique.add(sourceKey);\n    return { platform, id, campaign, start, end, downloads: value(downloads, /^\\d{1,12}$/), rates };\n  });\n}\n"}};
const BASE="https://pbnimpqrthvznbwewtcf.supabase.co";
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const common={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY"};
export default {async fetch(request,env={}){
 if(new URL(request.url).pathname.startsWith("/internal-backup/"))return backupHandler(request,env);
 const url=new URL(request.url);
 if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405,headers:common});
 let pathname=url.pathname;
 if(pathname==="/")pathname="/index.html";
 if(pathname==="/console")pathname="/console/";
 if(pathname==="/ads")pathname="/ads/";
 if(pathname==="/privacy")pathname="/privacy.html";
 if(pathname==="/terms")pathname="/terms.html";
 if(PAGES[pathname])return new Response(request.method==="HEAD"?null:PAGES[pathname].body,{headers:{...common,"Content-Type":PAGES[pathname].type,...(pathname.startsWith("/console")||pathname.startsWith("/ads/")?{"X-Robots-Tag":"noindex, nofollow","Content-Security-Policy":`default-src 'self'; connect-src 'self' ${BASE}; img-src 'self' blob: data:; media-src 'self' blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'`}:{})}});
 if(pathname==="/healthz")return new Response(JSON.stringify({ok:true,service:"MEFRION public pages"}),{headers:{...common,"Content-Type":"application/json"}});
 const match=pathname.match(/^\/(cloud-shared|cloud-development-shared)\/([0-9a-f-]+)$/i);
 if(match&&uuid.test(match[2])){
  const sharedBase=match[1]==="cloud-shared"?BASE:"https://pmrvzpuznwzuejbuhaqm.supabase.co";
  try{
   const upstream=await fetch(sharedBase+"/functions/v1/shared-page?post="+encodeURIComponent(match[2]),{headers:{"Cache-Control":"no-store"},signal:AbortSignal.timeout(15000)});
   if(![200,404,503].includes(upstream.status))return new Response("共有を読み込めません。もう一度お試しください。",{status:503,headers:common});
   const body=await upstream.text();
   if(body.length>500000)return new Response("共有を読み込めません。",{status:503,headers:common});
   return new Response(request.method==="HEAD"?null:body,{status:upstream.status,headers:{...common,"Content-Type":"text/html; charset=utf-8","Content-Security-Policy":`default-src 'none'; style-src 'unsafe-inline'; img-src ${sharedBase}; frame-ancestors 'none'; base-uri 'none'; form-action 'none'`}});
  }catch{return new Response("共有を読み込めません。もう一度お試しください。",{status:503,headers:common});}
 }
 return new Response("ページが見つかりません。",{status:404,headers:{...common,"Content-Type":"text/plain; charset=utf-8"}});
}};
